private java.lang.String checkImmunizations(long pid) throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.lang.String reason = "";
    java.util.List<edu.ncsu.csc.itrust.beans.ProcedureBean> procs = this.patientDAO.getProcedures(pid);
    edu.ncsu.csc.itrust.beans.PatientBean patient = this.patientDAO.getPatient(pid);
    java.util.Date patientDOB = patient.getDateOfBirth();
    edu.ncsu.csc.itrust.enums.Gender gen = patient.getGender();
    int hepB = 0;
    long hepBTime = 0;
    int rota = 0;
    long rotaTime = 0;
    int diptet = 0;
    long deptetTime = 0;
    int haemoflu = 0;
    long haemofluTime = 0;
    long haemofluTimeFirst = 0;
    int pneumo = 0;
    long pneumoTime = 0;
    long pneumofluTimeFirst = 0;
    int polio = 0;
    long polioTime = 0;
    int measles = 0;
    long measlesTime = 0;
    int varicella = 0;
    long varicellaTime = 0;
    int hepA = 0;
    long hepATime = 0;
    int hpv = 0;
    long hpvTime = 0;
    for (edu.ncsu.csc.itrust.beans.ProcedureBean proc : procs) {
        java.lang.String cpt = proc.getCPTCode();
        // Hep B (90371)
        if (cpt.equals("90371")) {
            hepB++;
            hepBTime = proc.getDate().getTime();
        } else if (cpt.equals("90681")) {
            rota++;
            rotaTime = proc.getDate().getTime();
        } else if (cpt.equals("90696")) {
            diptet++;
            deptetTime = proc.getDate().getTime();
        } else if (cpt.equals("90645")) {
            if (0 == haemoflu) {
                haemofluTimeFirst = proc.getDate().getTime();
            }
            haemoflu++;
            haemofluTime = proc.getDate().getTime();
        } else if (cpt.equals("90669")) {
            if (0 == pneumo) {
                pneumofluTimeFirst = proc.getDate().getTime();
            }
            pneumo++;
            pneumoTime = proc.getDate().getTime();
        } else if (cpt.equals("90712")) {
            polio++;
            polioTime = proc.getDate().getTime();
        } else if (cpt.equals("90707")) {
            measles++;
            measlesTime = proc.getDate().getTime();
        } else if (cpt.equals("90396")) {
            varicella++;
            varicellaTime = proc.getDate().getTime();
        } else if (cpt.equals("90633")) {
            hepA++;
            hepATime = proc.getDate().getTime();
        } else if (cpt.equals("90649")) {
            hpv++;
            hpvTime = proc.getDate().getTime();
        }
    }
    if (3 > hepB) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testHepB(hepB, patientDOB, hepBTime);
    }
    if (3 > rota) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testRotaVirus(rota, patientDOB, rotaTime);
    }
    if (6 > diptet) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testDipTet(diptet, patientDOB, deptetTime);
    }
    if (3 > haemoflu) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testHaemoFlu(haemoflu, patientDOB, haemofluTime, haemofluTimeFirst);
    }
    if (4 > pneumo) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testPneumo(pneumo, patientDOB, pneumoTime, pneumofluTimeFirst);
    }
    if (3 > polio) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testPolio(polio, patientDOB, polioTime);
    }
    if (2 > measles) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testMeasles(measles, patientDOB, measlesTime);
    }
    if (2 > varicella) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testVaricella(varicella, patientDOB, varicellaTime);
    }
    if (2 > hepA) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testHepA(hepA, patientDOB, hepATime);
    }
    if ((3 > hpv) && gen.getName().equals("Female")) {
        reason += edu.ncsu.csc.itrust.action.GetVisitRemindersAction.testHPV(hpv, patientDOB, hpvTime);
    }
    if (reason.length() > 2) {
        return reason.substring(0, reason.length() - 2);
    }
    return reason;
}

