public java.util.List<edu.ncsu.csc.itrust.beans.forms.VisitReminderReturnForm> getDiagnosedVisitNeeders(long hcpid) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    java.sql.ResultSet rs = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT  hid, MID, lastName, firstName, phone, ICDcode, visitDate FROM " + ((((((((((((((((((((((((((((((((((((((((((((("(SELECT DISTINCT " + "  ? as hid, ") + "  p.MID as MID, ") + "  p.lastName, ") + "  p.firstName, ") + "  p.phone, ") + "  ovd.ICDcode ") + " FROM ") + "  patients p, ") + "  officevisits ov, ") + "  ovdiagnosis ovd ") + " WHERE ") + "  p.MID = ov.PatientID ") + " AND ") + "  p.DateOfDeath is null ") + " AND ") + "  ov.ID = ovd.VisitID ") + " AND ") + "  (") + "    ovd.ICDCode BETWEEN ? AND ? ") + "   OR ") + "    ovd.ICDCode BETWEEN ? AND ? ") + "   OR ") + "    ovd.ICDCode BETWEEN ? AND ? ") + "  ) ") + " AND ") + "  p.MID NOT IN ") + "   ( ") + "    SELECT p.MID FROM patients p, officevisits ov ") + "    WHERE ") + "     p.MID = ov.PatientID ") + "	 AND ") + "     ov.visitDate > DATE_SUB(CURDATE(), INTERVAL 1 YEAR) ") + "   ) ") + ") a ") + " INNER JOIN ") + "  ( ") + "   SELECT p.MID, MAX(ov.visitDate) as visitDate FROM patients p, officevisits ov ") + "   WHERE ") + "    p.MID = ov.PatientID ") + "   GROUP BY ") + "    p.mid ") + "  ) b ") + " USING(MID) ") + "ORDER BY ") + " lastName, firstName, MID, ICDcode "));
        ps.setLong(1, hcpid);
        ps.setFloat(2, 250.0F);
        ps.setFloat(3, 250.99F);
        ps.setFloat(4, 390.0F);
        ps.setFloat(5, 459.99F);
        ps.setFloat(6, 493.0F);
        ps.setFloat(7, 493.99F);
        rs = ps.executeQuery();
        java.util.List<edu.ncsu.csc.itrust.beans.forms.VisitReminderReturnForm> patients = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.forms.VisitReminderReturnForm>();
        edu.ncsu.csc.itrust.beans.forms.VisitReminderReturnForm temp = null;
        edu.ncsu.csc.itrust.beans.loaders.VisitReminderReturnFormLoader loader = new edu.ncsu.csc.itrust.beans.loaders.VisitReminderReturnFormLoader();
        long lastId = -1;
        while (rs.next()) {
            if (lastId == rs.getLong(2)) {
                patients.get(patients.size() - 1).addVisitFlag(new edu.ncsu.csc.itrust.beans.VisitFlag(edu.ncsu.csc.itrust.beans.VisitFlag.DIAGNOSED, rs.getString(6)));
            } else {
                lastId = rs.getLong(2);
                temp = loader.loadSingle(rs);
                temp.addVisitFlag(new edu.ncsu.csc.itrust.beans.VisitFlag(edu.ncsu.csc.itrust.beans.VisitFlag.DIAGNOSED, rs.getString(6)));
                temp.addVisitFlag(new edu.ncsu.csc.itrust.beans.VisitFlag(edu.ncsu.csc.itrust.beans.VisitFlag.LAST_VISIT, rs.getString(7)));
                patients.add(temp);
            }
        } 
        rs.close();
        return patients;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

