private edu.ncsu.csc.itrust.beans.HealthRecord transferForm(long pid, edu.ncsu.csc.itrust.beans.forms.HealthRecordForm form) throws edu.ncsu.csc.itrust.exception.FormValidationException {
    edu.ncsu.csc.itrust.beans.HealthRecord record = new edu.ncsu.csc.itrust.beans.HealthRecord();
    record.setPatientID(pid);
    record.setPersonnelID(super.getHcpid());
    record.setBloodPressureD(java.lang.Integer.valueOf(form.getBloodPressureD()));
    record.setBloodPressureN(java.lang.Integer.valueOf(form.getBloodPressureN()));
    record.setCholesterolHDL(java.lang.Integer.valueOf(form.getCholesterolHDL()));
    record.setCholesterolLDL(java.lang.Integer.valueOf(form.getCholesterolLDL()));
    record.setCholesterolTri(java.lang.Integer.valueOf(form.getCholesterolTri()));
    if ((record.getTotalCholesterol() < 100) || (record.getTotalCholesterol() > 600)) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException("Total cholesterol must be in [100,600]");
    }
    record.setHeight(java.lang.Double.valueOf(form.getHeight()));
    record.setWeight(java.lang.Double.valueOf(form.getWeight()));
    record.setSmoker(java.lang.Integer.valueOf(form.getIsSmoker()));
    record.setHouseholdSmokingStatus(java.lang.Integer.valueOf(form.getHouseholdSmokingStatus()));
    return record;
}

