    java.lang.String stmt = "SELECT " + ((((((((((((((("CONCAT(psender.firstName,' ',psender.lastName) AS senderName, " + "CONCAT(preceiver.firstName,' ',preceiver.lastName) AS receiverName, ") + "referrals.*, ") + "officevisits.visitDate, ") + "CONCAT(patients.firstName,' ',patients.lastName) AS patientName ") + "FROM ") + "referrals, ") + "personnel AS psender, ") + "personnel AS preceiver, ") + "patients, ") + "officevisits ") + "WHERE ") + "referrals.SenderID=psender.mid ") + "AND referrals.ReceiverID=preceiver.mid ") + "AND referrals.PatientID=patients.mid ") + "AND referrals.ovid=officevisits.id ");
    stmt += java.lang.String.format("AND %s = ? ", this.getUserField());
    stmt += this.buildSort(sortField, dir);
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement(stmt);
        ps.setLong(1, this.getUserId());
        java.sql.ResultSet rs = ps.executeQuery();
        java.util.List<edu.ncsu.csc.itrust.beans.VerboseReferralBean> loadlist = this.verboseLoader.loadList(rs);
        rs.close();
        ps.close();
        return loadlist;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
