@java.lang.Override
public int hashCode() {
    final int prime = 31;
    int result = 1;
    result = (prime * result) + this.bloodPressureD;
    result = (prime * result) + this.bloodPressureS;
    result = (prime * result) + (this.dateVisit == null ? 0 : this.dateVisit.hashCode());
    result = (prime * result) + (this.deliveryType == null ? 0 : this.deliveryType.hashCode());
    result = (prime * result) + (this.edd == null ? 0 : this.edd.hashCode());
    result = (prime * result) + this.fhr;
    long temp;
    temp = java.lang.Double.doubleToLongBits(this.fhu);
    result = (prime * result) + ((int) (temp ^ (temp >>> 32)));
    temp = java.lang.Double.doubleToLongBits(this.hoursInLabor);
    result = (prime * result) + ((int) (temp ^ (temp >>> 32)));
    result = (prime * result) + (this.lmp == null ? 0 : this.lmp.hashCode());
    result = (prime * result) + ((int) (this.mid ^ (this.mid >>> 32)));
    result = (prime * result) + ((int) (this.oid ^ (this.oid >>> 32)));
    result = (prime * result) + ((int) (this.pregId ^ (this.pregId >>> 32)));
    result = (prime * result) + (this.pregnancyStatus == null ? 0 : this.pregnancyStatus.hashCode());
    result = (prime * result) + (this.weeksPregnant == null ? 0 : this.weeksPregnant.hashCode());
    temp = java.lang.Double.doubleToLongBits(this.weight);
    result = (prime * result) + ((int) (temp ^ (temp >>> 32)));
    result = (prime * result) + this.yearConception;
    return result;
}

