public java.util.List<java.lang.String> parseLOINCFile(java.io.InputStream data, boolean ignoreDupData) throws edu.ncsu.csc.itrust.exception.DBException {
    java.util.ArrayList<java.lang.String> results = new java.util.ArrayList<java.lang.String>();
    java.io.BufferedReader buf;
    try {
        buf = new java.io.BufferedReader(new java.io.InputStreamReader(data, "UTF-8"));
        java.lang.String line = null;
        int linesInserted = 0;
        int dupDataSkipped = 0;
        int dupDataUpdated = 0;
        int lnum = 1;
        // Match for starting with a LOINC code: "NUMBERS AND DASHES"
        java.lang.String labRegEx = "^\"([\\d-]*)\"\\t";
        java.util.regex.Pattern req = java.util.regex.Pattern.compile(labRegEx);
        try {
            while ((line = buf.readLine()) != null) {
                try {
                    java.util.regex.Matcher reqMatch = req.matcher(line);
                    // The line must start with a LOINC code to be further processed
                    boolean found = ((line.length() > 0) && (line.charAt(0) == '"')) && reqMatch.find();
                    if (!found) {
                        results.add((("IGNORED LINE " + lnum) + ": ") + line);
                    } else {
                        java.lang.String beanInfo[] = new java.lang.String[7];
                        // split the line along tabs
                        java.lang.String parts[] = line.split("\t");
                        // the line must have been split into at least 2 parts to continue
                        if ((parts != null) && (!parts[0].equals(line))) {
                            for (int i = 0; (i < beanInfo.length) && (i < parts.length); i++) {
                                // this was an empty field
                                if (parts[i].length() <= 2) {
                                    beanInfo[i] = "";
                                } else if ((parts[i].charAt(0) != '"') || (parts[i].charAt(parts[i].length() - 1) != '"')) {
                                    // The first 7 fields of LOINC data must be surrounded by quotes. If they aren't then it's wrong.
                                    throw new edu.ncsu.csc.itrust.exception.FormValidationException("Bad LOINC data line. All fields must be surrounded by quotation marks.");
                                } else {
                                    // strip quotes
                                    beanInfo[i] = parts[i].substring(1, parts[i].length() - 1);
                                }
                            }
                            edu.ncsu.csc.itrust.beans.LOINCbean bean = this.createBean(beanInfo);
                            boolean duplicate = false;
                            try {
                                this.add(bean);
                                // success
                                linesInserted++;
                            } catch (java.lang.Exception e) {
                                if (!e.getMessage().contains("Code already exists")) {
                                    results.add((((("ERROR, LINE " + lnum) + ": ") + line) + " ") + e.getMessage());
                                } else {
                                    duplicate = true;
                                }
                            }
                            if (duplicate) {
                                if (!ignoreDupData) {
                                    java.lang.String res = "";
                                    res = this.updateInformation(bean);
                                    if (res.contains("Error")) {
                                        throw new edu.ncsu.csc.itrust.exception.FormValidationException(res);
                                    } else {
                                        // We updated some data
                                        dupDataUpdated++;
                                    }
                                } else {
                                    // We skipped a line
                                    dupDataSkipped++;
                                }
                            }
                        }
                    }
                } catch (edu.ncsu.csc.itrust.exception.FormValidationException e) {
                    // If we got this we should report the line as an error
                    results.add((((("ERROR, LINE " + lnum) + ": ") + line) + " ") + e.getMessage());
                }
                lnum++;
            } 
        } catch (java.io.IOException e) {
            // this is an IO error and not a data error
            // treat it differently
            results.add("ERROR: " + e.getMessage());
        }
        // No data was changed
        if ((linesInserted <= 0) && (dupDataUpdated <= 0)) {
            // Files are only invalid if we didnt add any new data nor update any existing data.
            if ((dupDataUpdated <= 0) && (dupDataSkipped <= 0)) {
                results.add("File invalid. No LOINC data added.");
            } else {
                // Otherwise, we just skipped existing data lines.
                results.add(("No new LOINC data added. " + dupDataSkipped) + " lines detected as duplicate data.");
            }
        } else {
            // Tell the user how many lines were updated/inserted.
            results.add(((("Successfully added " + linesInserted) + " lines of new LOINC data. Updated ") + dupDataUpdated) + " lines of existing LOINC data.");
        }
    } catch (java.io.UnsupportedEncodingException e1) {
        results.add("ERROR: " + e1.getMessage());
    }
    return results;
}

