public java.util.List<edu.ncsu.csc.itrust.beans.ApptBean> getAllConflictsForDoctor(final long mid) throws java.sql.SQLException, edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstring = null;
    try {
        conn = this.factory.getConnection();
        pstring = conn.prepareStatement("SELECT a1.* " + (((((((("FROM appointment a1, appointment a2, "// all possible sets of 2 appts
         + "appointmenttype type1,appointmenttype type2 ")// and the corresponding types
         + "WHERE a1.appt_id!=a2.appt_id AND ")// exclude itself
         + "a1.appt_type=type1.appt_type AND a2.appt_type=type2.appt_type AND ")// match them with types
         + "((DATE_ADD(a1.sched_date, INTERVAL type1.duration MINUTE)>a2.sched_date AND ")// a1 ends after a2 starts AND
         + "a1.sched_date<=a2.sched_date) OR")// a1 starts before a2 OR
         + "(DATE_ADD(a2.sched_date, INTERVAL type2.duration MINUTE)>a1.sched_date AND ")// a2 ends after a1 starts AND
         + "a2.sched_date<=a1.sched_date)) AND ")// a2 starts before a1 starts
         + "a1.doctor_id=? AND a2.doctor_id=?;"));
        pstring.setLong(1, mid);
        pstring.setLong(2, mid);
        final java.sql.ResultSet results = pstring.executeQuery();
        final java.util.List<edu.ncsu.csc.itrust.beans.ApptBean> conflictList = this.abloader.loadList(results);
        results.close();
        pstring.close();
        return conflictList;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstring);
    }
}

