public static org.w3c.dom.Document generateXml(java.util.ArrayList<java.lang.String> headers, java.util.ArrayList<java.util.ArrayList<java.lang.String>> Data) {
    org.w3c.dom.Document report;
    try {
        // sorced from http://stackoverflow.com/questions/8865099/xml-file-generator-in-java
        javax.xml.parsers.DocumentBuilderFactory factory = javax.xml.parsers.DocumentBuilderFactory.newInstance();
        javax.xml.parsers.DocumentBuilder builder = factory.newDocumentBuilder();
        // new document
        report = builder.newDocument();
        // head element
        org.w3c.dom.Element head = report.createElement("PatientReport");
        report.appendChild(head);
        // assumed has document builder and factory
        // for each top level element
        for (int x = 0; x < Data.size(); x++) {
            // makes format <Patient name="blah" age="xx" birthdate=""/> etc...
            org.w3c.dom.Element patient = report.createElement("Patient");
            for (int y = 0; (y < Data.get(x).size()) && (y < headers.size()); y++) {
                patient.setAttribute(edu.ncsu.csc.itrust.XmlGenerator.parse(headers.get(y)), edu.ncsu.csc.itrust.XmlGenerator.parse(Data.get(x).get(y)));
            }
            head.appendChild(patient);
        }
        // for each first level element, loop through second level and
    } catch (javax.xml.parsers.ParserConfigurationException e) {
        // TODO log error
        return null;
    }
    return report;
}

