    edu.ncsu.csc.itrust.exception.ErrorList errorList = new edu.ncsu.csc.itrust.exception.ErrorList();
    // First name, last name, and email are all required
    errorList.addIfNotNull(this.checkFormat("First name", p.getFirstName(), edu.ncsu.csc.itrust.validate.ValidationFormat.NAME, false));
    errorList.addIfNotNull(this.checkFormat("Last name", p.getLastName(), edu.ncsu.csc.itrust.validate.ValidationFormat.NAME, false));
    errorList.addIfNotNull(this.checkFormat("Email", p.getEmail(), edu.ncsu.csc.itrust.validate.ValidationFormat.EMAIL, false));
    if (!p.getDateOfBirthStr().isEmpty()) {
        errorList.addIfNotNull(this.checkFormat("Date of Birth", p.getDateOfBirthStr(), edu.ncsu.csc.itrust.validate.ValidationFormat.DATE, false));
    }
    if (!p.getDateOfDeathStr().isEmpty()) {
        errorList.addIfNotNull(this.checkFormat("Date of Death", p.getDateOfDeathStr(), edu.ncsu.csc.itrust.validate.ValidationFormat.DATE, true));
    }
    try {
        if ("".equals(p.getDateOfDeathStr()) || (p.getDateOfDeath() == null)) {
            if (!p.getCauseOfDeath().equals("")) {
                errorList.addIfNotNull("Cause of Death cannot be specified without Date of Death!");
            }
        } else {
            if (p.getDateOfDeath().before(p.getDateOfBirth())) {
                errorList.addIfNotNull("Death date cannot be before birth date!");
            }
            if (p.getDateOfDeath().after(new java.util.Date())) {
                errorList.addIfNotNull("Death date cannot be in the future!");
            }
        }
        if (p.getDateOfBirth().after(new java.util.Date())) {
            errorList.addIfNotNull("Birth date cannot be in the future!");
        }
    } catch (java.lang.NullPointerException e) {
        // ignore this
    }
    if (!p.getCauseOfDeath().isEmpty()) {
        boolean deathCauseNull = (null == p.getDateOfDeathStr()) || p.getDateOfDeathStr().equals("");
        errorList.addIfNotNull(this.checkFormat("Cause of Death", p.getCauseOfDeath(), edu.ncsu.csc.itrust.validate.ValidationFormat.ICD9CM, deathCauseNull));
    }
    if (!p.getStreetAddress1().isEmpty()) {
        errorList.addIfNotNull(this.checkFormat("Street Address 1", p.getStreetAddress1(), edu.ncsu.csc.itrust.validate.ValidationFormat.ADDRESS, false));
    }
