public static java.lang.String testHPV(int count, java.util.Date patientDOB, long time) {
    java.lang.String reason = "";
    long weeks = (java.util.Calendar.getInstance().getTimeInMillis() - time) / edu.ncsu.csc.itrust.action.GetVisitRemindersAction.WEEK_IN_MILLIS;
    new java.util.Date();
    if (0 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 9, 0, 0)) {
            reason += "90649 Human Papillomavirus (9 years), ";
        }
    } else if (1 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 9, 2, 0) && (8 <= weeks)) {
            reason += "90649 Human Papillomavirus (9 years, 2 months), ";
        }
    } else if (2 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 9, 6, 0) && (16 <= weeks)) {
            reason += "90649 Human Papillomavirus (9 years, 6 months), ";
        }
    }
    return reason;
}

