private edu.ncsu.csc.itrust.beans.CDCStatsBean getCDCStatsBean(edu.ncsu.csc.itrust.beans.HealthRecord record, edu.ncsu.csc.itrust.dao.mysql.CDCStatsDAO statsDAO) throws edu.ncsu.csc.itrust.exception.DBException {
    // Integer for holding the patient's gender
    int sex = 0;
    // Get the patient's gender
    if (this.patientDAO.getPatient(this.patientID).getGender().toString().equals("Male")) {
        sex = edu.ncsu.csc.itrust.action.ViewHealthRecordsHistoryAction.MALE;
    } else {
        sex = edu.ncsu.csc.itrust.action.ViewHealthRecordsHistoryAction.FEMALE;
    }
    // Get the patient's age
    float age = 0;
    if (record.getVisitDate().equals(this.patientDAO.getPatient(this.patientID).getDateOfBirth())) {
        // If the patient's birthdate equals the office visit date,
        // the patient's age is 0 months
        age = ((float) (0.0));
    } else {
        // Otherwise add 0.5 to the patient's age in months
        age = ((float) (this.calculateAgeInMonthsAtOfficeVisit(record.getOfficeVisitID()) + 0.5));
    }
    // Get the CDCStatsBean for a patient's health metric at his or her age
    edu.ncsu.csc.itrust.beans.CDCStatsBean statsBean = statsDAO.getCDCStats(sex, age);
    if ((statsBean == null) && (age != 0)) {
        // If there is no match with the specified age and sex,
        // query again with the age rounded down as a whole number
        statsBean = statsDAO.getCDCStats(sex, ((float) (java.lang.Math.floor(age))));
    }
    return statsBean;
}

