public boolean addHospital(edu.ncsu.csc.itrust.beans.HospitalBean hosp) throws edu.ncsu.csc.itrust.exception.DBException, edu.ncsu.csc.itrust.exception.ITrustException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("INSERT INTO hospitals (HospitalID, HospitalName, Address, City, State, Zip) " + "VALUES (?,?,?,?,?,?)");
        ps.setString(1, hosp.getHospitalID());
        ps.setString(2, hosp.getHospitalName());
        ps.setString(3, hosp.getHospitalAddress());
        ps.setString(4, hosp.getHospitalCity());
        ps.setString(5, hosp.getHospitalState());
        ps.setString(6, hosp.getHospitalZip());
        boolean check = 1 == ps.executeUpdate();
        ps.close();
        return check;
    } catch (java.sql.SQLException e) {
        if (1062 == e.getErrorCode()) {
            throw new edu.ncsu.csc.itrust.exception.ITrustException("Error: Hospital already exists.");
        }
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

