public int hashCode() {
    final int prime = 31;
    int result = 1;
    result = (prime * result) + (this.comment == null ? 0 : this.comment.hashCode());
    result = (prime * result) + (this.date == null ? 0 : this.date.hashCode());
    result = (prime * result) + (this.docFirstName == null ? 0 : this.docFirstName.hashCode());
    result = (prime * result) + (this.docLastName == null ? 0 : this.docLastName.hashCode());
    result = (prime * result) + ((int) (this.doctormid ^ (this.doctormid >>> 32)));
    result = (prime * result) + ((int) (this.oid ^ (this.oid >>> 32)));
