public double getWeightZScore(edu.ncsu.csc.itrust.beans.HealthRecord record) throws edu.ncsu.csc.itrust.exception.DBException {
    // Get the CDCStatsBean for a patient's weight at his or her age
    edu.ncsu.csc.itrust.beans.CDCStatsBean statsBean = this.getCDCStatsBean(record, this.weightStatsDAO);
    // If there is no matching entry in the CDC Stats table then return -999
    if (statsBean == null) {
        return -999;
    }
    // Get the weight in kilograms
    double weight = record.getWeight() / edu.ncsu.csc.itrust.action.ViewHealthRecordsHistoryAction.POUNDS_IN_KG;
    // Get the z score for the patient's weight
    double zScore = this.getZScore(statsBean, weight);
    return zScore;
}

public static java.lang.String calculateColor(java.lang.String primaryColor, java.lang.String secondaryColor, double ratio) {
    double primeRed = java.lang.Integer.parseInt(primaryColor.substring(0, 2), 16);
    double primeGreen = java.lang.Integer.parseInt(primaryColor.substring(2, 4), 16);
    double primeBlue = java.lang.Integer.parseInt(primaryColor.substring(4, 6), 16);
    double secondRed = java.lang.Integer.parseInt(secondaryColor.substring(0, 2), 16);
    double secondGreen = java.lang.Integer.parseInt(secondaryColor.substring(2, 4), 16);
    double secondBlue = java.lang.Integer.parseInt(secondaryColor.substring(4, 6), 16);
    int newRed = ((int) ((secondRed * ratio) + (primeRed * (1 - ratio))));
    int newGreen = ((int) ((secondGreen * ratio) + (primeGreen * (1 - ratio))));
    int newBlue = ((int) ((secondBlue * ratio) + (primeBlue * (1 - ratio))));
    return java.lang.String.format("%06X", ((newRed << 16) + (newGreen << 8)) + newBlue);
}

