public int getResetPasswordFailures(final java.lang.String ipAddr) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstmt = null;
    int numFailures;
    try {
        conn = this.factory.getConnection();
        pstmt = conn.prepareStatement("SELECT * FROM resetpasswordfailures WHERE IPADDRESS=?");
        pstmt.setString(1, ipAddr);
        final java.sql.ResultSet results = pstmt.executeQuery();
        if (results.next()) {
            // if we're more than X minutes out, clear the failure count
            if ((java.lang.System.currentTimeMillis() - results.getTimestamp("lastFailure").getTime()) > edu.ncsu.csc.itrust.dao.mysql.AuthDAO.LOGIN_TIMEOUT) {
                this.updateResetFailuresToZero(ipAddr);
                results.close();
                pstmt.close();
                numFailures = 0;
            } else {
                final int result = results.getInt("failureCount");
                results.close();
                pstmt.close();
                numFailures = result;
            }
        } else {
            this.insertResetPasswordRow(ipAddr, 0);
            results.close();
            pstmt.close();
            numFailures = 0;
        }
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstmt);
    }
    return numFailures;
}

