public int getSessionTimeoutMins() throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT Value FROM globalvariables WHERE Name='Timeout'");
        java.sql.ResultSet rs = ps.executeQuery();
        if (rs.next()) {
            int returnVal = rs.getInt("Value");
            rs.close();
            return returnVal;
        } else {
            rs.close();
            this.insertDefaultTimeout(20);
            return 20;
        }
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

