    edu.ncsu.csc.itrust.beans.PersonnelBean personnel;
    try {
        /* This nightmare if-statement just checks for two things. Either:
        1) The patient is viewing their own diary.
        2) A trainer designated for the provided PID is viewing the diary.
         */
        if ((this.patientDAO.checkPatientExists(this.loggedInMID) && (this.loggedInMID == patientMID)) || ((((personnel = this.personnelDAO.getPersonnel(this.loggedInMID)) != null) && (personnel.getSpecialty() != null)) && personnel.getSpecialty().equalsIgnoreCase("Trainer"))) {
            return this.exerciseEntryDAO.getPatientExerciseDiaryTotals(patientMID);
        } else {
            throw new edu.ncsu.csc.itrust.exception.ITrustException("You do not have permission to " + "view the Exercise Diary!");
        }
    } catch (edu.ncsu.csc.itrust.exception.DBException d) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Error retrieving Exercise Diary");
    }
}

