public boolean isAtRisk() {
    if (this.qualifiesForDisease()) {
        int numRisks = 0;
        java.util.List<edu.ncsu.csc.itrust.risk.factors.PatientRiskFactor> diseaseRiskFactors = this.getDiseaseRiskFactors();
        for (edu.ncsu.csc.itrust.risk.factors.PatientRiskFactor factor : diseaseRiskFactors) {
            if (factor.hasRiskFactor()) {
                numRisks++;
            }
            if (numRisks >= edu.ncsu.csc.itrust.risk.RiskChecker.RISK_THRESHOLD) {
                return true;
            }
        }
    }
    return false;// both an else from qualifies or NOT over the threshold

}

