public boolean reportInteraction(java.lang.String firstDrug, java.lang.String secondDrug, java.lang.String description) throws edu.ncsu.csc.itrust.exception.ITrustException {
    if (firstDrug.equals(secondDrug)) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Drug cannot interact with itself.");
    }
    java.util.List<edu.ncsu.csc.itrust.beans.DrugInteractionBean> currentIntsDrug2 = this.getInteractions(secondDrug);
    for (edu.ncsu.csc.itrust.beans.DrugInteractionBean dib : currentIntsDrug2) {
        if (dib.getSecondDrug().equals(firstDrug)) {
            throw new edu.ncsu.csc.itrust.exception.ITrustException("Error: Interaction between these drugs already exists.");
        }
    }
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("INSERT INTO druginteractions (FirstDrug, SecondDrug, Description) " + "VALUES (?,?,?)");
        ps.setString(1, firstDrug);
        ps.setString(2, secondDrug);
        ps.setString(3, description);
        boolean check = 1 == ps.executeUpdate();
        ps.close();
        return check;
    } catch (java.sql.SQLException e) {
        if (1062 == e.getErrorCode()) {
            throw new edu.ncsu.csc.itrust.exception.ITrustException("Error: Interaction between these drugs already exists.");
        }
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

