// this warning is only suppressed because Map isn't parameterized (old JSP)
@java.lang.SuppressWarnings("rawtypes")
public T build(java.util.Map map, T bean) throws java.lang.Exception {
    // JavaBeans should not have overloaded methods, according to their API
    // (a stupid limitation!)
    // Nevertheless, we should check for it
    this.checkOverloadedMethods(bean);
    // Use an introspector to find all of the getXXX or setXXX, we only want
    // the setXXX
    java.beans.PropertyDescriptor[] propertyDescriptors = java.beans.Introspector.getBeanInfo(bean.getClass()).getPropertyDescriptors();
    for (java.beans.PropertyDescriptor descriptor : propertyDescriptors) {
        // if object is null, either it was ignored or empty - just go with
        // bean's default
        java.lang.String[] value = ((java.lang.String[]) (map.get(descriptor.getName())));
        java.lang.reflect.Method writeMethod = descriptor.getWriteMethod();
        if (((!"class".equals(descriptor.getName())) && (value != null)) && (writeMethod != null)) {
            // descriptor's name is the name of your property; like
            // firstName
            // only take the first string
            try {
                // Skip the setters for enumerations
                if (writeMethod.getParameterTypes()[0].getEnumConstants() == null) {
                    writeMethod.invoke(bean, new java.lang.Object[]{ value[0] });
                }
            } catch (java.lang.IllegalArgumentException e) {
                // Throw a more informative exception
                throw new java.lang.IllegalArgumentException((((e.getMessage() + " with ") + writeMethod.getName()) + " and ") + value[0]);
            }
        }
    }
    return bean;
}

