public java.util.List<edu.ncsu.csc.itrust.beans.ExerciseEntryBean> getBoundedExerciseDiaryTotals(java.util.Date lower, java.util.Date upper, long patientMID) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstring = null;
    try {
        conn = this.factory.getConnection();
        pstring = conn.prepareStatement(" SELECT EntryID AS EntryID, Date AS Date, ExerciseType AS ExerciseType, Name AS Name, " + (((((((" SUM(Hours) AS Hours, " + " SUM(Calories) AS Calories, ") + " Sets AS Sets, Reps AS Reps, PatientID AS PatientID, LabelID AS LabelID  ") + " FROM exerciseEntry ") + " WHERE PatientID = ? ") + " AND Date BETWEEN ? AND ? ") + " GROUP BY Date ") + " ORDER BY Date DESC"));
        // Add params
        pstring.setLong(1, patientMID);
        // Convert java.util.Date to java.sql.Date
        java.sql.Date lowerSQLDate = new java.sql.Date(lower.getTime());
        java.sql.Date upperSQLDate = new java.sql.Date(upper.getTime());
        pstring.setDate(2, lowerSQLDate);
        pstring.setDate(3, upperSQLDate);
        final java.sql.ResultSet results = pstring.executeQuery();
        final java.util.List<edu.ncsu.csc.itrust.beans.ExerciseEntryBean> diaryList = this.exerciseLoader.loadList(results);
        results.close();
        pstring.close();
        return diaryList;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstring);
    }
}

