    edu.ncsu.csc.itrust.exception.ErrorList errorList = new edu.ncsu.csc.itrust.exception.ErrorList();
    errorList.addIfNotNull(this.checkFormat("Date Performed", bean.getStrDate().toString(), edu.ncsu.csc.itrust.validate.ValidationFormat.DATE, false));
    if (this.checkFormat("Date Performed", bean.getStrDate(), edu.ncsu.csc.itrust.validate.ValidationFormat.DATE, false).equals("")) {
        java.util.Date date = null;
        try {
            date = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(bean.getStrDate());
            java.lang.String dateError = null;
            if (date.after(new java.util.Date())) {
                // if it is after today's date
                dateError = "The Date Performed must be before or on " + "today's Date.";
            }
            errorList.addIfNotNull(dateError);
        } catch (java.text.ParseException e) {
            errorList.addIfNotNull(edu.ncsu.csc.itrust.validate.ValidationFormat.DATE.getDescription());
        }
    }
    if (bean.getExerciseType() == null) {
        errorList.addIfNotNull("Must enter a Exercise Type");
    }
    if (bean.getExerciseType() != null) {
        // make sure we don't get a null
        // pointer
        errorList.addIfNotNull(this.checkFormat("Exercise Type", bean.getExerciseType().getName(), edu.ncsu.csc.itrust.validate.ValidationFormat.EXERCISETYPE, false));
    }
    if ((bean.getStrName() == null) || bean.getStrName().isEmpty()) {
        errorList.addIfNotNull("Must enter the Name of the Exercise");
    }
    if (bean.getHoursWorked() <= 0) {
        errorList.addIfNotNull("Number of Hours must be " + "greater than 0");
    }
    if (bean.getCaloriesBurned() <= 0) {
        errorList.addIfNotNull("Number of Calories Burned must be " + "greater than 0");
    }
    // Only validate these if it's weight training.
    if ((bean.getExerciseType() != null) && bean.getExerciseType().equals(edu.ncsu.csc.itrust.enums.ExerciseType.Weights)) {
        if (bean.getNumSets() <= 0) {
            errorList.addIfNotNull("Number of Sets must be " + "greater than 0");
        }
        if (bean.getNumReps() <= 0) {
            errorList.addIfNotNull("Number of Reps must be " + "greater than 0");
        }
    }
    if (errorList.hasErrors()) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException(errorList);
    }
}

public java.util.List<edu.ncsu.csc.itrust.beans.TransactionBean> getAccesses(java.lang.String lowerDate, java.lang.String upperDate, java.lang.String logMID, boolean getByRole) throws edu.ncsu.csc.itrust.exception.ITrustException, edu.ncsu.csc.itrust.exception.DBException, edu.ncsu.csc.itrust.exception.FormValidationException {
    java.util.List<edu.ncsu.csc.itrust.beans.TransactionBean> accesses;// stores the log entries

    java.util.List<edu.ncsu.csc.itrust.beans.PersonnelBean> dlhcps;
    // get the medical dependents for a signed in user. If the selected user is not the
    // signed in user or one of the dependents, then the user doesn't have access to the log
    java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> patientRelatives = this.getRepresented(this.loggedInMID);
    long mid = this.loggedInMID;
    try {
        mid = java.lang.Long.parseLong(logMID);
    } catch (java.lang.Exception e) {
        // TODO
    }
    dlhcps = this.patientDAO.getDeclaredHCPs(mid);
    boolean midInScope = false;
    for (edu.ncsu.csc.itrust.beans.PatientBean pb : patientRelatives) {
        if (pb.getMID() == mid) {
            midInScope = true;
        }
    }
    if ((mid != this.loggedInMID) && (!midInScope)) {
        // the selected user in the form is out of scope and can't be shown to the user
        throw new edu.ncsu.csc.itrust.exception.FormValidationException("Log to View.");
    }
    // user has either 0 or 1 DLHCP's. Get one if exists so it can be filtered from results
    long dlhcpID = -1;
    if (!dlhcps.isEmpty()) {
        dlhcpID = dlhcps.get(0).getMID();
    }
    if ((lowerDate == null) || (upperDate == null)) {
        return this.transDAO.getAllRecordAccesses(mid, dlhcpID, getByRole);
    }
    try {
        /* the way the Date class works, is if you enter more months, or days than
        is allowed, it will simply mod it, and add it all together. To make sure it
        matches MM/dd/yyyy, I am going to use a Regular Expression
         */
        // month can have 1 or 2 digits, same with day, and year must have 4
        java.util.regex.Pattern p = java.util.regex.Pattern.compile("[0-9]{1,2}?/[0-9]{1,2}?/[0-9]{4}?");
        java.util.regex.Matcher m = p.matcher(upperDate);
        java.util.regex.Matcher n = p.matcher(lowerDate);
        // if it fails to match either of them, throw the form validation exception
        if ((!m.matches()) || (!n.matches())) {
            throw new edu.ncsu.csc.itrust.exception.FormValidationException("Enter dates in MM/dd/yyyy");
        }
        java.util.Date lower = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(lowerDate);
        java.util.Date upper = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(upperDate);
        if (lower.after(upper)) {
            throw new edu.ncsu.csc.itrust.exception.FormValidationException("Start date must be before end date!");
        }
        accesses = this.transDAO.getRecordAccesses(mid, dlhcpID, lower, upper, getByRole);
    } catch (java.text.ParseException e) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException("Enter dates in MM/dd/yyyy");
    }
    return accesses;
}

