public java.util.List<edu.ncsu.csc.itrust.beans.PrescriptionBean> getPrescriptionsForPatient(long patientID) throws edu.ncsu.csc.itrust.exception.ITrustException {
    edu.ncsu.csc.itrust.beans.PatientBean patient = this.patientDAO.getPatient(patientID);
    if (this.loggedInMID == patientID) {
        return this.patientDAO.getExpiredPrescriptions(patientID);
    }
    java.util.List<java.lang.String> toList = new java.util.ArrayList<java.lang.String>();
    toList.add(patient.getEmail());
    java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> representatives = this.patientDAO.getRepresenting(patientID);
    for (edu.ncsu.csc.itrust.beans.PatientBean representative : representatives) {
        if (this.loggedInMID == representative.getMID()) {
            return this.patientDAO.getExpiredPrescriptions(patientID);
        }
        toList.add(representative.getEmail());
    }
    java.util.List<edu.ncsu.csc.itrust.beans.PersonnelBean> dlhcps = this.patientDAO.getDeclaredHCPs(patientID);
    for (edu.ncsu.csc.itrust.beans.PersonnelBean dlhcp : dlhcps) {
        if (this.loggedInMID == dlhcp.getMID()) {
            return this.patientDAO.getExpiredPrescriptions(patientID);
        }
        java.util.List<edu.ncsu.csc.itrust.beans.PersonnelBean> uaps = this.personnelDAO.getUAPsForHCP(dlhcp.getMID());
        for (edu.ncsu.csc.itrust.beans.PersonnelBean uap : uaps) {
            if (this.loggedInMID == uap.getMID()) {
                return this.patientDAO.getPrescriptions(patientID);
            }
        }
    }
    edu.ncsu.csc.itrust.beans.Email email = new edu.ncsu.csc.itrust.beans.Email();
    email.setToList(toList);
    email.setFrom("noreply@itrust.com");
    email.setSubject("Undesignated Personnel Have Accessed Your Prescription Records");
    email.setBody("An undesignated HCP or UAP has accessed your prescription records. For more information, please log in to iTrust.");
    this.emailer.sendEmail(email);
    return this.patientDAO.getPrescriptions(patientID);
}

