        edu.ncsu.csc.itrust.beans.AdverseEventBean aeBean = this.adverseEventDAO.getReport(id);
        this.adverseEventDAO.removeReport(id);
        HCPMID = this.adverseEventDAO.getHCPMID(id);
        edu.ncsu.csc.itrust.beans.MessageBean mBeanTwo = new edu.ncsu.csc.itrust.beans.MessageBean();
        edu.ncsu.csc.itrust.beans.MessageBean mBeanOne = new edu.ncsu.csc.itrust.beans.MessageBean();
        java.lang.String body = ((((("An adverse event for " + aeBean.getDrug()) + " perscribed to ") + this.patientDAO.getName(java.lang.Long.parseLong(aeBean.getMID()))) + " with description: (") + aeBean.getDescription()) + ") was removed.";
        mBeanOne.setTo(java.lang.Long.parseLong(aeBean.getMID()));
        mBeanTwo.setTo(HCPMID);
        mBeanOne.setSubject("Subject");
        mBeanTwo.setSubject("Subject");
        mBeanOne.setBody(body);
        mBeanTwo.setBody(body);
        mBeanOne.setFrom(this.loggedInMID);
        mBeanTwo.setFrom(this.loggedInMID);
        this.messenger.sendMessage(mBeanOne);
        this.messenger.sendMessage(mBeanTwo);
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    }
