public java.lang.String payBillWithCC(java.lang.String ccNum, java.lang.String ccHolder, java.lang.String ccType, java.lang.String billAddress, java.lang.String cvv) throws java.lang.Exception {
    java.util.regex.Pattern checkCvv = java.util.regex.Pattern.compile("[0-9]{3,4}");
    if ((ccType == null) || ccType.equals("null")) {
        return "The field for Credit Card Type must be filled.";
    }
    if (ccType.length() > 20) {
        return "The field for the Credit Card Type must be 20 or shorter.";
    }
    this.myBill.setCcType(ccType);
    if ((ccNum == null) || ccNum.equals("null")) {
        return "The field for Credit Card Number must be filled.";
    }
    int type = org.apache.commons.validator.CreditCardValidator.NONE;
    if (ccType.equals("MasterCard")) {
        type = org.apache.commons.validator.CreditCardValidator.MASTERCARD;
    } else if (ccType.equals("Visa")) {
        type = org.apache.commons.validator.CreditCardValidator.VISA;
    } else if (ccType.equals("AmericanExpress")) {
        type = org.apache.commons.validator.CreditCardValidator.AMEX;
    } else if (ccType.equals("Discover")) {
        type = org.apache.commons.validator.CreditCardValidator.DISCOVER;
    }
    org.apache.commons.validator.CreditCardValidator c = new org.apache.commons.validator.CreditCardValidator(type);
    if ((ccNum.length() > edu.ncsu.csc.itrust.action.PayBillAction.CC_NUMBER_LEN) || (!c.isValid(ccNum))) {
        return "Invalid Credit Card number.";
    }
    this.myBill.setCcNumber(ccNum);
    if ((ccHolder == null) || ccHolder.equals("null")) {
        return "The field for Credit Card Holder must be filled.";
    }
    if (ccHolder.length() > 30) {
        return "The Credit Card Holder must be 30 characters or shorter.";
    }
    this.myBill.setCcHolderName(ccHolder);
    if ((billAddress == null) || billAddress.equals("null")) {
        return "The field for Billing Address must be filled.";
    }
    if (billAddress.length() > 120) {
        return "The fields for Billing Address must be 120 characters or shorter.";
    }
    this.myBill.setBillingAddress(billAddress);
    if ((cvv == null) || cvv.equals("null")) {
        return "The field for CVV must be filled.";
    }
    java.util.regex.Matcher verify = checkCvv.matcher(cvv);
    if (!verify.matches()) {
        return "Invalid CVV code.";
    }
    this.myBill.setCvv(cvv);
    this.myBill.setStatus("Submitted");
    this.myBill.setInsurance(false);
    this.billingDAO.editBill(this.myBill);
    return null;
}

