public java.util.List<edu.ncsu.csc.itrust.beans.MessageBean> filterMessages(java.util.List<edu.ncsu.csc.itrust.beans.MessageBean> messages, java.lang.String filter) throws edu.ncsu.csc.itrust.exception.ITrustException, java.text.ParseException {
    java.util.List<edu.ncsu.csc.itrust.beans.MessageBean> filtered = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.MessageBean>();
    java.lang.String[] f = filter.split(",", -1);
    for (edu.ncsu.csc.itrust.beans.MessageBean m : messages) {
        if (!f[0].equals("")) {
            if (!this.getName(m.getFrom()).equalsIgnoreCase(f[0])) {
                continue;
            }
        }
        if (!f[1].equals("")) {
            if (!m.getSubject().equalsIgnoreCase(f[1])) {
                continue;
            }
        }
        if (!f[2].equals("")) {
            if ((!m.getSubject().toLowerCase().contains(f[2].toLowerCase())) && (!m.getBody().toLowerCase().contains(f[2].toLowerCase()))) {
                continue;
            }
        }
        if (!f[3].equals("")) {
            if (m.getSubject().toLowerCase().contains(f[3].toLowerCase()) || m.getBody().toLowerCase().contains(f[3].toLowerCase())) {
                continue;
            }
        }
        if (!f[4].equals("")) {
            java.text.DateFormat format = new java.text.SimpleDateFormat("MM/dd/yyyy");
            java.util.Date s = format.parse(f[4]);
            if (s.after(m.getSentDate())) {
                continue;
            }
        }
        if (!f[5].equals("")) {
            java.text.DateFormat format = new java.text.SimpleDateFormat("MM/dd/yyyy");
            java.util.Date s = format.parse(f[5]);
            java.util.Calendar c = java.util.Calendar.getInstance();
            c.setTime(s);
            c.add(java.util.Calendar.DAY_OF_MONTH, 1);
            s = c.getTime();
            if (s.before(m.getSentDate())) {
                continue;
            }
        }
        filtered.add(m);
    }
    return filtered;
}

