public boolean hasData() {
    java.util.Date threeYearsAgo = new java.util.Date();
    java.util.Date recDate;
    java.lang.String dateStr;
    java.text.DateFormat year = new java.text.SimpleDateFormat("yyyy");
    java.text.DateFormat rest = new java.text.SimpleDateFormat("/MM/dd HHmma");
    java.text.DateFormat sdf = new java.text.SimpleDateFormat("yyyy/MM/dd HHmma");
    dateStr = year.format(threeYearsAgo);
    dateStr = "" + (java.lang.Integer.parseInt(dateStr) - 3);
    dateStr += rest.format(threeYearsAgo);
    try {
        threeYearsAgo = sdf.parse(dateStr);
    } catch (java.text.ParseException e) {
        return false;
    }
    for (edu.ncsu.csc.itrust.beans.HealthRecord hr : this.healthRecords) {
        recDate = new java.util.Date(hr.getDateRecorded().getTime());
        if (recDate.before(threeYearsAgo)) {
            continue;
        } else {
            return true;
        }
    }
    return false;
}

