protected void doPost(HttpServletRequest request, HttpServletResponse response) throws java.io.IOException, edu.ncsu.csc.itrust.server.ServletException {
    try {
        this.releaseAction = ((edu.ncsu.csc.itrust.action.RequestRecordsReleaseAction) (request.getSession().getAttribute("releaseAction")));
        this.loggingAction = ((edu.ncsu.csc.itrust.action.EventLoggingAction) (request.getSession().getAttribute("loggingAction")));
        this.loggedInName = ((java.lang.String) (request.getSession().getAttribute("loggedInName")));
        this.currentMID = request.getParameter("currentMID");
        this.isRepresentee = request.getParameter("isRepresentee");
        this.releaseHospital = request.getParameter("releaseHospital");
        this.recFirstName = request.getParameter("recFirstName");
        this.recLastName = request.getParameter("recLastName");
        this.recPhone = request.getParameter("recPhone");
        this.recEmail = request.getParameter("recEmail");
        this.recHospitalName = request.getParameter("recHospitalName");
        this.recHospitalAddress1 = request.getParameter("recHospitalAddress1");
        this.recHospitalAddress2 = request.getParameter("recHospitalAddress2");
        this.recHospitalCity = request.getParameter("recHospitalCity");
        this.recHospitalState = request.getParameter("recHospitalState");
        this.recHospitalZip = request.getParameter("recHospitalZip");
        this.releaseJustification = request.getParameter("releaseJustification");
        this.verifyForm = java.lang.Boolean.parseBoolean(request.getParameter("verifyForm"));
        this.digitalSig = request.getParameter("digitalSig");
        this.patMID = ((java.lang.String) (request.getSession().getAttribute("patMID")));
    } catch (java.lang.NullPointerException e) {
        e.printStackTrace();
    }
    java.lang.Boolean checksum = false;
    try {
        checksum = this.checkCredentials(this.digitalSig);
    } catch (java.lang.Exception e) {
        e.printStackTrace();
    }
    try {
        this.form = new edu.ncsu.csc.itrust.beans.forms.RecordsReleaseForm();
        this.form.setReleaseHospitalID(this.releaseHospital);
        this.form.setRecipientFirstName(this.recFirstName);
        this.form.setRecipientLastName(this.recLastName);
        this.form.setRecipientPhone(this.recPhone);
        this.form.setRecipientEmail(this.recEmail);
        this.form.setRecipientHospitalName(this.recHospitalName);
        this.form.setRecipientHospitalAddress(((((((this.recHospitalAddress1 + this.recHospitalAddress2) + ", ") + this.recHospitalCity) + ", ") + this.recHospitalState) + " ") + this.recHospitalZip);
        this.form.setRequestJustification(this.releaseJustification);
        this.form.setDigitalSignature(checksum);
    } catch (java.lang.NullPointerException e) {
        e.printStackTrace();
    }
    java.lang.String message = "";
    message = this.releaseAction.addRecordsRelease(this.form);
    if (!message.equals(edu.ncsu.csc.itrust.action.RequestRecordsReleaseAction.SUCCESS_MESSAGE)) {
        request.setAttribute("failure", message);
        request.setAttribute("isRepresentee", this.isRepresentee);
        request.getRequestDispatcher("requestRecordsRelease.jsp").forward(request, response);
        return;
    }
    try {
        if (this.isRepresentee.equals("false")) {
            this.loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.PATIENT_RELEASE_HEALTH_RECORDS, java.lang.Long.parseLong(this.patMID), java.lang.Long.parseLong(this.currentMID), "");
        } else if (this.isRepresentee.equals("true")) {
            this.loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.PATIENT_REQUEST_DEPEDENT_RECORDS, java.lang.Long.parseLong(this.patMID), java.lang.Long.parseLong(this.currentMID), "");
        }
    } catch (edu.ncsu.csc.itrust.exception.DBException e) {
        e.printStackTrace();
    }
    request.setAttribute("currentMID", this.currentMID);
    request.setAttribute("status", "Pending");
    request.setAttribute("releaseHospital", this.releaseHospital);
    request.setAttribute("recFirstName", this.recFirstName);
    request.setAttribute("recLastName", this.recLastName);
    request.setAttribute("recPhone", this.recPhone);
    request.setAttribute("recEmail", this.recEmail);
    request.setAttribute("recHospitalName", this.recHospitalName);
    request.setAttribute("recHospitalAddress", ((((((this.recHospitalAddress1 + this.recHospitalAddress2) + ", ") + this.recHospitalCity) + ", ") + this.recHospitalState) + " ") + this.recHospitalZip);
    request.setAttribute("recHospitalAddress1", this.recHospitalAddress1);
    request.setAttribute("recHospitalAddress2", this.recHospitalAddress2);
    request.setAttribute("recHospitalCity", this.recHospitalCity);
    request.setAttribute("recHospitalState", this.recHospitalState);
    request.setAttribute("recHospitalZip", this.recHospitalZip);
    request.setAttribute("releaseJustification", this.releaseJustification);
    if (this.verifyForm) {
        request.setAttribute("fromServlet", "true");
        request.getRequestDispatcher("confirmRecordsReleaseServlet.jsp").forward(request, response);
    }
}

