    edu.ncsu.csc.itrust.beans.PersonnelBean personnel;
    try {
        /* This nightmare if-statement just checks for two things. Either:
        1) The patient is viewing their own diary.
        2) A nutritionist designated for the provided PID is viewing the diary.
        the Nutritionist must be the designated nutritionist
         */
        if ((this.patientDAO.checkPatientExists(this.loggedInMID) && (this.loggedInMID == patientMID)) || (((((personnel = this.personnelDAO.getPersonnel(this.loggedInMID)) != null) && (personnel.getSpecialty() != null)) && personnel.getSpecialty().equalsIgnoreCase("Nutritionist")) && (this.patientDAO.getDesignatedNutritionist(patientMID) == this.loggedInMID))) {
            return this.foodEntryDAO.getPatientFoodDiary(patientMID);
        } else {
            throw new edu.ncsu.csc.itrust.exception.ITrustException("You do not have permission to " + "view the Food Diary!");
        }
    } catch (edu.ncsu.csc.itrust.exception.DBException d) {
