public java.util.List<edu.ncsu.csc.itrust.beans.forms.VisitReminderReturnForm> getFluShotDelinquents(long hcpid) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    java.sql.ResultSet rs = null;
    /* Fall 2007 Bug Fix: Use the correct range for a zero-based calendar (eg January is 0) */
    boolean thisYear = edu.ncsu.csc.itrust.DateUtil.currentlyInMonthRange(8, 11);
    java.lang.String flagType = (thisYear) ? edu.ncsu.csc.itrust.beans.VisitFlag.MISSING_MEDICATION : edu.ncsu.csc.itrust.beans.VisitFlag.MISSED_MEDICATION;
    java.sql.Date september = new java.sql.Date(0L);
    java.sql.Date december = new java.sql.Date(0L);
    edu.ncsu.csc.itrust.DateUtil.setSQLMonthRange(september, 8, thisYear ? 0 : 1, december, 11, thisYear ? 0 : 1);
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT DISTINCT " + (((((((((((("? as hid, p.mid as patientid, p.lastname, p.firstname, p.phone " + "FROM officevisits ov, patients p ") + "WHERE (ov.patientid=p.mid ") + "OR p.mid NOT IN (SELECT ov.patientid FROM officevisits ov)) ") + "AND p.dateofdeath IS NULL ") + "AND p.dateofbirth < DATE_SUB(CURDATE(), INTERVAL 50 YEAR) ") + "AND p.mid NOT IN ") + "(SELECT patientid AS mid FROM officevisits ov, ovprocedure op ") + "WHERE ov.id=op.visitid ") + "AND CPTCode IN (90656, 90658, 90660) ") + "AND ((ov.visitdate BETWEEN ? AND ?) ") + "OR (ov.visitdate BETWEEN ? AND ?))) ") + "ORDER BY lastname, firstname, p.mid"));
        ps.setLong(1, hcpid);
        ps.setDate(2, september);
        ps.setDate(3, december);
        ps.setDate(4, september);
        ps.setDate(5, december);
        rs = ps.executeQuery();
        java.util.List<edu.ncsu.csc.itrust.beans.forms.VisitReminderReturnForm> patients = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.forms.VisitReminderReturnForm>();
        edu.ncsu.csc.itrust.beans.forms.VisitReminderReturnForm temp;
        edu.ncsu.csc.itrust.beans.loaders.VisitReminderReturnFormLoader loader = new edu.ncsu.csc.itrust.beans.loaders.VisitReminderReturnFormLoader();
        while (rs.next()) {
            temp = loader.loadSingle(rs);
            temp.addVisitFlag(new edu.ncsu.csc.itrust.beans.VisitFlag(flagType, "Flu Shot"));
            patients.add(temp);
        } 
        rs.close();
        return patients;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

