public int updateNutritionist(long HCPID) throws edu.ncsu.csc.itrust.exception.ITrustException {
    /* If the HCPID = -1 (HCPID can never be -1), then the
    patient wishes to have 'None' as his selected hcp and 
    we will delete it.
    if not -1, we will try first to just update it, and assume that 
    the patient already has a designated nutritionist, if not
    we will add 1 for him
     */
    try {
        int updated = 0;
        edu.ncsu.csc.itrust.beans.PersonnelBean personnel = this.personnelDAO.getPersonnel(HCPID);
        edu.ncsu.csc.itrust.beans.PersonnelBean currentHCP = this.getDesignatedNutritionist();
        if (((personnel != null) && (currentHCP != null)) && (personnel.getMID() == currentHCP.getMID())) {
            // the patient wants to update it to his current nutritionist
            updated = -1;
        } else if (HCPID == (-1)) {
            updated = this.patientDAO.deleteDesignatedNutritionist(this.loggedInMID);
        } else {
            // must want to change/add his designated nutritionist
            // must first make sure the hcp in question has
            // specialty of nutritionist
            boolean isNutritionist = (personnel != null) && personnel.getSpecialty().equalsIgnoreCase("Nutritionist");
            if (isNutritionist) {
                updated = this.patientDAO.updateDesignatedNutritionist(this.loggedInMID, HCPID);
                if (updated == 0) {
                    // didn't update anything, so have to add
                    updated = this.patientDAO.addDesignatedNutritionist(this.loggedInMID, HCPID);
                }
            } else {
                updated = -2;
            }
        }
        return updated;
    } catch (edu.ncsu.csc.itrust.exception.DBException d) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Error retrieving information");
    }
}

