public static void setSQLMonthRange(java.sql.Date month1, int monthValue1, int yearsAgo1, java.sql.Date month2, int monthValue2, int yearsAgo2) {
    java.util.GregorianCalendar cal = new java.util.GregorianCalendar();
    cal.add(java.util.Calendar.YEAR, -yearsAgo1);
    cal.set(java.util.Calendar.MONTH, monthValue1);
    cal.set(java.util.Calendar.DAY_OF_MONTH, 1);
    month1.setTime(cal.getTimeInMillis());
    cal.add(java.util.Calendar.YEAR, yearsAgo1);
    cal.add(java.util.Calendar.YEAR, -yearsAgo2);
    cal.set(java.util.Calendar.MONTH, monthValue2);
    cal.set(java.util.Calendar.DAY_OF_MONTH, cal.getActualMaximum(java.util.Calendar.DAY_OF_MONTH));
    month2.setTime(cal.getTimeInMillis());
}

