public edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean getDiagnosisStatistics(java.lang.String lowerDate, java.lang.String upperDate, java.lang.String icdCode, java.lang.String zip) throws edu.ncsu.csc.itrust.exception.FormValidationException, edu.ncsu.csc.itrust.exception.ITrustException {
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean dsBean;
    try {
        if (((lowerDate == null) || (upperDate == null)) || (icdCode == null)) {
            return null;
        }
        java.util.Date lower = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(lowerDate);
        java.util.Date upper = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(upperDate);
        if (lower.after(upper)) {
            throw new edu.ncsu.csc.itrust.exception.FormValidationException("Start date must be before end date!");
        }
        if (!zip.matches("([0-9]{5})|([0-9]{5}-[0-9]{4})")) {
            throw new edu.ncsu.csc.itrust.exception.FormValidationException("Zip Code must be 5 digits!");
        }
        boolean validCode = false;
        for (edu.ncsu.csc.itrust.beans.DiagnosisBean diag : this.getDiagnosisCodes()) {
            if (diag.getICDCode().equals(icdCode)) {
                validCode = true;
            }
        }
        if (validCode == false) {
            throw new edu.ncsu.csc.itrust.exception.FormValidationException("ICDCode must be valid diagnosis!");
        }
        dsBean = this.diagnosesDAO.getDiagnosisCounts(icdCode, zip, lower, upper);
    } catch (java.text.ParseException e) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException("Enter dates in MM/dd/yyyy");
    }
    return dsBean;
}

