        response.setContentType("application/x-download");
        response.setHeader("Content-Disposition", ("attachment; filename=patientReport-" + java.util.Calendar.getInstance().getTimeInMillis()) + ".xml");
        javax.xml.transform.dom.DOMSource source = new javax.xml.transform.dom.DOMSource(this.doc);
        javax.xml.transform.Transformer transformer = javax.xml.transform.TransformerFactory.newInstance().newTransformer();
        java.io.Writer writer = new java.io.OutputStreamWriter(response.getOutputStream(), "UTF-8");
        javax.xml.transform.stream.StreamResult result = new javax.xml.transform.stream.StreamResult(writer);
        transformer.transform(source, result);
    } catch (java.lang.Exception e) {
        java.lang.System.out.println(e);
    }
}

