public boolean isFluEpidemic(java.lang.String curDateStr, java.lang.String zip) throws java.text.ParseException, edu.ncsu.csc.itrust.exception.DBException {
    new java.text.SimpleDateFormat("MM/dd/yyyy").parse("01/04/1998");
    java.util.Date curDate = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(curDateStr);
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.setTime(curDate);
    int weekOfYr = cal.get(java.util.Calendar.WEEK_OF_YEAR);
    double threshold = this.calcThreshold(weekOfYr);
    double thresholdL = this.calcThreshold(weekOfYr - 1);
    double thresholdN = this.calcThreshold(weekOfYr + 1);
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean dbNow = this.diagnosesDAO.getCountForWeekOf(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_INFLUENZA, zip, cal.getTime());
    cal.add(java.util.Calendar.HOUR, (-12) * 7);
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean dbLast = this.diagnosesDAO.getCountForWeekOf(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_INFLUENZA, zip, cal.getTime());
    cal.add(java.util.Calendar.HOUR, (2 * 12) * 7);
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean dbNext = this.diagnosesDAO.getCountForWeekOf(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_INFLUENZA, zip, cal.getTime());
    double weekNow = ((double) (dbNow.getRegionStats()));
    double weekL = ((double) (dbLast.getRegionStats()));
    double weekN = ((double) (dbNext.getRegionStats()));
    return (weekNow > threshold) && ((weekL > thresholdL) || (weekN > thresholdN));
}

