        ps = conn.prepareStatement("INSERT INTO cptcodes (Code, Description, Attribute) " + "VALUES (?,?,?)");
        ps.setString(1, proc.getCPTCode());
        ps.setString(2, proc.getDescription());
        ps.setString(3, proc.getAttribute());
