public static java.lang.String testVaricella(int count, java.util.Date patientDOB, long time) {
    java.lang.String reason = "";
    long weeks = (java.util.Calendar.getInstance().getTimeInMillis() - time) / edu.ncsu.csc.itrust.action.GetVisitRemindersAction.WEEK_IN_MILLIS;
    if (0 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 1, 0, 0)) {
            reason += "90396 Varicella (12 months), ";
        }
    } else if (1 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 4, 0, 0) && (12 <= weeks)) {
            reason += "90396 Varicella (4 years), ";
        }
    }
    return reason;
}

