public java.lang.String updateAllergies(long pid, java.lang.String description) throws edu.ncsu.csc.itrust.exception.FormValidationException, edu.ncsu.csc.itrust.exception.ITrustException {
    edu.ncsu.csc.itrust.beans.AllergyBean bean = new edu.ncsu.csc.itrust.beans.AllergyBean();
    bean.setPatientID(pid);
    bean.setDescription(description);
    edu.ncsu.csc.itrust.validate.AllergyBeanValidator abv = new edu.ncsu.csc.itrust.validate.AllergyBeanValidator();
    abv.validate(bean);
    // now, set the ndcode if it happens to exist for the description
    for (edu.ncsu.csc.itrust.beans.MedicationBean med : this.ndcodesDAO.getAllNDCodes()) {
        if (med.getDescription().equalsIgnoreCase(bean.getDescription())) {
            bean.setNDCode(med.getNDCode());
            break;
        }
    }
    java.lang.String patientName = this.patientDAO.getName(pid);
    java.util.List<edu.ncsu.csc.itrust.beans.AllergyBean> allergies = this.allergyDAO.getAllergies(pid);
    for (edu.ncsu.csc.itrust.beans.AllergyBean current : allergies) {
        if (current.getDescription().equalsIgnoreCase(bean.getDescription())) {
            return ((((("Allergy " + bean.getNDCode()) + " - ") + bean.getDescription()) + " has already been added for ") + patientName) + ".";
        }
    }
    this.allergyDAO.addAllergy(bean);
    this.emailutil.sendEmail(this.makeEmail());
    /* adding loop that checks for allergy conflicts. The loop runs through every prescription bean
    and checks for conflict.
     */
    java.util.List<edu.ncsu.csc.itrust.beans.PrescriptionBean> beansRx = this.patientDAO.getCurrentPrescriptions(pid);
    for (int i = 0; i < beansRx.size(); i++) {
        if (beansRx.get(i).getMedication().getNDCode().equals(bean.getNDCode())) {
            return ((((("Medication " + beansRx.get(i).getMedication().getNDCode()) + " - ") + beansRx.get(i).getMedication().getDescription()) + " is currently prescribed to ") + patientName) + ".";
        }
    }
    // log that this was added
    this.loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.parse(6700), this.HCPUAP.getMID(), this.patient.getMID(), "An allergy record has been added: " + bean.getId());
    return "Allergy Added";// If loop is successful, it will never reach here.

}

