public long getNextID(final edu.ncsu.csc.itrust.enums.Role role) throws edu.ncsu.csc.itrust.exception.DBException, edu.ncsu.csc.itrust.exception.ITrustException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstmt = null;
    long minID = role.getMidFirstDigit() * 1000000000L;
    minID = (minID == 0) ? 1 : minID;// Do not use 0 as an ID.

    final long maxID = minID + 999999998L;
    long nextID = minID;
    try {
        conn = this.factory.getConnection();
        pstmt = conn.prepareStatement("SELECT MAX(users.mid) FROM users WHERE mid BETWEEN ? AND ?");
        pstmt.setLong(1, minID);
        pstmt.setLong(2, maxID);
        final java.sql.ResultSet results = pstmt.executeQuery();
        if (results.next()) {
            nextID = results.getLong(1) + 1;
            if (nextID < minID) {
                nextID = minID;
            }
        }
        results.close();
        pstmt.close();
        return nextID;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstmt);
    }
}

