public int calculateAgeInMonthsAtOfficeVisit(long ovID) throws edu.ncsu.csc.itrust.exception.DBException {
    // Create int for patient's age in months
    int ageInMonths = 0;
    // Get office visit information
    java.util.Calendar ovDate = java.util.Calendar.getInstance();
    edu.ncsu.csc.itrust.beans.OfficeVisitBean ov = this.ovDAO.getOfficeVisit(ovID);
    ovDate.setTime(ov.getVisitDate());
    // Get the patient's birthdate
    java.util.Calendar dateOfBirth = java.util.Calendar.getInstance();
    edu.ncsu.csc.itrust.beans.PatientBean patient = this.patientDAO.getPatient(this.patientID);
    dateOfBirth.setTime(patient.getDateOfBirth());
    // Split the patient's birthdate into day, month, and year
    int birthDay = dateOfBirth.get(java.util.Calendar.DAY_OF_MONTH);
    int birthMonth = dateOfBirth.get(java.util.Calendar.MONTH) + 1;
    int birthYear = dateOfBirth.get(java.util.Calendar.YEAR);
    // Split the office visit date into day month and year
    int visitDay = ovDate.get(java.util.Calendar.DAY_OF_MONTH);
    int visitMonth = ovDate.get(java.util.Calendar.MONTH) + 1;
    int visitYear = ovDate.get(java.util.Calendar.YEAR);
    // Calculate the year, month, and day differences
    int yearDiff = visitYear - birthYear;
    int monthDiff = visitMonth - birthMonth;
    int dayDiff = visitDay - birthDay;
    // Get the patient's age in months by multiplying the year difference by 12
    // and adding the month difference
    ageInMonths = (yearDiff * edu.ncsu.csc.itrust.action.ViewHealthRecordsHistoryAction.MONTHS_IN_YEAR) + monthDiff;
    // If the day difference is negative, subtract a month from the age
    if (dayDiff < 0) {
        ageInMonths -= 1;
    }
    // Return the age in months
    return ageInMonths;
}

