public void validate(edu.ncsu.csc.itrust.beans.ObstetricsRecordBean p) throws edu.ncsu.csc.itrust.exception.FormValidationException {
    edu.ncsu.csc.itrust.exception.ErrorList errorList = new edu.ncsu.csc.itrust.exception.ErrorList();
    if (p != null) {
        // if Initial record
        if (p.getPregnancyStatus().equals(edu.ncsu.csc.itrust.enums.PregnancyStatus.Initial)) {
            if (((p.getLmp() != null) && (p.getDateVisit() != null)) && p.getLmp().after(p.getDateVisit())) {
                errorList.addIfNotNull("Last menstrual period cannot be after Date of visit");
            }
            errorList.addIfNotNull(this.checkFormat("Weeks Pregnant", p.getWeeksPregnant(), edu.ncsu.csc.itrust.validate.ValidationFormat.WEEKS_PREGNANT, false));
        } else if (p.getPregnancyStatus().equals(edu.ncsu.csc.itrust.enums.PregnancyStatus.Office)) {
            if ((p.getDateVisit() == null) || p.getDateVisitString().equals("")) {
                errorList.addIfNotNull("Date Visit is a required field");
            }
            // note that this weeks pregnant != the initial weeks pregnant b/c can be up to 49 weeks
            errorList.addIfNotNull(this.checkFormat("Weeks Pregnant", p.getWeeksPregnant(), edu.ncsu.csc.itrust.validate.ValidationFormat.WEEKS_PREGNANT_OV, false));
            errorList.addIfNotNull(this.checkFormat("Weight", p.getWeight(), edu.ncsu.csc.itrust.validate.ValidationFormat.WEIGHT, false));
            errorList.addIfNotNull(this.checkFormat("Blood Pressure Systolic", p.getBloodPressureS(), edu.ncsu.csc.itrust.validate.ValidationFormat.SYSTOLIC_BLOOD_PRESSURE, false));
            errorList.addIfNotNull(this.checkFormat("Blood Pressure Diastolic", p.getBloodPressureD(), edu.ncsu.csc.itrust.validate.ValidationFormat.DIASTOLIC_BLOOD_PRESSURE, false));
            errorList.addIfNotNull(this.checkFormat("FHR", p.getFhr(), edu.ncsu.csc.itrust.validate.ValidationFormat.FHR, false));
            errorList.addIfNotNull(this.checkFormat("FHU", p.getFhu(), edu.ncsu.csc.itrust.validate.ValidationFormat.FHU, false));
        } else {
            if ((p.getDateVisit() == null) || p.getDateVisitString().equals("")) {
                errorList.addIfNotNull("Date Visit is a required field");
            }
            errorList.addIfNotNull(this.checkFormat("Year Conception", p.getYearConception(), edu.ncsu.csc.itrust.validate.ValidationFormat.YEAR, false));
            errorList.addIfNotNull(this.checkFormat("Weeks Pregnant", p.getWeeksPregnant(), edu.ncsu.csc.itrust.validate.ValidationFormat.WEEKS_PREGNANT, false));
            errorList.addIfNotNull(this.checkFormat("Hours in Labor", p.getHoursInLabor(), edu.ncsu.csc.itrust.validate.ValidationFormat.HOURS_LABOR, false));
        }
        if (errorList.hasErrors()) {
            throw new edu.ncsu.csc.itrust.exception.FormValidationException(errorList);
        }
    }
}

