public java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean> getWeeklyCounts(java.lang.String icdCode, java.lang.String zipCode, java.util.Date lower, java.util.Date upper) throws edu.ncsu.csc.itrust.exception.DBException {
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.setTime(lower);
    cal.set(java.util.Calendar.DAY_OF_WEEK, java.util.Calendar.MONDAY);
    java.util.Date lowerDate = cal.getTime();
    cal.add(java.util.Calendar.HOUR, 24 * 6);
    java.util.Date upperDate = cal.getTime();
    java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean> weekStats = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean>();
    do {
        edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean db = this.getDiagnosisCounts(icdCode, zipCode, lowerDate, upperDate);
        weekStats.add(db);
        cal.setTime(upperDate);
        cal.add(java.util.Calendar.HOUR, 24);
        lowerDate = cal.getTime();
        cal.add(java.util.Calendar.HOUR, 24 * 6);
        upperDate = cal.getTime();
    } while (lowerDate.before(upper) );
    return weekStats;
}

