public java.util.Hashtable<java.lang.Integer, java.util.ArrayList<edu.ncsu.csc.itrust.beans.OfficeVisitBean>> getOfficeVisitsTable(int thisMonth, int thisYear) throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.util.List<edu.ncsu.csc.itrust.beans.OfficeVisitBean> officeVisits = this.r_action.getAllOfficeVisits();
    java.util.Hashtable<java.lang.Integer, java.util.ArrayList<edu.ncsu.csc.itrust.beans.OfficeVisitBean>> rtable = new java.util.Hashtable<java.lang.Integer, java.util.ArrayList<edu.ncsu.csc.itrust.beans.OfficeVisitBean>>();
    java.util.Calendar a = java.util.Calendar.getInstance();
    for (edu.ncsu.csc.itrust.beans.OfficeVisitBean b : officeVisits) {
        a.setTimeInMillis(b.getVisitDate().getTime());
        if ((a.get(java.util.Calendar.MONTH) == thisMonth) && (a.get(java.util.Calendar.YEAR) == thisYear)) {
            if (!rtable.containsKey(a.get(java.util.Calendar.DAY_OF_MONTH))) {
                rtable.put(a.get(java.util.Calendar.DAY_OF_MONTH), new java.util.ArrayList<edu.ncsu.csc.itrust.beans.OfficeVisitBean>());
            }
            java.util.ArrayList<edu.ncsu.csc.itrust.beans.OfficeVisitBean> l = rtable.get(a.get(java.util.Calendar.DAY_OF_MONTH));
            l.add(b);
            rtable.put(a.get(java.util.Calendar.DAY_OF_MONTH), l);
        }
    }
    return rtable;
}

