private void parseCSV(java.util.Scanner CSVScanner) throws edu.ncsu.csc.itrust.exception.CSVFormatException {
    java.lang.String currentLine;
    java.util.ArrayList<java.lang.String> parsedLine = null;
    // The number of fields (columns) in the CSV file as determined by the number of headers
    int numFields = 0;
    // The current line number being processed (Used to report the line number of errors)
    int currentLineNumber = 1;
    // Attempt to read the first line (the header) from the file
    if (CSVScanner.hasNextLine()) {
        currentLine = CSVScanner.nextLine();
        this.CSVHeader = this.parseCSVLine(currentLine);
        numFields = this.CSVHeader.size();
        // If it does not exist (or if the file isn't a text file at all), the entire process fails
    } else {
        throw new edu.ncsu.csc.itrust.exception.CSVFormatException("File is not valid CSV file.");
    }
    // Read the file line-by-line and call the line parser for each line
    while (CSVScanner.hasNextLine()) {
        currentLineNumber++;
        currentLine = CSVScanner.nextLine();
        try {
            parsedLine = this.parseCSVLine(currentLine);
            // If the line doesn't have the right number of fields, it is ignored
            if (parsedLine.size() == numFields) {
                this.CSVData.add(parsedLine);
            } else {
                this.errors.addIfNotNull("Field number mismatch on line " + currentLineNumber);
            }
            // If the line is otherwise invalid, it is also ignored
        } catch (edu.ncsu.csc.itrust.exception.CSVFormatException e) {
            this.errors.addIfNotNull((e.getMessage() + " on line ") + currentLineNumber);
        }
    } 
}

