public void sendReferralCreatedMessages(edu.ncsu.csc.itrust.beans.ReferralBean bean) throws java.lang.Exception {
    java.lang.StringBuilder body = new java.lang.StringBuilder();
    body.append("Referral information:\n");
    java.lang.String senderSpecialty = this.personnelDAO.getPersonnel(bean.getSenderID()).getSpecialty();
    java.lang.String receiverSpecialty = this.personnelDAO.getPersonnel(bean.getReceiverID()).getSpecialty();
    senderSpecialty = (senderSpecialty == null) ? "no specialty" : senderSpecialty;
    receiverSpecialty = (receiverSpecialty == null) ? "no specialty" : receiverSpecialty;
    body.append(((("Sending HCP: " + this.personnelDAO.getName(bean.getSenderID())) + " (") + senderSpecialty) + ")\n");
    body.append(((("Receiving HCP: " + this.personnelDAO.getName(bean.getReceiverID())) + " (") + receiverSpecialty) + ")\n");
    body.append(("Patient: " + this.getPatientName(bean)) + "\n");
    body.append(("Notes: " + bean.getReferralDetails()) + "\n");
    body.append(("Created on: " + bean.getTimeStamp()) + "\n");
    edu.ncsu.csc.itrust.beans.MessageBean senderMsg = new edu.ncsu.csc.itrust.beans.MessageBean();
    senderMsg.setFrom(bean.getSenderID());
    senderMsg.setTo(bean.getSenderID());
    senderMsg.setBody(body.toString());
    senderMsg.setSubject("You Created a New Referral");
    senderMsg.setRead(0);
    this.messageAction.sendMessage(senderMsg);
    edu.ncsu.csc.itrust.beans.MessageBean receiverMsg = new edu.ncsu.csc.itrust.beans.MessageBean();
    receiverMsg.setFrom(bean.getSenderID());
    receiverMsg.setTo(bean.getReceiverID());
    receiverMsg.setBody(body.toString());
    receiverMsg.setSubject("You Received a New Referral");
    receiverMsg.setRead(0);
    this.messageAction.sendMessage(receiverMsg);
    edu.ncsu.csc.itrust.beans.MessageBean patientMsg = new edu.ncsu.csc.itrust.beans.MessageBean();
    patientMsg.setFrom(bean.getSenderID());
    patientMsg.setTo(bean.getPatientID());
    patientMsg.setBody(body.toString());
    patientMsg.setSubject("You Received a New Referral");
    patientMsg.setRead(0);
    this.messageAction.sendMessage(patientMsg);
}

