public java.util.List<edu.ncsu.csc.itrust.beans.DiagnosisBean> getWarningDiagnoses() throws edu.ncsu.csc.itrust.exception.ITrustException {
    try {
        boolean dup = false;
        java.util.List<edu.ncsu.csc.itrust.beans.DiagnosisBean> allDiagnoses = this.patientDAO.getDiagnoses(this.pid);
        java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisBean> warningList = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisBean>();
        for (edu.ncsu.csc.itrust.beans.DiagnosisBean bean : allDiagnoses) {
            edu.ncsu.csc.itrust.beans.OfficeVisitBean ovb = this.ovDAO.getOfficeVisit(bean.getVisitID());
            if (ovb == null) {
                continue;
            }
            if ("yes".equals(bean.getClassification()) || (ovb.getVisitDate().getTime() > (java.util.Calendar.getInstance().getTimeInMillis() - ((((30 * 24) * 60) * 60) * 1000)))) {
                for (edu.ncsu.csc.itrust.beans.DiagnosisBean wbean : warningList) {
                    if (bean.getDescription().equals(wbean.getDescription())) {
                        dup = true;
                    }
                }
                if (!dup) {
                    warningList.add(bean);
                }
            }
        }
        return warningList;
    } catch (edu.ncsu.csc.itrust.exception.DBException dbe) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException(dbe.getMessage());
    }
}

