@java.lang.Override
public void validate(edu.ncsu.csc.itrust.beans.SleepEntryBean bean) throws edu.ncsu.csc.itrust.exception.FormValidationException {
    edu.ncsu.csc.itrust.exception.ErrorList errorList = new edu.ncsu.csc.itrust.exception.ErrorList();
    errorList.addIfNotNull(this.checkFormat("Date Slept", bean.getStrDate().toString(), edu.ncsu.csc.itrust.validate.ValidationFormat.DATE, false));
    if (this.checkFormat("Date Slept", bean.getStrDate(), edu.ncsu.csc.itrust.validate.ValidationFormat.DATE, false).equals("")) {
        java.util.Date date = null;
        try {
            date = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(bean.getStrDate());
            java.lang.String dateError = null;
            if (date.after(new java.util.Date())) {
                // if it is after today's date
                dateError = "The Date Slept must be before or on " + "today's Date.";
            }
            errorList.addIfNotNull(dateError);
        } catch (java.text.ParseException e) {
            errorList.addIfNotNull(edu.ncsu.csc.itrust.validate.ValidationFormat.DATE.getDescription());
        }
    }
    if (bean.getSleepType() == null) {
        errorList.addIfNotNull("Must enter a Sleep Type");
    }
    if (bean.getSleepType() != null) {
        // make sure we don't get a null
        // pointer
        errorList.addIfNotNull(this.checkFormat("Sleep Type", bean.getSleepType().getName(), edu.ncsu.csc.itrust.validate.ValidationFormat.SLEEPTYPE, false));
    }
    if (bean.getHoursSlept() <= 0) {
        errorList.addIfNotNull("Number of Hours must be " + "greater than 0");
    }
    if (errorList.hasErrors()) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException(errorList);
    }
}

