        if (this.validOverride(pres)) {
            this.emailUtil.sendEmail(this.makeEmail(pres, warnings));
        } else {
            throw new edu.ncsu.csc.itrust.exception.PrescriptionWarningException(warnings);
        }
    }
    if ("".equals(pres.getInstructions())) {
        throw new edu.ncsu.csc.itrust.exception.PrescriptionFieldException("Instructions are required.");
