public static java.lang.String testDipTet(int count, java.util.Date patientDOB, long time) {
    java.lang.String reason = "";
    long weeks = (java.util.Calendar.getInstance().getTimeInMillis() - time) / edu.ncsu.csc.itrust.action.GetVisitRemindersAction.WEEK_IN_MILLIS;
    if (0 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 0, 6)) {
            reason += "90696 Diphtheria, Tetanus, Pertussis (6 weeks), ";
        }
    } else if (1 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 4, 0) && (4 <= weeks)) {
            reason += "90696 Diphtheria, Tetanus, Pertussis (4 months), ";
        }
    } else if (2 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 6, 0) && (4 <= weeks)) {
            reason += "90696 Diphtheria, Tetanus, Pertussis (6 months), ";
        }
    } else if (3 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 0, 15) && (26 <= weeks)) {
            reason += "90696 Diphtheria, Tetanus, Pertussis (15 weeks), ";
        }
    } else if (4 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 4, 0, 0) && (26 <= weeks)) {
            reason += "90696 Diphtheria, Tetanus, Pertussis (4 years), ";
        }
    } else if (5 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 11, 0, 0) && (260 <= weeks)) {
            reason += "90696 Diphtheria, Tetanus, Pertussis (11 years), ";
        }
    }
    return reason;
}

