public edu.ncsu.csc.itrust.beans.Email sendMail(edu.ncsu.csc.itrust.beans.AdverseEventBean aeBean) throws edu.ncsu.csc.itrust.exception.ITrustException, edu.ncsu.csc.itrust.exception.FormValidationException {
    edu.ncsu.csc.itrust.beans.Email email = new edu.ncsu.csc.itrust.beans.Email();
    java.lang.String fromEmail;
    email.setFrom("noreply@itrust.com");
    java.util.List<java.lang.String> toList = new java.util.ArrayList<java.lang.String>();
    edu.ncsu.csc.itrust.beans.PatientBean sender = this.patientDAO.getPatient(this.loggedInMID);
    edu.ncsu.csc.itrust.beans.PersonnelBean receiver = this.personnelDAO.getPersonnel(this.hcpID);
    toList.add(receiver.getEmail());
    fromEmail = sender.getEmail();
    email.setToList(toList);
    email.setFrom(fromEmail);
    email.setSubject(java.lang.String.format("Adverse Event Report (Immunization)"));
    email.setBody(java.lang.String.format((((((((((" Patient: " + this.patientDAO.getName(java.lang.Long.parseLong(aeBean.getMID()))) + " (MID ") + aeBean.getMID()) + ") Has Reported the following adverse event") + " Drug: ") + aeBean.getDrug()) + "(") + aeBean.getCode()) + ") Description: ") + aeBean.getDescription()));
    this.emailer.sendEmail(email);
    return email;
