public void validate(edu.ncsu.csc.itrust.beans.FoodEntryBean bean) throws edu.ncsu.csc.itrust.exception.FormValidationException {
    edu.ncsu.csc.itrust.exception.ErrorList errorList = new edu.ncsu.csc.itrust.exception.ErrorList();
    errorList.addIfNotNull(this.checkFormat("Date Eaten", bean.getDateEatenStr().toString(), edu.ncsu.csc.itrust.validate.ValidationFormat.DATE, false));
    if (this.checkFormat("Date Eaten", bean.getDateEatenStr(), edu.ncsu.csc.itrust.validate.ValidationFormat.DATE, false).equals("")) {
        java.util.Date dateEaten = null;
        try {
            dateEaten = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(bean.getDateEatenStr());
            java.lang.String dateError = null;
            if (dateEaten.after(new java.util.Date())) {
                // if it is after today's date
                dateError = "The Date Eaten must be before or on " + "today's Date.";
            }
            errorList.addIfNotNull(dateError);
        } catch (java.text.ParseException e) {
            errorList.addIfNotNull(edu.ncsu.csc.itrust.validate.ValidationFormat.DATE.getDescription());
        }
    }
    if (bean.getMealType() == null) {
        errorList.addIfNotNull("Must enter a Meal Type");
    }
    if (bean.getMealType() != null) {
        // make sure we don't get a null pointer
        errorList.addIfNotNull(this.checkFormat("Meal Type", bean.getMealType().getName(), edu.ncsu.csc.itrust.validate.ValidationFormat.MEALTYPE, false));
    }
    if ((bean.getFood() == null) || bean.getFood().isEmpty()) {
        errorList.addIfNotNull("Must enter the Name of the Food");
    }
    if (bean.getServings() <= 0) {
        errorList.addIfNotNull("Number of Servings must be " + "greater than 0");
    }
    if (bean.getCalories() < 0) {
        errorList.addIfNotNull("Calories per Serving cannot " + "be negative");
    }
    if (bean.getFatGrams() < 0) {
        errorList.addIfNotNull("Grams of Fat per Serving cannot " + "be negative");
    }
    if (bean.getMilligramsSodium() < 0) {
        errorList.addIfNotNull("Milligrams of Sodium per Serving cannot " + "be negative");
    }
    if (bean.getCarbGrams() < 0) {
        errorList.addIfNotNull("Grams of Carbs per Serving cannot " + "be negative");
    }
    if (bean.getSugarGrams() < 0) {
        errorList.addIfNotNull("Grams of Sugars per Serving cannot " + "be negative");
    }
    if (bean.getFiberGrams() < 0) {
        errorList.addIfNotNull("Grams of Fiber per Serving cannot " + "be negative");
    }
    if (bean.getProteinGrams() < 0) {
        errorList.addIfNotNull("Grams of Protein per Serving cannot " + "be negative");
    }
    if (errorList.hasErrors()) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException(errorList);
    }
}

