public java.lang.String getUserName(final long mid) throws edu.ncsu.csc.itrust.exception.ITrustException {
    final edu.ncsu.csc.itrust.enums.Role role = this.getUserRole(mid);
    java.lang.String uName;
    switch (role) {
        case HCP :
        case PHA :
        case ADMIN :
        case UAP :
        case ER :
        case LT :
            uName = this.factory.getPersonnelDAO().getName(mid);
            break;
        case PATIENT :
            uName = this.factory.getPatientDAO().getName(mid);
            break;
        case TESTER :
            uName = java.lang.String.valueOf(mid);
            break;
        default :
            throw new edu.ncsu.csc.itrust.exception.ITrustException(("Role " + role) + " not supported");
    }
    return uName;
}

