public boolean checkIfPatientIsActive(long pid) throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        if (pid == 0L) {
            throw new java.sql.SQLException("pid cannot be 0");
        }
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT * FROM patients WHERE MID=? AND DateOfDeactivation IS NULL");
        ps.setLong(1, pid);
        java.sql.ResultSet rs = ps.executeQuery();
        edu.ncsu.csc.itrust.beans.PatientBean bean = new edu.ncsu.csc.itrust.beans.PatientBean();
        if (rs.next()) {
            bean = this.patientLoader.loadSingle(rs);
        }
        rs.close();
        ps.close();
        if (bean.getMID() == pid) {
            return true;
        }
        return false;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

public boolean addRepresentative(long representer, long representee) throws edu.ncsu.csc.itrust.exception.DBException, edu.ncsu.csc.itrust.exception.ITrustException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
