        ps = conn.prepareStatement("INSERT INTO representatives(RepresenterMID,RepresenteeMID) VALUES (?,?)");
        ps.setLong(1, representer);
        ps.setLong(2, representee);
        boolean check = 1 == ps.executeUpdate();
        ps.close();
        return check;
    } catch (java.sql.SQLException e) {
        if (1062 == e.getErrorCode()) {
            throw new edu.ncsu.csc.itrust.exception.ITrustException((("Patient " + representer) + " already represents patient ") + representee);
        }
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

