public java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean> getEpidemicStatistics(java.lang.String startDate, java.lang.String icdCode, java.lang.String zip, java.lang.String threshold) throws edu.ncsu.csc.itrust.exception.FormValidationException, edu.ncsu.csc.itrust.exception.DBException {
    if ((startDate == null) || (icdCode == null)) {
        return null;
    }
    if (!(icdCode.equals("84.50") || icdCode.equals("487.00"))) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException("Exception");
    }
    if (edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_MALARIA.equals(icdCode)) {
        try {
            java.lang.Integer.parseInt(threshold);
        } catch (java.lang.NumberFormatException e) {
            throw new edu.ncsu.csc.itrust.exception.FormValidationException("Threshold must be an integer.");
        }
    }
    java.util.Date lower;// lower, which is parsed to startDate

    try {
        lower = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(startDate);
    } catch (java.text.ParseException e) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException("Enter dates in MM/dd/yyyy");
    }
    if (!zip.matches("([0-9]{5})|([0-9]{5}-[0-9]{4})")) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException("Zip Code must be 5 digits!");
    }
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean dbWeek = this.diagnosesDAO.getCountForWeekOf(icdCode, zip, lower);
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean dbAvg = new edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean(zip, 0, 0, lower, lower);
    java.util.Calendar cal = java.util.Calendar.getInstance();
    java.util.Date start = this.diagnosesDAO.findEarliestIncident(icdCode);// start, which is set to earliest incident

    java.util.Calendar startCal = java.util.Calendar.getInstance();
    if (start != null) {
        startCal.setTime(start);
    }
    java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean> ret = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean>();
    if (start == null) {
        ret.add(dbWeek);
        ret.add(dbAvg);
        return ret;
    }
    cal.setTime(lower);// cal, which is set to lower

    java.util.Calendar lowerCal = java.util.Calendar.getInstance();
    lowerCal.setTime(lower);
    int weekOfYr = cal.get(java.util.Calendar.WEEK_OF_YEAR);
    cal.set(java.util.Calendar.YEAR, startCal.get(java.util.Calendar.YEAR));// cal's year then gets set to start's year

    java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean> dbList = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean>();
    while (cal.getTime().before(lower) && (cal.get(java.util.Calendar.YEAR) != lowerCal.get(java.util.Calendar.YEAR))) {
        dbList.add(this.diagnosesDAO.getCountForWeekOf(icdCode, zip, cal.getTime()));
        cal.add(java.util.Calendar.YEAR, 1);
        cal.set(java.util.Calendar.WEEK_OF_YEAR, weekOfYr);
        cal.set(java.util.Calendar.DAY_OF_WEEK, java.util.Calendar.MONDAY);
    } 
    long avg = 0;
    long avgRegion = 0;
    if (dbList.size() > 0) {
        for (edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean d : dbList) {
            avg += d.getZipStats();
            avgRegion += d.getRegionStats();
        }
        avg /= dbList.size();
        avgRegion /= dbList.size();
    }
    dbAvg.setRegionStats(avgRegion);
    dbAvg.setZipStats(avg);
    ret.add(dbWeek);
    ret.add(dbAvg);
    return ret;
}

