    int medMatch = 0;
    java.util.HashMap<java.lang.Long, edu.ncsu.csc.itrust.beans.HCPDiagnosisBean> hcpHash = new java.util.HashMap<java.lang.Long, edu.ncsu.csc.itrust.beans.HCPDiagnosisBean>();
    java.util.HashMap<java.lang.Long, java.lang.Long> patientHash = new java.util.HashMap<java.lang.Long, java.lang.Long>();
    edu.ncsu.csc.itrust.beans.HCPDiagnosisBean diag = null;
    java.util.List<edu.ncsu.csc.itrust.beans.OfficeVisitBean> beans = this.officeVisitDAO.getAllOfficeVisitsForDiagnosis(icdcode);
    for (edu.ncsu.csc.itrust.beans.OfficeVisitBean bean : beans) {
        // check for HCP-Patient locality based on first 3 digits in ZIP
        if (!this.patientDAO.getPatient(this.loggedInMID).getZip().substring(0, 2).equals(this.personnelDAO.getPersonnel(bean.getHcpID()).getZip().substring(0, 2))) {
            continue;
        }
        // Check to see if we already have a bean for the HCP associated with this visit
        if (hcpHash.containsKey(bean.getHcpID())) {
            diag = hcpHash.get(bean.getHcpID());
            // get all prescriptions associated with an office visit
            java.util.List<edu.ncsu.csc.itrust.beans.PrescriptionBean> prescriptions = this.prescriptionsDAO.getList(bean.getID());
            for (edu.ncsu.csc.itrust.beans.PrescriptionBean p : prescriptions) {
                java.util.List<edu.ncsu.csc.itrust.beans.MedicationBean> mlist = diag.getMedList();
                for (edu.ncsu.csc.itrust.beans.MedicationBean b : mlist) {
                    if (p.getMedication().getDescription().equals(b.getDescription())) {
                        medMatch++;
                    }
                }
                if (medMatch == 0) {
                    mlist.add(p.getMedication());
                    diag.setMedList(mlist);
                } else {
                    medMatch = 0;
                }
            }
            // Get Lab Procedures
            java.util.List<edu.ncsu.csc.itrust.beans.LabProcedureBean> labprocs = diag.getLabList();
            java.util.List<edu.ncsu.csc.itrust.beans.LabProcedureBean> lpbeans = this.labprocDAO.getAllLabProceduresForDocOV(bean.getVisitID());
            for (edu.ncsu.csc.itrust.beans.LabProcedureBean p : lpbeans) {
                labprocs.add(p);
            }
            diag.setLabList(labprocs);
            if (this.surveyDAO.isSurveyCompleted(bean.getVisitID())) {
                edu.ncsu.csc.itrust.beans.SurveyBean survey = this.surveyDAO.getSurveyData(bean.getVisitID());
                diag.setVisitSat(survey.getVisitSatisfaction());
                diag.setTreatmentSat(survey.getTreatmentSatisfaction());
            }
            // Check if this patient has been seen multiple times for this diagnosis
            if (!patientHash.containsKey(bean.getPatientID())) {
                patientHash.put(bean.getPatientID(), bean.getHcpID());
                diag.incNumPatients();
            }
        } else {
            diag = new edu.ncsu.csc.itrust.beans.HCPDiagnosisBean();
            java.util.List<edu.ncsu.csc.itrust.beans.MedicationBean> mlist = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.MedicationBean>();
            diag.setHCP(bean.getHcpID());
            try {
                diag.setHCPName(this.personnelDAO.getName(bean.getHcpID()));
            } catch (edu.ncsu.csc.itrust.exception.ITrustException e) {
                diag.setHCPName("null");
            }
            diag.incNumPatients();
            java.util.List<edu.ncsu.csc.itrust.beans.PrescriptionBean> prescriptions = this.prescriptionsDAO.getList(bean.getID());
            for (edu.ncsu.csc.itrust.beans.PrescriptionBean p : prescriptions) {
                mlist.add(p.getMedication());
            }
            diag.setMedList(mlist);
            diag.setLabList(this.labprocDAO.getAllLabProceduresForDocOV(bean.getVisitID()));
            if (this.surveyDAO.isSurveyCompleted(bean.getVisitID())) {
                edu.ncsu.csc.itrust.beans.SurveyBean survey = this.surveyDAO.getSurveyData(bean.getVisitID());
                diag.setVisitSat(survey.getVisitSatisfaction());
                diag.setTreatmentSat(survey.getTreatmentSatisfaction());
            }
            patientHash.put(bean.getPatientID(), bean.getHcpID());
            hcpHash.put(bean.getHcpID(), diag);
        }
    }
    java.util.List<edu.ncsu.csc.itrust.beans.HCPDiagnosisBean> list = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.HCPDiagnosisBean>(hcpHash.values());
    java.util.Collections.sort(list, new edu.ncsu.csc.itrust.action.MyDiagnosisAction.HCPDiagnosisBeanComparator());
    return list;
}

