public java.lang.String addRepresentee(java.lang.String pidString) throws edu.ncsu.csc.itrust.exception.ITrustException {
    try {
        long representee = java.lang.Long.valueOf(pidString);
        if (this.authDAO.getUserRole(representee) != edu.ncsu.csc.itrust.enums.Role.PATIENT) {
            throw new edu.ncsu.csc.itrust.exception.ITrustException("This user is not a patient!");
        } else if (super.pid == representee) {
            throw new edu.ncsu.csc.itrust.exception.ITrustException("This user cannot represent themselves.");
        } else if (!this.patientDAO.checkIfRepresenteeIsActive(representee)) {
            throw new edu.ncsu.csc.itrust.exception.ITrustException(this.patientDAO.getPatient(representee).getFullName() + "cannot be added as a representee, they are not active.");
        }
        boolean confirm = this.patientDAO.addRepresentative(this.pid, representee);
        if (confirm) {
            return "Patient represented";
        } else {
            return "No change made";
        }
    } catch (java.lang.NumberFormatException e) {
        return "MID not a number";
    }
}

