public java.lang.String addHealthRecord(long pid, edu.ncsu.csc.itrust.beans.forms.HealthRecordForm hr, long ovID) throws edu.ncsu.csc.itrust.exception.FormValidationException, edu.ncsu.csc.itrust.exception.ITrustException {
    edu.ncsu.csc.itrust.beans.HealthRecord record;
    if (this.patientAge < edu.ncsu.csc.itrust.action.EditHealthHistoryAction.MONTHS_IN_THREE_YEARS) {
        this.validator.validateBaby(hr);
        record = this.transferFormBaby(pid, hr);
    } else if (this.patientAge < edu.ncsu.csc.itrust.action.EditHealthHistoryAction.MONTHS_IN_TWELVE_YEARS) {
        this.validator.validateYouth(hr);
        record = this.transferFormYouth(pid, hr);
    } else {
        this.validator.validate(hr);
        record = this.transferForm(pid, hr);
    }
    record.setOfficeVisitID(ovID);
    edu.ncsu.csc.itrust.beans.OfficeVisitBean ov = this.ovDAO.getOfficeVisit(ovID);
    record.setOfficeVisitDateStr(ov.getVisitDateStr());
    // If there is already an existing health record with the specified office visit ID
    if (this.getHealthRecordByOfficeVisit(ovID) != null) {
        // Remove the health record before adding a new one
        this.hrDAO.remove(record);
        this.loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.EDIT_BASIC_HEALTH_METRICS, super.getHcpid(), pid, "");
    } else {
        this.loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.CREATE_BASIC_HEALTH_METRICS, super.getHcpid(), pid, "");
    }
    this.hrDAO.add(record);
    return "Information Recorded";
}

