public java.util.Hashtable<java.lang.Integer, java.util.ArrayList<edu.ncsu.csc.itrust.beans.LabProcedureBean>> getLabProceduresTable(int thisMonth, int thisYear) throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.util.List<edu.ncsu.csc.itrust.beans.LabProcedureBean> procs = this.r_action.getLabs();
    java.util.Hashtable<java.lang.Integer, java.util.ArrayList<edu.ncsu.csc.itrust.beans.LabProcedureBean>> ptable = new java.util.Hashtable<java.lang.Integer, java.util.ArrayList<edu.ncsu.csc.itrust.beans.LabProcedureBean>>();
    java.util.Calendar a = java.util.Calendar.getInstance();
    for (edu.ncsu.csc.itrust.beans.LabProcedureBean b : procs) {
        a.setTimeInMillis(b.getTimestamp().getTime());
        if ((a.get(java.util.Calendar.MONTH) == thisMonth) && (a.get(java.util.Calendar.YEAR) == thisYear)) {
            if (!ptable.containsKey(a.get(java.util.Calendar.DAY_OF_MONTH))) {
                ptable.put(a.get(java.util.Calendar.DAY_OF_MONTH), new java.util.ArrayList<edu.ncsu.csc.itrust.beans.LabProcedureBean>());
            }
            java.util.ArrayList<edu.ncsu.csc.itrust.beans.LabProcedureBean> l = ptable.get(a.get(java.util.Calendar.DAY_OF_MONTH));
            l.add(b);
            ptable.put(a.get(java.util.Calendar.DAY_OF_MONTH), l);
        }
    }
    return ptable;
}

