public boolean isMalariaEpidemic(java.lang.String weekDate, java.lang.String zip, java.lang.String thresholdStr) throws edu.ncsu.csc.itrust.exception.DBException, java.text.ParseException {
    java.util.Date wkDate = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(weekDate);
    java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean> dbList = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean>();
    java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean> dbListL = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean>();
    java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean> dbListN = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean>();
    int threshold = java.lang.Integer.parseInt(thresholdStr);
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean current = this.diagnosesDAO.getCountForWeekOf(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_MALARIA, zip, wkDate);
    long weekTotal = current.getRegionStats();
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.setTime(wkDate);
    cal.add(java.util.Calendar.HOUR, (-7) * 24);
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean last = this.diagnosesDAO.getCountForWeekOf(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_MALARIA, zip, cal.getTime());
    long weekTotalL = last.getRegionStats();
    cal.add(java.util.Calendar.HOUR, (2 * 7) * 24);
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean next = this.diagnosesDAO.getCountForWeekOf(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_MALARIA, zip, cal.getTime());
    long weekTotalN = next.getRegionStats();
    cal.setTime(wkDate);
    int weekOfYr = cal.get(java.util.Calendar.WEEK_OF_YEAR);
    // Find earliest Malaria Case. Set calendar's year to that year
    java.util.Date startData = this.diagnosesDAO.findEarliestIncident(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_MALARIA);
    if (startData == null) {
        if (current.getRegionStats() > 0) {
            return true;
        }
        return false;
    }
    java.util.Calendar startDateCal = java.util.Calendar.getInstance();
    startDateCal.setTime(startData);
    java.util.Calendar wkDateCal = java.util.Calendar.getInstance();
    wkDateCal.setTime(wkDate);
    cal.set(java.util.Calendar.YEAR, startDateCal.get(java.util.Calendar.YEAR));
    while (cal.getTime().before(wkDate) && (cal.get(java.util.Calendar.YEAR) != wkDateCal.get(java.util.Calendar.YEAR))) {
        dbList.add(this.diagnosesDAO.getCountForWeekOf(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_MALARIA, zip, cal.getTime()));
        cal.add(java.util.Calendar.HOUR, (-7) * 24);
        dbListL.add(this.diagnosesDAO.getCountForWeekOf(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_MALARIA, zip, cal.getTime()));
        cal.add(java.util.Calendar.HOUR, (2 * 7) * 24);
        dbListN.add(this.diagnosesDAO.getCountForWeekOf(edu.ncsu.csc.itrust.action.ViewDiagnosisStatisticsAction.ICD_MALARIA, zip, cal.getTime()));
        cal.add(java.util.Calendar.YEAR, 1);
        cal.set(java.util.Calendar.WEEK_OF_YEAR, weekOfYr);
        cal.set(java.util.Calendar.DAY_OF_WEEK, java.util.Calendar.MONDAY);
    } 
    long total = 0;
    for (edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean d : dbList) {
        total += d.getRegionStats();
    }
    for (edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean d : dbListL) {
        d.getRegionStats();
    }
    for (edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean d : dbListN) {
        d.getRegionStats();
    }
    long avg = 0;
    long avgL = 0;
    long avgN = 0;
    if (dbList.size() != 0) {
        avg = total / dbList.size();
        avgL = total / dbListL.size();
        avgN = total / dbListN.size();
    }
    return ((weekTotal != 0) && (((weekTotal * 100) / threshold) > avg)) && (((weekTotalL != 0) && (((weekTotalL * 100) / threshold) > avgL)) || ((weekTotalN != 0) && (((weekTotalN * 100) / threshold) > avgN)));
}

