@java.lang.Override
public boolean equals(java.lang.Object other) {
    if (this == other) {
        return true;
    }
    if (!(other instanceof edu.ncsu.csc.itrust.beans.ApptBean)) {
        return false;
    }
    edu.ncsu.csc.itrust.beans.ApptBean otherAppt = ((edu.ncsu.csc.itrust.beans.ApptBean) (other));
    return otherAppt.getApptID() == this.getApptID();
}

@java.lang.Override
public boolean equals(java.lang.Object obj) {
    if (this == obj) {
        return true;
    }
    if (obj == null) {
        return false;
    }
    if (this.getClass() != obj.getClass()) {
        return false;
    }
    edu.ncsu.csc.itrust.beans.ObstetricsRecordBean other = ((edu.ncsu.csc.itrust.beans.ObstetricsRecordBean) (obj));
    if (this.bloodPressureD != other.bloodPressureD) {
        return false;
    }
    if (this.bloodPressureS != other.bloodPressureS) {
        return false;
    }
    if (this.dateVisit == null) {
        if (other.dateVisit != null) {
            return false;
        }
    } else if (!this.dateVisit.equals(other.dateVisit)) {
        return false;
    }
    if (this.deliveryType != other.deliveryType) {
        return false;
    }
    if (this.edd == null) {
        if (other.edd != null) {
            return false;
        }
    } else if (!this.edd.equals(other.edd)) {
        return false;
    }
    if (this.fhr != other.fhr) {
        return false;
    }
    if (java.lang.Double.doubleToLongBits(this.fhu) != java.lang.Double.doubleToLongBits(other.fhu)) {
        return false;
    }
    if (java.lang.Double.doubleToLongBits(this.hoursInLabor) != java.lang.Double.doubleToLongBits(other.hoursInLabor)) {
        return false;
    }
    if (this.lmp == null) {
        if (other.lmp != null) {
            return false;
        }
    } else if (!this.lmp.equals(other.lmp)) {
        return false;
    }
    if (this.mid != other.mid) {
        return false;
    }
    if (this.oid != other.oid) {
        return false;
    }
    if (this.pregId != other.pregId) {
        return false;
    }
    if (this.pregnancyStatus != other.pregnancyStatus) {
        return false;
    }
    if (this.weeksPregnant == null) {
        if (other.weeksPregnant != null) {
            return false;
        }
    } else if (!this.weeksPregnant.equals(other.weeksPregnant)) {
        return false;
    }
    if (java.lang.Double.doubleToLongBits(this.weight) != java.lang.Double.doubleToLongBits(other.weight)) {
        return false;
    }
    if (this.yearConception != other.yearConception) {
        return false;
    }
    return true;
}

