public java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> filter(java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> patients) {
    java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> prunedList = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.PatientBean>();
    boolean add = (this.filterValue != null) && (!this.filterValue.isEmpty());
    if (add) {
        for (edu.ncsu.csc.itrust.beans.PatientBean patient : patients) {
            add = false;
            switch (this.filterType) {
                case MID :
                    add = this.filterValue.equalsIgnoreCase(java.lang.Long.toString(patient.getMID()));
                    break;
                case GENDER :
                    add = this.filterValue.equalsIgnoreCase(patient.getGender().toString());
                    break;
                case LAST_NAME :
                    add = patient.getLastName().equalsIgnoreCase(this.filterValue);
                    break;
                case FIRST_NAME :
                    add = patient.getFirstName().equalsIgnoreCase(this.filterValue);
                    break;
                case CONTACT_EMAIL :
                    add = patient.getEmail().equalsIgnoreCase(this.filterValue);
                    break;
                case STREET_ADDR :
                    add = (patient.getStreetAddress1().equalsIgnoreCase(this.filterValue) || patient.getStreetAddress2().equalsIgnoreCase(this.filterValue)) || ((patient.getStreetAddress1() + " ") + patient.getStreetAddress2()).equalsIgnoreCase(this.filterValue);
                    break;
                case CITY :
                    add = patient.getCity().equalsIgnoreCase(this.filterValue);
                    break;
                case STATE :
                    add = patient.getState().equalsIgnoreCase(this.filterValue);
                    break;
                case ZIP :
                    add = patient.getZip().contains(this.filterValue);
                    break;
                case PHONE :
                    add = patient.getPhone().equalsIgnoreCase(this.filterValue);
                    break;
                case EMER_CONTACT_NAME :
                    add = patient.getEmergencyName().equalsIgnoreCase(this.filterValue);
                    break;
                case EMER_CONTACT_PHONE :
                    add = patient.getEmergencyPhone().equalsIgnoreCase(this.filterValue);
                    break;
                case INSURE_NAME :
                    add = patient.getIcName().equalsIgnoreCase(this.filterValue);
                    break;
                case INSURE_ADDR :
                    add = (patient.getIcAddress1().equalsIgnoreCase(this.filterValue) || patient.getIcAddress2().equalsIgnoreCase(this.filterValue)) || ((patient.getIcAddress1() + " ") + patient.getIcAddress2()).equalsIgnoreCase(this.filterValue);
                    break;
                case INSURE_CITY :
                    add = patient.getIcCity().equalsIgnoreCase(this.filterValue);
                    break;
                case INSURE_STATE :
                    add = patient.getIcState().equalsIgnoreCase(this.filterValue);
                    break;
                case INSURE_ZIP :
                    add = patient.getIcZip().equalsIgnoreCase(this.filterValue);
                    break;
                case INSURE_PHONE :
                    add = patient.getIcPhone().equalsIgnoreCase(this.filterValue);
                    break;
                case INSURE_ID :
                    add = patient.getIcID().equalsIgnoreCase(this.filterValue);
                    break;
                case PARENT_FIRST_NAME :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> parents = this.fDAO.getParents(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.FamilyMemberBean parent : parents) {
                            if (this.filterValue.equalsIgnoreCase(parent.getFirstName())) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case PARENT_LAST_NAME :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> parents = this.fDAO.getParents(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.FamilyMemberBean parent : parents) {
                            if (parent.getLastName().equals(this.filterValue)) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case CHILD_FIRST_NAME :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> children = this.fDAO.getChildren(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.FamilyMemberBean child : children) {
                            if (child.getFirstName().equals(this.filterValue)) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case CHILD_LAST_NAME :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> children = this.fDAO.getChildren(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.FamilyMemberBean child : children) {
                            if (child.getLastName().equals(this.filterValue)) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case SIBLING_FIRST_NAME :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> siblings = this.fDAO.getSiblings(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.FamilyMemberBean sibling : siblings) {
                            if (sibling.getFirstName().equals(this.filterValue)) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case SIBLING_LAST_NAME :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> siblings = this.fDAO.getSiblings(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.FamilyMemberBean sibling : siblings) {
                            if (sibling.getLastName().equals(this.filterValue)) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case LOWER_AGE_LIMIT :
                    int lalval = java.lang.Integer.parseInt(this.filterValue);
                    if (lalval < 0) {
                        throw new java.lang.NumberFormatException("Age must be GTE 0!");
                    }
                    add = lalval <= patient.getAge();
                    break;
                case UPPER_AGE_LIMIT :
                    int ualval = java.lang.Integer.parseInt(this.filterValue);
                    if (ualval < 0) {
                        throw new java.lang.NumberFormatException("Age must be GTE 0!");
                    }
                    add = (patient.getAge() > 0) && (ualval >= patient.getAge());
                    break;
                case DEACTIVATED :
                    if (this.filterValue.equals("exclude")) {
                        add = patient.getDateOfDeactivationStr().equals("");
                    } else if (this.filterValue.equals("only")) {
                        add = !patient.getDateOfDeactivationStr().equals("");
                    } else {
                        add = true;
                    }
                    break;
                default :
                    break;
            }
            if (add) {
                prunedList.add(patient);
            }
        }
    }
    return prunedList;
}

