public java.util.Hashtable<java.lang.Integer, java.util.ArrayList<edu.ncsu.csc.itrust.beans.ApptBean>> getApptsTable(int thisMonth, int thisYear) throws java.sql.SQLException, edu.ncsu.csc.itrust.exception.DBException {
    java.util.List<edu.ncsu.csc.itrust.beans.ApptBean> appts = this.a_action.getAllMyAppointments();
    java.util.Hashtable<java.lang.Integer, java.util.ArrayList<edu.ncsu.csc.itrust.beans.ApptBean>> atable = new java.util.Hashtable<java.lang.Integer, java.util.ArrayList<edu.ncsu.csc.itrust.beans.ApptBean>>();
    java.util.Calendar a = java.util.Calendar.getInstance();
    for (edu.ncsu.csc.itrust.beans.ApptBean b : appts) {
        a.setTimeInMillis(b.getDate().getTime());
        if ((a.get(java.util.Calendar.MONTH) == thisMonth) && (a.get(java.util.Calendar.YEAR) == thisYear)) {
            if (!atable.containsKey(a.get(java.util.Calendar.DAY_OF_MONTH))) {
                atable.put(a.get(java.util.Calendar.DAY_OF_MONTH), new java.util.ArrayList<edu.ncsu.csc.itrust.beans.ApptBean>());
            }
            java.util.ArrayList<edu.ncsu.csc.itrust.beans.ApptBean> l = atable.get(a.get(java.util.Calendar.DAY_OF_MONTH));
            l.add(b);
            this.send.add(b);
            atable.put(a.get(java.util.Calendar.DAY_OF_MONTH), l);
        }
    }
    return atable;
}

