private java.util.List<java.lang.String> checkInteraction(edu.ncsu.csc.itrust.beans.PrescriptionBean newPrescription) throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.util.ArrayList<java.lang.String> warnings = new java.util.ArrayList<java.lang.String>();
    try {
        java.text.SimpleDateFormat needed = new java.text.SimpleDateFormat("yyyy/MM/dd");
        java.lang.String startdate = needed.format(newPrescription.getStartDate());
        java.lang.String enddate = needed.format(newPrescription.getEndDate());
        java.lang.String drug = newPrescription.getMedication().getNDCode();
        startdate = startdate.replaceAll("/", "-");
        enddate = enddate.replaceAll("/", "-");
        java.util.List<edu.ncsu.csc.itrust.beans.PrescriptionReportBean> prBeanList = this.rptDAO.byDate(this.getPid(), startdate, enddate);
        java.util.List<edu.ncsu.csc.itrust.beans.DrugInteractionBean> dBeanList = this.interactionsDAO.getInteractions(drug);
        for (edu.ncsu.csc.itrust.beans.PrescriptionReportBean prBean : prBeanList) {
            java.lang.String oldDrug = prBean.getPrescription().getMedication().getNDCode();
            edu.ncsu.csc.itrust.beans.PrescriptionBean oldPrescription = prBean.getPrescription();
            for (edu.ncsu.csc.itrust.beans.DrugInteractionBean dBean : dBeanList) {
                java.lang.String intDrug1 = dBean.getFirstDrug();
                java.lang.String intDrug2 = dBean.getSecondDrug();
                if (oldDrug.equals(intDrug1) && drug.equals(intDrug2)) {
                    warnings.add(this.formatInteractionWarning(newPrescription, oldPrescription, dBean));
                } else if (oldDrug.equals(intDrug2) && drug.equals(intDrug1)) {
                    warnings.add(this.formatInteractionWarning(newPrescription, oldPrescription, dBean));
                }
            }
        }
    } catch (edu.ncsu.csc.itrust.exception.DBException e) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException(e.getMessage());
    }
    return warnings;
}

