    java.sql.ResultSet rs = null;
    try {
        if (icdcode == null) {
            throw new java.sql.SQLException("icdcode cannot be null");
        }
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT * FROM ovdiagnosis ovd, icdcodes icd WHERE ovd.ICDCode=? and icd.Code=?");
        ps.setString(1, icdcode);
        ps.setString(2, icdcode);
        rs = ps.executeQuery();
        diags = this.diagnosisLoader.loadList(rs);
        rs.close();
        ps.close();
        ps = null;
        rs = null;
        for (edu.ncsu.csc.itrust.beans.DiagnosisBean bean : diags) {
            ps = conn.prepareStatement("SELECT * FROM officevisits ov WHERE ov.ID=?");
            ps.setInt(1, ((int) (bean.getVisitID())));
            rs = ps.executeQuery();
            if (rs.next()) {
                ovs.add(this.officeVisitLoader.loadSingle(rs));
            }
            rs.close();
            ps.close();
        }
        return ovs;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
