    for (edu.ncsu.csc.itrust.beans.AdverseEventBean beano : aeList) {
        if (!MIDlist.contains(beano.getPrescriber())) {
            MIDlist.add(beano.getPrescriber());
        }
    }
    edu.ncsu.csc.itrust.beans.Email email = new edu.ncsu.csc.itrust.beans.Email();
    for (java.lang.String num : MIDlist) {
        java.lang.String message = (((" Patient: " + this.patientDAO.getName(java.lang.Long.parseLong(patientID))) + " (MID ") + patientID) + ") Has Reported the following adverse event(s)";
        java.lang.StringBuffer buf = new java.lang.StringBuffer();
        for (edu.ncsu.csc.itrust.beans.AdverseEventBean beano : aeList) {
            if (beano.getPrescriber().equals(num)) {
                buf.append(beano.getDescription());
            }
        }
        message += buf.toString();
        java.lang.String fromEmail;
        email.setFrom("noreply@itrust.com");
        edu.ncsu.csc.itrust.beans.PatientBean sender = this.patientDAO.getPatient(this.loggedInMID);
        edu.ncsu.csc.itrust.beans.PersonnelBean receiver = this.personnelDAO.getPersonnel(java.lang.Long.parseLong(num));
        java.util.List<java.lang.String> toList = new java.util.ArrayList<java.lang.String>();
        toList.add(receiver.getEmail());
        fromEmail = sender.getEmail();
        email.setToList(toList);
        email.setFrom(fromEmail);
        email.setSubject(java.lang.String.format("Adverse Event Report(Prescription)"));
        email.setBody(message);
        this.emailer.sendEmail(email);
    }
    return email;
}

