private double getZScore(edu.ncsu.csc.itrust.beans.CDCStatsBean statsBean, double healthMetric) {
    // Get the L, M, and S values for a patient's bmi at his or her age
    double L = statsBean.getL();
    double M = statsBean.getM();
    double S = statsBean.getS();
    // Double for holding the z-score
    double zScore;
    if (L == 0.0) {
        // If L is 0 then calculate the z score differently
        zScore = java.lang.Math.log(healthMetric / M) / S;
    } else {
        zScore = (java.lang.Math.pow(healthMetric / M, L) - 1) / (L * S);
    }
    // Round the z score to two decimal places
    zScore = java.lang.Double.parseDouble(java.lang.String.format("%.2f", zScore));
    return zScore;
}

