public java.lang.Object produceDataset(@java.lang.SuppressWarnings("rawtypes")
java.util.Map params) throws de.laures.cewolf.DatasetProduceException {
    // The DefaultCategoryDataset is used for bar charts.
    // This data set class may change based on the type of chart you wish to produce.
    org.jfree.data.category.DefaultCategoryDataset dataset = new org.jfree.data.category.DefaultCategoryDataset() {
        private static final long serialVersionUID = 1L;
    };
    if (this.epidemic == false) {
        this.seriesName = new java.lang.String[2];
        dataset.addValue(this.values[0], this.diagnosisName, "Zipcode Cases");
        dataset.addValue(this.values[1], this.diagnosisName, "Region Cases");
        this.seriesName[0] = "Zipcode Case";
        this.seriesName[1] = "Region Cases";
    } else if (this.epidemic == true) {
        this.seriesName = new java.lang.String[4];
        dataset.addValue(this.values[0], this.diagnosisName, "Current Week Zipcode Cases");
        dataset.addValue(this.values[1], this.diagnosisName, "Average Prior Zipcode Cases");
        dataset.addValue(this.values[2], this.diagnosisName, "Current Week Region Cases");
        dataset.addValue(this.values[3], this.diagnosisName, "Average Prior Region Cases");
        this.seriesName[0] = "Current Week Zipcode Cases";
        this.seriesName[1] = "Average Prior Zipcode Cases";
        this.seriesName[2] = "Current Week Region Cases";
        this.seriesName[3] = "Average Prior Region Cases";
    }
    return dataset;
}

