public void updateFhrFlag(edu.ncsu.csc.itrust.beans.ObstetricsRecordBean p) throws edu.ncsu.csc.itrust.exception.DBException {
    java.util.List<edu.ncsu.csc.itrust.beans.ObstetricsRecordBean> lst = this.obstetricsDAO.getObstetricsRecordsByMID(this.loggedInMID);
    // Get the current flag bean
    edu.ncsu.csc.itrust.beans.FlagsBean f = new edu.ncsu.csc.itrust.beans.FlagsBean();
    f.setMid(p.getMid());
    f.setPregId(p.getPregId());
    f.setFlagValue(edu.ncsu.csc.itrust.enums.FlagValue.AbnormalFHR);
    f = this.flagsDAO.getFlag(f);
    boolean setFlag = false;
    for (edu.ncsu.csc.itrust.beans.ObstetricsRecordBean r : lst) {
        if ((r.getFhr() > edu.ncsu.csc.itrust.beans.FlagsBean.FHR_MAX_TRIGGER) || (r.getFhr() < edu.ncsu.csc.itrust.beans.FlagsBean.FHR_MIN_TRIGGER)) {
