public static java.lang.String testHaemoFlu(int count, java.util.Date patientDOB, long time, long firstDoseTime) {
    java.lang.String reason = "";
    long weeks = (java.util.Calendar.getInstance().getTimeInMillis() - time) / edu.ncsu.csc.itrust.action.GetVisitRemindersAction.WEEK_IN_MILLIS;
    java.util.Date firstDose = new java.util.Date(firstDoseTime);
    if (0 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 0, 6)) {
            reason += "90645 Haemophilus influenzae (6 weeks), ";
        }
    } else if (1 == count) {
        if ((edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 4, 0) && (!edu.ncsu.csc.itrust.action.GetVisitRemindersAction.firstDoseAfter(patientDOB, firstDose, 1, 0, 0))) && (4 <= weeks)) {
            reason += "90645 Haemophilus influenzae (4 months), ";
        } else if (((edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 4, 0) && edu.ncsu.csc.itrust.action.GetVisitRemindersAction.firstDoseAfter(patientDOB, firstDose, 1, 0, 0)) && (!edu.ncsu.csc.itrust.action.GetVisitRemindersAction.firstDoseAfter(patientDOB, firstDose, 1, 2, 0))) && (8 <= weeks)) {
            reason += "90645 Haemophilus influenzae (4 months), ";
        }
    } else if (2 == count) {
        if ((edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 6, 0) && (4 <= weeks)) && (!edu.ncsu.csc.itrust.action.GetVisitRemindersAction.firstDoseAfter(patientDOB, firstDose, 1, 0, 0))) {
            reason += "90645 Haemophilus influenzae (6 months), ";
        }
    }
    return reason;
}

