public int[] getLabTechQueueSizeByPriority(long mid) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    int[] sizes = new int[4];
    try {
        if (mid == 0L) {
            throw new java.sql.SQLException("LabTechID cannot be null");
        }
        conn = this.factory.getConnection();
        for (int i = 1; i <= 3; i++) {
            int count = 0;
            ps = conn.prepareStatement("SELECT COUNT(*) FROM labprocedure WHERE LabTechID = ? AND (Status = ? OR Status = ?) AND PriorityCode = ?");
            ps.setLong(1, mid);
            ps.setString(2, edu.ncsu.csc.itrust.beans.LabProcedureBean.In_Transit);
            ps.setString(3, edu.ncsu.csc.itrust.beans.LabProcedureBean.Received);
            ps.setInt(4, i);
            java.sql.ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                count = rs.getInt(1);
            }
            rs.close();
            sizes[i] = count;
        }
        ps.close();
        return sizes;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

