private void processOfficeVisits() throws edu.ncsu.csc.itrust.exception.ITrustException {
    try {
        java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> plist = this.patientDAO.getAllPatients();
        for (edu.ncsu.csc.itrust.beans.PatientBean pb : plist) {
            // Create a new visit bean
            edu.ncsu.csc.itrust.beans.PatientVisitBean visitBean = new edu.ncsu.csc.itrust.beans.PatientVisitBean();
            // Add patient's information to the visit
            visitBean.setPatient(pb);
            visitBean.setPatientName(pb.getFullName());
            visitBean.setAddress1((pb.getStreetAddress1() + " ") + pb.getStreetAddress2());
            visitBean.setAddress2((((pb.getCity() + " ") + pb.getState()) + " ") + pb.getZip());
            // Get this patients office visit history
            java.util.List<edu.ncsu.csc.itrust.beans.OfficeVisitBean> ovlist = this.officevisitDAO.getAllOfficeVisits(pb.getMID());
            // If they've had an office visit previously, get the date of the latest visit
            if (!ovlist.isEmpty()) {
                // The list is ordered DESC, so the first entry will be the latest
                edu.ncsu.csc.itrust.beans.OfficeVisitBean ov = ovlist.get(0);
                java.lang.String date = ov.getVisitDateStr();
                java.util.Scanner sc = new java.util.Scanner(date);
                sc.useDelimiter("/");
                java.lang.String month = sc.next();
                java.lang.String day = sc.next();
                java.lang.String year = sc.next();
                sc.close();
                visitBean.setLastOVDateM(month);
                visitBean.setLastOVDateD(day);
                visitBean.setLastOVDateY(year);
                visitBean.setLastOVDate((((year + "-") + month) + "-") + date);
            } else {
                // The patient hasn't had an office visit, so set the date to null
                visitBean.setLastOVDateM(null);
                visitBean.setLastOVDateD(null);
                visitBean.setLastOVDateY(null);
                visitBean.setLastOVDate(null);
            }
            this.visits.add(visitBean);
        }
    } catch (edu.ncsu.csc.itrust.exception.DBException dbe) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException(dbe.getMessage());
    }
}

