public edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean getDiagnosisCounts(java.lang.String icdCode, java.lang.String zipCode, java.util.Date lower, java.util.Date upper) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean dsBean = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT * FROM ovdiagnosis INNER JOIN officevisits ON ovdiagnosis.VisitID=officevisits.ID INNER JOIN patients ON officevisits.PatientID=patients.MID WHERE ICDCode=? AND zip=? AND visitDate >= ? AND visitDate <= ? ");
        ps.setString(1, icdCode);
        ps.setString(2, zipCode);
        ps.setTimestamp(3, new java.sql.Timestamp(lower.getTime()));
        // add 1 day's worth to include the upper
        ps.setTimestamp(4, new java.sql.Timestamp(upper.getTime() + (((1000L * 60L) * 60) * 24L)));
        java.sql.ResultSet rs = ps.executeQuery();
        rs.last();
        int local = rs.getRow();
        ps.close();
        ps = conn.prepareStatement("SELECT * FROM ovdiagnosis INNER JOIN officevisits ON ovdiagnosis.VisitID=officevisits.ID INNER JOIN patients ON officevisits.PatientID=patients.MID WHERE ICDCode=? AND zip LIKE ? AND visitDate >= ? AND visitDate <= ? ");
        ps.setString(1, icdCode);
        ps.setString(2, zipCode.substring(0, 3) + "%");
        ps.setTimestamp(3, new java.sql.Timestamp(lower.getTime()));
        // add 1 day's worth to include the upper
        ps.setTimestamp(4, new java.sql.Timestamp(upper.getTime() + (((1000L * 60L) * 60) * 24L)));
        rs = ps.executeQuery();
        rs.last();
        int region = rs.getRow();
        dsBean = new edu.ncsu.csc.itrust.beans.DiagnosisStatisticsBean(zipCode, local, region, lower, upper);
        rs.close();
        ps.close();
        return dsBean;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

