public java.lang.String putConditionByMID(long mid, java.lang.String condition) {
    if ((condition == null) || (condition.length() < 1)) {
        return "Cannot add empty string as a pre-existing condition";
    }
    if (condition.length() > edu.ncsu.csc.itrust.dao.mysql.PreExistingConditionsDAO.CONDITION_MAX_STR_LEN) {
        return ("Maximum length of " + edu.ncsu.csc.itrust.dao.mysql.PreExistingConditionsDAO.CONDITION_MAX_STR_LEN) + " exceeded";
    }
    if (!edu.ncsu.csc.itrust.dao.mysql.PreExistingConditionsDAO.validateStr(condition)) {
        return "Illegal condition. Only alphanumerics - , and _ are allowed.";
    }
    try {
        java.sql.Connection conn = this.factory.getConnection();
        java.sql.Statement stmt = conn.createStatement();
        java.lang.String request = ((("INSERT INTO `obstetricsconditions` (`mid`, `condition`) VALUES ('" + mid) + "', '") + condition) + "');";
        stmt.execute(request);
        conn.close();
        return "Pre-existing condition added OK";
    } catch (java.sql.SQLException e) {
        return "Database error while inserting";
    }
}

