private edu.ncsu.csc.itrust.beans.Email makeEmail() throws edu.ncsu.csc.itrust.exception.DBException {
    edu.ncsu.csc.itrust.beans.Email email = new edu.ncsu.csc.itrust.beans.Email();
    java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> reps = this.patientDAO.getRepresenting(this.patient.getMID());
    java.util.List<java.lang.String> toAddrs = new java.util.ArrayList<java.lang.String>();
    toAddrs.add(this.patient.getEmail());
    for (edu.ncsu.csc.itrust.beans.PatientBean r : reps) {
        toAddrs.add(r.getEmail());
    }
    email.setFrom("no-reply@itrust.com");
    email.setToList(toAddrs);// patient and personal representative

    email.setSubject(java.lang.String.format("Your medical records have been altered"));
    email.setBody((("Health care professional " + this.HCPUAP.getFullName()) + " has altered your medical records. ") + "She is not on your list of designated health care professionals.");
    return email;
}

