public void sendReferralCancelledMessages(edu.ncsu.csc.itrust.beans.ReferralBean bean) throws java.lang.Exception {
    java.lang.StringBuilder body = new java.lang.StringBuilder();
    body.append(("The referral created on " + bean.getTimeStamp()) + "has been deleted.\n\n");
    body.append("The referral is reproduced here for your convienence:\n");
    body.append(((("Sending HCP: " + this.personnelDAO.getName(bean.getSenderID())) + " (") + this.personnelDAO.getPersonnel(bean.getSenderID()).getSpecialty()) + ")\n");
    body.append(((("Receiving HCP: " + this.personnelDAO.getName(bean.getReceiverID())) + " (") + this.personnelDAO.getPersonnel(bean.getReceiverID()).getSpecialty()) + ")\n");
    body.append(("Patient: " + this.getPatientName(bean)) + "\n");
    body.append(("Notes: " + bean.getReferralDetails()) + "\n");
    body.append(("Created on: " + bean.getTimeStamp()) + "\n");
    edu.ncsu.csc.itrust.beans.MessageBean receiverMsg = new edu.ncsu.csc.itrust.beans.MessageBean();
    receiverMsg.setFrom(bean.getSenderID());
    receiverMsg.setTo(bean.getReceiverID());
    receiverMsg.setBody(body.toString());
    receiverMsg.setSubject("Your Referral Was Cancelled");
    receiverMsg.setRead(0);
    this.messageAction.sendMessage(receiverMsg);
    edu.ncsu.csc.itrust.beans.MessageBean patientMsg = new edu.ncsu.csc.itrust.beans.MessageBean();
    patientMsg.setFrom(bean.getSenderID());
    patientMsg.setTo(bean.getPatientID());
    patientMsg.setBody(body.toString());
    patientMsg.setSubject("Your Referral Was Cancelled");
    patientMsg.setRead(0);
    this.messageAction.sendMessage(patientMsg);
}

