public java.lang.String addRecordsRelease(edu.ncsu.csc.itrust.beans.forms.RecordsReleaseForm form) {
    edu.ncsu.csc.itrust.beans.RecordsReleaseBean release;
    try {
        // Validate the form
        this.validator.validate(form);
        // Check that there is a digital signature
        if (!form.getDigitalSignature()) {
            return edu.ncsu.csc.itrust.action.RequestRecordsReleaseAction.SIGNATURE_ERROR;
        }
        // Transfer the form to a RecordsReleaseBean object
        release = this.transferForm(form);
        // Add the bean to the dao
        this.rrDAO.addRecordsRelease(release);
    } catch (edu.ncsu.csc.itrust.exception.FormValidationException e1) {
        java.lang.String errorMsg = "";
        // Check that there is a digital signature
        if (!form.getDigitalSignature()) {
            errorMsg = ", " + edu.ncsu.csc.itrust.action.RequestRecordsReleaseAction.SIGNATURE_ERROR.substring(edu.ncsu.csc.itrust.action.RequestRecordsReleaseAction.SIGNATURE_ERROR.indexOf(' ') + 1);
        }
        // If a form validation exception is thrown, indicate the release could not be added
        return e1.getMessage() + errorMsg;
    } catch (edu.ncsu.csc.itrust.exception.DBException e2) {
        // If a DBException is thrown, indicate the release could not be added
        return edu.ncsu.csc.itrust.action.RequestRecordsReleaseAction.DB_ERROR;
    }
    // Indicate that the release request was successfully added
    return edu.ncsu.csc.itrust.action.RequestRecordsReleaseAction.SUCCESS_MESSAGE;
}

