public int calcDistance(java.lang.String zipCode1, java.lang.String zipCode2) throws edu.ncsu.csc.itrust.exception.DBException {
    edu.ncsu.csc.itrust.beans.ZipCodeBean bean1 = this.zipCodeDAO.getZipCode(zipCode1);
    edu.ncsu.csc.itrust.beans.ZipCodeBean bean2 = this.zipCodeDAO.getZipCode(zipCode2);
    if ((bean1 == null) || (bean2 == null)) {
        return java.lang.Integer.MAX_VALUE;
    }
    double latA = java.lang.Double.valueOf(bean1.getLatitude());
    double longA = java.lang.Double.valueOf(bean1.getLongitude());
    double latB = java.lang.Double.valueOf(bean2.getLatitude());
    double longB = java.lang.Double.valueOf(bean2.getLongitude());
    double theDistance = (java.lang.Math.sin(java.lang.Math.toRadians(latA)) * java.lang.Math.sin(java.lang.Math.toRadians(latB))) + ((java.lang.Math.cos(java.lang.Math.toRadians(latA)) * java.lang.Math.cos(java.lang.Math.toRadians(latB))) * java.lang.Math.cos(java.lang.Math.toRadians(longA - longB)));
    return ((int) (java.lang.Math.toDegrees(java.lang.Math.acos(theDistance)) * 69.09));
}

