private edu.ncsu.csc.itrust.beans.LOINCbean createBean(java.lang.String[] beanInfo) {
    edu.ncsu.csc.itrust.beans.LOINCbean bean = new edu.ncsu.csc.itrust.beans.LOINCbean();
    for (int i = 0; i < beanInfo.length; i++) {
        boolean empty = (beanInfo[i] == null) || beanInfo[i].isEmpty();
        if (empty) {
            beanInfo[i] = null;
        }
        switch (i) {
            case 0 :
                bean.setLabProcedureCode(beanInfo[i]);
                break;
            case 1 :
                bean.setComponent(beanInfo[i]);
                break;
            case 2 :
                bean.setKindOfProperty(beanInfo[i]);
                break;
            case 3 :
                bean.setTimeAspect(beanInfo[i]);
                break;
            case 4 :
                bean.setSystem(beanInfo[i]);
                break;
            case 5 :
                bean.setScaleType(beanInfo[i]);
                break;
            case 6 :
                bean.setMethodType(beanInfo[i]);
                break;
            default :
                break;
        }
    }
    return bean;
}

