public void addObstetricsRecord(edu.ncsu.csc.itrust.beans.ObstetricsRecordBean p, java.util.ArrayList<edu.ncsu.csc.itrust.beans.FlagsBean> flags) throws edu.ncsu.csc.itrust.exception.FormValidationException, edu.ncsu.csc.itrust.exception.ITrustException {
    if (p != null) {
        new edu.ncsu.csc.itrust.validate.ObstetricsRecordValidator().validate(p);
        java.util.List<edu.ncsu.csc.itrust.beans.ObstetricsRecordBean> initialBeans = null;
        // if not an office visit
        if (!p.getPregnancyStatus().equals(edu.ncsu.csc.itrust.enums.PregnancyStatus.Office)) {
            edu.ncsu.csc.itrust.beans.ObstetricsRecordBean bean = this.obstetricsDAO.getObstetricsRecordsByMIDLargestpregId(p.getMid());
            if ((bean == null) || (bean.getPregnancyStatus() == null)) {
                p.setPregId(0);
            } else {
                p.setPregId(bean.getPregId() + 1);
            }
        } else // else, it is an office visit
        {
            initialBeans = this.obstetricsDAO.getObstetricsRecordsByMIDPregStatus(p.getMid(), edu.ncsu.csc.itrust.enums.PregnancyStatus.Initial.toString());
            if ((initialBeans == null) || initialBeans.isEmpty()) {
                throw new edu.ncsu.csc.itrust.exception.ITrustException("The patient chosen is not a current obstetrics patient");
            } else {
                p.setPregId(initialBeans.get(0).getPregId());
            }
        }
        // add the obstetrics record to the database
        this.obstetricsDAO.addObstetricsRecord(p);
        boolean isTwins = false;
        // set the manual flags first to load from later and pull if twins is set
        for (edu.ncsu.csc.itrust.beans.FlagsBean flag : flags) {
            flag.setPregId(p.getPregId());
            this.flagsDAO.setFlag(flag);
            if (flag.getFlagValue() == edu.ncsu.csc.itrust.enums.FlagValue.Twins) {
                isTwins = flag.isFlagged();
            }
        }
        // Office Visit flags
        if (p.getPregnancyStatus().equals(edu.ncsu.csc.itrust.enums.PregnancyStatus.Office)) {
            // Weight flag processing
            boolean setWeightFlag = false;
            java.util.List<edu.ncsu.csc.itrust.beans.HealthRecord> records = this.hDao.getAllRecordsBeforeOVDate(p.getMid(), p.getLmp());
            // can only do BMI calculations if a normal office visit (with height/weight) exists before LMP
            if (records.isEmpty()) {
                records = this.hDao.getAllHealthRecords(p.getMid());
            }
            if (!records.isEmpty()) {
                double height = records.get(0).getHeight();
                double origWeight = records.get(0).getWeight();
                double newWeight = p.getWeight();
                // calculate the original BMI
                double origBMI = edu.ncsu.csc.itrust.beans.HealthRecord.calculateBMI(height, origWeight);
                double weightChange = newWeight - origWeight;
                // find the expected weight offsets in BMI/weight tables
                for (int i = 0; i < edu.ncsu.csc.itrust.beans.FlagsBean.WEIGHTGAINBMIBOUNDS.length; i++) {
                    // This is the correct upper bound
                    if (edu.ncsu.csc.itrust.beans.FlagsBean.WEIGHTGAINBMIBOUNDS[i] > origBMI) {
                        if (isTwins) {
                            // If not in expected twins range
                            if ((edu.ncsu.csc.itrust.beans.FlagsBean.WeightGainTwinsBMIMin[i] > weightChange) || (edu.ncsu.csc.itrust.beans.FlagsBean.WeightGainTwinsBMIMax[i] < weightChange)) {
                                setWeightFlag = true;
                            }
                        } else // If not in expected range
                        if ((edu.ncsu.csc.itrust.beans.FlagsBean.WEIGHTGAINBMIMIN[i] > weightChange) || (edu.ncsu.csc.itrust.beans.FlagsBean.WeightGainBMIMax[i] < weightChange)) {
                            setWeightFlag = true;
                        }
                        break;// exit after computed

                    }
                }
            }
            // Set weight flag if needed
            edu.ncsu.csc.itrust.beans.FlagsBean wFlag = new edu.ncsu.csc.itrust.beans.FlagsBean();
            wFlag.setMid(p.getMid());
            wFlag.setPregId(p.getPregId());
            wFlag.setFlagValue(edu.ncsu.csc.itrust.enums.FlagValue.WeightChange);
            wFlag = this.flagsDAO.getFlag(wFlag);
            if (!wFlag.isFlagged()) {
                wFlag.setFlagged(setWeightFlag);
                this.flagsDAO.setFlag(wFlag);
            }
            // Set FHR flag if needed
            edu.ncsu.csc.itrust.beans.FlagsBean fhrFlag = new edu.ncsu.csc.itrust.beans.FlagsBean();
            fhrFlag.setMid(p.getMid());
            fhrFlag.setPregId(p.getPregId());
            fhrFlag.setFlagValue(edu.ncsu.csc.itrust.enums.FlagValue.AbnormalFHR);
            fhrFlag = this.flagsDAO.getFlag(fhrFlag);
            if (!fhrFlag.isFlagged()) {
                if ((p.getFhr() > edu.ncsu.csc.itrust.beans.FlagsBean.FHR_MAX_TRIGGER) || ((p.getFhr() > 0) && (p.getFhr() < edu.ncsu.csc.itrust.beans.FlagsBean.FHR_MIN_TRIGGER))) {
                    fhrFlag.setFlagged(true);
                    this.flagsDAO.setFlag(fhrFlag);
                }
            }
            // Set BP flag if needed
            edu.ncsu.csc.itrust.beans.FlagsBean bpFlag = new edu.ncsu.csc.itrust.beans.FlagsBean();
            bpFlag.setMid(p.getMid());
            bpFlag.setPregId(p.getPregId());
            bpFlag.setFlagValue(edu.ncsu.csc.itrust.enums.FlagValue.HighBloodPressure);
            bpFlag = this.flagsDAO.getFlag(bpFlag);
            if (!bpFlag.isFlagged()) {
                if ((p.getBloodPressureS() > edu.ncsu.csc.itrust.beans.FlagsBean.SYS_BP_MAX_TRIGGER) || (p.getBloodPressureD() > edu.ncsu.csc.itrust.beans.FlagsBean.DIA_BP_MAX_TRIGGER)) {
                    bpFlag.setFlagged(true);
                    this.flagsDAO.setFlag(bpFlag);
                }
            }
        }
        // UC67: Allergies Flag
        edu.ncsu.csc.itrust.beans.FlagsBean allergiesFlag = new edu.ncsu.csc.itrust.beans.FlagsBean();
        allergiesFlag.setFlagValue(edu.ncsu.csc.itrust.enums.FlagValue.MaternalAllergies);
        allergiesFlag.setMid(p.getMid());
        allergiesFlag.setPregId(p.getPregId());
        allergiesFlag.setFlagged(!this.allergyDAO.getAllergies(p.getMid()).isEmpty());// if not empty, have allergies

        this.flagsDAO.setFlag(allergiesFlag);
        // Advanced maternal age flag
        edu.ncsu.csc.itrust.beans.PatientBean chosenPatient = this.patientDAO.getPatient(p.getMid());
        if (chosenPatient.getAge() > 35) {
            edu.ncsu.csc.itrust.beans.FlagsBean advancedMaternalAge = new edu.ncsu.csc.itrust.beans.FlagsBean();
            advancedMaternalAge.setMid(p.getMid());
            advancedMaternalAge.setPregId(p.getPregId());
            advancedMaternalAge.setFlagValue(edu.ncsu.csc.itrust.enums.FlagValue.AdvancedMaternalAge);
            advancedMaternalAge.setFlagged(true);
            this.flagsDAO.setFlag(advancedMaternalAge);
        }
        // Rh- flag
        if (chosenPatient.getBloodType().toString().contains("-")) {
            edu.ncsu.csc.itrust.beans.FlagsBean rhNeg = new edu.ncsu.csc.itrust.beans.FlagsBean();
            rhNeg.setMid(p.getMid());
            rhNeg.setPregId(p.getPregId());
            rhNeg.setFlagValue(edu.ncsu.csc.itrust.enums.FlagValue.rhNeg);
            rhNeg.setFlagged(true);
            this.flagsDAO.setFlag(rhNeg);
        }
        // Genetic miscarriage flag
        edu.ncsu.csc.itrust.action.ViewObstetricsAction viewObstetrics = new edu.ncsu.csc.itrust.action.ViewObstetricsAction(this.prodDAO, this.loggedInMID);
        java.util.List<edu.ncsu.csc.itrust.beans.ObstetricsRecordBean> priorPregnancies = viewObstetrics.getViewableObstetricsRecordsByMIDType(p.getMid(), edu.ncsu.csc.itrust.enums.PregnancyStatus.Complete);
        int priorMiscarriageCount = 0;
        for (edu.ncsu.csc.itrust.beans.ObstetricsRecordBean prior : priorPregnancies) {
            if (prior.getDeliveryType().equals(edu.ncsu.csc.itrust.enums.DeliveryType.Miscarriage)) {
                priorMiscarriageCount++;
            }
        }
        if (priorMiscarriageCount > 1) {
            edu.ncsu.csc.itrust.beans.FlagsBean miscarriage = new edu.ncsu.csc.itrust.beans.FlagsBean();
            miscarriage.setMid(p.getMid());
            miscarriage.setPregId(p.getPregId());
            miscarriage.setFlagValue(edu.ncsu.csc.itrust.enums.FlagValue.GeneticMiscarriage);
            miscarriage.setFlagged(true);
            this.flagsDAO.setFlag(miscarriage);
        }
        // Pre-existing conditions flag
        java.util.List<java.lang.String> conditions = this.conditionsDAO.getConditionsByMID(p.getMid());
        if (!conditions.isEmpty()) {
            edu.ncsu.csc.itrust.beans.FlagsBean conds = new edu.ncsu.csc.itrust.beans.FlagsBean();
            conds.setMid(p.getMid());
            conds.setPregId(p.getPregId());
            conds.setFlagValue(edu.ncsu.csc.itrust.enums.FlagValue.PreExistingConditions);
            conds.setFlagged(true);
            this.flagsDAO.setFlag(conds);
        }
        if (p.getPregnancyStatus().equals(edu.ncsu.csc.itrust.enums.PregnancyStatus.Initial)) {
            this.loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.parse(6300), this.loggedInMID, p.getMid(), ("Initial Obstetrics Record " + p.getOid()) + " added");
        } else if (p.getPregnancyStatus().equals(edu.ncsu.csc.itrust.enums.PregnancyStatus.Office)) {
            this.loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.parse(6400), this.loggedInMID, p.getMid(), ("Obstetrics Office Visit " + p.getOid()) + " added");
        }
    } else {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Cannot add a null Obstetrics Record.");
    }
}

