public boolean doesFamilyMemberHaveHighCholesterol(edu.ncsu.csc.itrust.beans.FamilyMemberBean member) throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.util.List<edu.ncsu.csc.itrust.beans.HealthRecord> records = this.hrDAO.getAllHealthRecords(member.getMid());
    if (records.size() == 0) {
        return false;
    }
    for (edu.ncsu.csc.itrust.beans.HealthRecord record : records) {
        if ((record.getCholesterolHDL() < 35) || (record.getCholesterolLDL() > 250)) {
            return true;
        }
    }
    return false;
}

