public java.lang.String getSecurityQuestion(final long mid) throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstmt = null;
    try {
        conn = this.factory.getConnection();
        pstmt = conn.prepareStatement("SELECT sQuestion FROM users WHERE MID=?");
        pstmt.setLong(1, mid);
        final java.sql.ResultSet results = pstmt.executeQuery();
        if (results.next()) {
            final java.lang.String result = results.getString("sQuestion");
            results.close();
            pstmt.close();
            return result;
        } else {
            results.close();
            pstmt.close();
            throw new edu.ncsu.csc.itrust.exception.ITrustException("No security question set for MID: " + mid);
        }
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstmt);
    }
}

