public void storePatientData(final long patientMID, final edu.ncsu.csc.itrust.beans.RemoteMonitoringDataBean bean, final java.lang.String reporterRole, final long reporterMID) throws edu.ncsu.csc.itrust.exception.ITrustException {
    float height = bean.getHeight();
    float weight = bean.getWeight();
    int pedometer = bean.getPedometerReading();
    int sbp = bean.getSystolicBloodPressure();
    int dbp = bean.getDiastolicBloodPressure();
    int glucose = bean.getGlucoseLevel();
    if (height == 0) {
        height = -1;
    }
    if (weight == 0) {
        weight = -1;
    }
    if (pedometer == 0) {
        pedometer = -1;
    }
    if (sbp == 0) {
        sbp = -1;
    }
    if (dbp == 0) {
        dbp = -1;
    }
    if (glucose == 0) {
        glucose = -1;
    }
    if ((this.getNumberOfDailyEntries(patientMID, "height") >= 1) && (height != (-1))) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Patient height entries for today cannot exceed 1.");
    }
    if ((this.getNumberOfDailyEntries(patientMID, "weight") >= 1) && (weight != (-1))) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Patient weight entries for today cannot exceed 1.");
    }
    if ((this.getNumberOfDailyEntries(patientMID, "pedometerReading") >= 1) && (pedometer != (-1))) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Patient pedometer reading entries for today cannot exceed 1.");
    }
    if ((this.getNumberOfDailyEntries(patientMID, "glucoseLevel") >= 10) && (glucose != (-1))) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Patient glucose level entries for today cannot exceed 10.");
    }
    if ((this.getNumberOfDailyEntries(patientMID, "systolicBloodPressure") >= 10) && (sbp != (-1))) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Patient systolic blood pressure entries for today cannot exceed 10.");
    }
    if ((this.getNumberOfDailyEntries(patientMID, "diastolicBloodPressure") >= 10) && (dbp != (-1))) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Patient diastolic blood pressure entries for today cannot exceed 10.");
    }
    if ("patient representative".equals(reporterRole)) {
        this.validatePR(reporterMID, patientMID);
    }
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstmt = null;
    try {
        conn = this.factory.getConnection();
        pstmt = conn.prepareStatement("INSERT INTO remotemonitoringdata(PatientID, height, weight, " + "pedometerReading, systolicBloodPressure, diastolicBloodPressure, glucoseLevel, ReporterRole, ReporterID) VALUES(?,?,?,?,?,?,?,?,?)");
        pstmt.setLong(1, patientMID);
        pstmt.setFloat(2, height);
        pstmt.setFloat(3, weight);
        pstmt.setInt(4, pedometer);
        pstmt.setInt(5, sbp);
        pstmt.setInt(6, dbp);
        pstmt.setInt(7, glucose);
        pstmt.setString(8, reporterRole);
        pstmt.setLong(9, reporterMID);
        pstmt.executeUpdate();
        pstmt.close();
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstmt);
    }
}

