public java.util.List<edu.ncsu.csc.itrust.beans.TransactionBean> getRecordAccesses(long patientID, long dlhcpID, java.util.Date lower, java.util.Date upper, boolean getByRole) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement((((("SELECT * FROM transactionlog WHERE secondaryMID=? AND transactionCode IN (" + edu.ncsu.csc.itrust.enums.TransactionType.patientViewableStr) + ") ") + "AND timeLogged >= ? AND timeLogged <= ? ") + "AND loggedInMID!=? ") + "ORDER BY timeLogged DESC");
        ps.setLong(1, patientID);
        ps.setTimestamp(2, new java.sql.Timestamp(lower.getTime()));
        // add 1 day's worth to include the upper
        ps.setTimestamp(3, new java.sql.Timestamp(upper.getTime() + (((1000L * 60L) * 60) * 24L)));
        ps.setLong(4, dlhcpID);
        java.sql.ResultSet rs = ps.executeQuery();
        java.util.List<edu.ncsu.csc.itrust.beans.TransactionBean> tbList = this.loader.loadList(rs);
        tbList = this.addAndSortRoles(tbList, patientID, getByRole);
        rs.close();
        ps.close();
        return tbList;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

