public boolean[] getConflicts() throws java.sql.SQLException, edu.ncsu.csc.itrust.exception.DBException {
    boolean conflicts[] = new boolean[this.send.size()];
    for (int i = 0; i < this.send.size(); i++) {
        edu.ncsu.csc.itrust.beans.ApptBean ab = this.send.get(i);
        long t = ab.getDate().getTime();
        long m = (this.apptTypeDAO.getApptType(ab.getApptType()).getDuration() * 60L) * 1000L;
        java.sql.Timestamp time = new java.sql.Timestamp(t + m);
        for (int j = i + 1; j < this.send.size(); j++) {
            if (this.send.get(j).getDate().before(time)) {
                conflicts[i] = true;
                conflicts[j] = true;
            }
        }
    }
    return conflicts;
}

