public static java.lang.String testRotaVirus(int count, java.util.Date patientDOB, long time) {
    java.lang.String reason = "";
    long weeks = (java.util.Calendar.getInstance().getTimeInMillis() - time) / edu.ncsu.csc.itrust.action.GetVisitRemindersAction.WEEK_IN_MILLIS;
    if (0 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 0, 6)) {
            reason += "90681 Rotavirus (6 weeks), ";
        }
    } else if (1 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 4, 0) && (4 <= weeks)) {
            reason += "90681 Rotavirus (4 months), ";
        }
    } else if (2 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 6, 0) && (4 <= weeks)) {
            reason += "90681 Rotavirus (6 months), ";
        }
    }
    return reason;
}

