public void validatePR(final long representativeMID, final long patientMID) throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstmt = null;
    try {
        conn = this.factory.getConnection();
        pstmt = conn.prepareStatement("SELECT * FROM representatives WHERE RepresenterMID=? AND RepresenteeMID=?");
        pstmt.setLong(1, representativeMID);
        pstmt.setLong(2, patientMID);
        final java.sql.ResultSet results = pstmt.executeQuery();
        if (!results.next()) {
            // no rows
            results.close();
            pstmt.close();
            throw new edu.ncsu.csc.itrust.exception.ITrustException("Representer is not valid for patient " + patientMID);
        }
        results.close();
        pstmt.close();
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstmt);
    }
}

