public java.lang.String getLongStatus(long id) throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.lang.StringBuilder s = new java.lang.StringBuilder();
    edu.ncsu.csc.itrust.beans.ReportRequestBean r = this.reportRequestDAO.getReportRequest(id);
    if (r.getStatus().equals(edu.ncsu.csc.itrust.beans.ReportRequestBean.Requested)) {
        edu.ncsu.csc.itrust.beans.PersonnelBean p = this.personnelDAO.getPersonnel(r.getRequesterMID());
        s.append(java.lang.String.format("Request was requested on %s by %s", r.getRequestedDateString(), p.getFullName()));
    }
    if (r.getStatus().equals(edu.ncsu.csc.itrust.beans.ReportRequestBean.Viewed)) {
        edu.ncsu.csc.itrust.beans.PersonnelBean p = this.personnelDAO.getPersonnel(r.getRequesterMID());
        java.lang.String fullName = "Unknown";
        if (p != null) {
            fullName = p.getFullName();
            s.append(java.lang.String.format("Request was requested on %s by %s, ", r.getRequestedDateString(), p.getFullName()));
        }
        s.append("");// removed "<br />" because it caused unit test to fail and seems to have no

        // purpose
        s.append(java.lang.String.format("and viewed on %s by %s", r.getViewedDateString(), fullName));
    }
    return s.toString();
}

