public java.util.List<edu.ncsu.csc.itrust.beans.RemoteMonitoringDataBean> getPatientsData(final long loggedInMID) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstmt = null;
    try {
        conn = this.factory.getConnection();
        pstmt = conn.prepareStatement("SELECT * FROM remotemonitoringlists WHERE HCPMID=? ORDER BY PatientMID");
        pstmt.setLong(1, loggedInMID);
        final java.sql.ResultSet patientRS = pstmt.executeQuery();
        java.sql.PreparedStatement pstmt1 = conn.prepareStatement("SELECT * FROM remotemonitoringdata WHERE timelogged >= CURRENT_DATE ORDER BY PatientID, timeLogged DESC");
        final java.sql.ResultSet dataRS = pstmt1.executeQuery();
        final java.util.List<java.lang.String> patientList = new java.util.ArrayList<java.lang.String>();
        while (patientRS.next()) {
            patientList.add(java.lang.Long.valueOf(patientRS.getLong("PatientMID")).toString());
        } 
        final java.util.List<edu.ncsu.csc.itrust.beans.RemoteMonitoringDataBean> dataList = this.loader.loadList(dataRS);
        pstmt.close();
        dataRS.close();
        pstmt1.close();
        int idx1;
        int idx2;
        // Go through all patients and remove any that aren't monitored by this HCP
        for (idx1 = 0; idx1 < dataList.size(); idx1++) {
            if (!patientList.contains(java.lang.Long.valueOf(dataList.get(idx1).getPatientMID()).toString())) {
                dataList.remove(idx1);
                idx1--;
            }
        }
        // Add values in patient list with no data for today to list.
        boolean itsThere;
        for (idx1 = 0; idx1 < patientList.size(); idx1++) {
            itsThere = false;
            for (idx2 = 0; idx2 < dataList.size(); idx2++) {
                if (dataList.get(idx2).getPatientMID() == java.lang.Long.parseLong(patientList.get(idx1))) {
                    itsThere = true;
                    break;
                }
            }
            if (!itsThere) {
                dataList.add(new edu.ncsu.csc.itrust.beans.RemoteMonitoringDataBean(java.lang.Long.parseLong(patientList.get(idx1))));
            }
        }
        return dataList;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstmt);
    }
}

