public boolean approveRequest(edu.ncsu.csc.itrust.beans.RecordsReleaseBean request) {
    // If the request status is not pending, don't update
    if (request.getStatus() != 0) {
        return false;
    }
    // Set the request to approved status
    request.setStatus(1);
    try {
        // Update the records release object
        this.releaseDAO.updateRecordsRelease(request);
    } catch (edu.ncsu.csc.itrust.exception.DBException e) {
        // If a DBException is caught reset the status and return false
        request.setStatus(0);
        return false;
    }
    return true;
}

