    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT firstName, lastName FROM patients WHERE MID=?");
        ps.setLong(1, mid);
        java.sql.ResultSet rs;
        rs = ps.executeQuery();
        if (rs.next()) {
            java.lang.String result = (rs.getString("firstName") + " ") + rs.getString("lastName");
            rs.close();
            ps.close();
            return result;
        } else {
            rs.close();
            ps.close();
            throw new edu.ncsu.csc.itrust.exception.ITrustException("User does not exist");
