public java.util.List<edu.ncsu.csc.itrust.beans.PrescriptionReportBean> getPrescriptionReports(java.util.Map<java.lang.String, java.lang.String> params, java.util.List<edu.ncsu.csc.itrust.beans.OfficeVisitBean> officeVisits) throws edu.ncsu.csc.itrust.exception.DBException {
    java.util.HashMap<java.lang.String, java.lang.String> myParams = edu.ncsu.csc.itrust.ParameterUtil.convertMap(params);
    java.util.List<java.lang.Long> ovIDs = new java.util.ArrayList<java.lang.Long>();
    for (int i = 0; i < officeVisits.size(); i++) {
        try {
            if (params.get("ovOff" + i) != null) {
                int offset = java.lang.Integer.valueOf(myParams.get("ovOff" + i));
                ovIDs.add(officeVisits.get(offset).getVisitID());
            }
        } catch (java.lang.NumberFormatException e) {
            // just skip it
        }
    }
    if (ovIDs.size() == 0) {
        return new java.util.ArrayList<edu.ncsu.csc.itrust.beans.PrescriptionReportBean>();
    }
    return this.prDAO.byOfficeVisitAndPatient(ovIDs, this.pid);
}

