public java.util.List<edu.ncsu.csc.itrust.beans.HealthRecord> getAllPatientHealthRecords() throws edu.ncsu.csc.itrust.exception.ITrustException {
    if (this.user.getUserRolesString().equals("patient")) {
        // Log for a patient
        this.loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.PATIENT_VIEW_BASIC_HEALTH_METRICS, this.loggedInMID, this.patientID, "");
    }
    if (this.user.getUserRolesString().equals("hcp")) {
        // Log for an HCP
        this.loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.HCP_VIEW_BASIC_HEALTH_METRICS, this.loggedInMID, this.patientID, "");
    }
    // Get the patient's date of birth
    java.util.Date dateOfBirth = this.patientDAO.getPatient(this.patientID).getDateOfBirth();
    // Age 3 date
    java.util.Calendar ovDateLower = java.util.Calendar.getInstance();
    ovDateLower.setTime(dateOfBirth);
    ovDateLower.add(java.util.Calendar.YEAR, 3);
    // Age 12 date
    java.util.Calendar ovDateUpper = java.util.Calendar.getInstance();
    ovDateUpper.setTime(dateOfBirth);
    ovDateUpper.add(java.util.Calendar.YEAR, 12);
    java.util.List<edu.ncsu.csc.itrust.beans.HealthRecord> adultList = this.hrDAO.getAllRecordsAfterOVDate(this.patientID, ovDateUpper.getTime());
    java.util.List<edu.ncsu.csc.itrust.beans.HealthRecord> youthList = this.hrDAO.getAllRecordsBetweenOVDates(this.patientID, ovDateLower.getTime(), ovDateUpper.getTime());
    java.util.List<edu.ncsu.csc.itrust.beans.HealthRecord> babyList = this.hrDAO.getAllRecordsBeforeOVDate(this.patientID, ovDateLower.getTime());
    youthList.addAll(adultList);
    babyList.addAll(youthList);
    java.util.List<edu.ncsu.csc.itrust.beans.HealthRecord> allList = babyList;
    return allList;
}

