public void generateReport() {
    // Initialize the GroupReportBean
    edu.ncsu.csc.itrust.beans.GroupReportBean report = this.action.generateReport(this.filters);
    // Populate the filter lists
    for (edu.ncsu.csc.itrust.report.ReportFilter filter : this.filters) {
        this.reportFilterTypes.add(filter.getFilterTypeString());
        this.reportFilterValues.add(filter.getFilterValue());
    }
    // Populate the header list with the DemographicReportFilters
    for (edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType type : edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType.values()) {
        if ((type != edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType.LOWER_AGE_LIMIT) && (type != edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType.UPPER_AGE_LIMIT)) {
            this.reportHeaders.add(type.toString());
        }
    }
    // Populate the header list with the MedicalReportFilters
    for (edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType type : edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.values()) {
        if ((type != edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.LOWER_OFFICE_VISIT_DATE) && (type != edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.UPPER_OFFICE_VISIT_DATE)) {
            this.reportHeaders.add(type.toString());
        }
        if (type == edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.LOWER_OFFICE_VISIT_DATE) {
            this.reportHeaders.add("OFFICE VISIT DATE");
        }
    }
    // Populate the header list with the PersonnelReportFilters
    for (edu.ncsu.csc.itrust.report.PersonnelReportFilter.PersonnelReportFilterType type : edu.ncsu.csc.itrust.report.PersonnelReportFilter.PersonnelReportFilterType.values()) {
        this.reportHeaders.add(type.toString());
    }
    // Loop through all the patients in the report
    for (edu.ncsu.csc.itrust.beans.PatientBean patient : report.getPatients()) {
        // Create a temporary ArrayList for the current patient's data
        java.util.ArrayList<java.lang.String> currentPatientData = new java.util.ArrayList<java.lang.String>();
        // Populate the current record with Demographic data
        for (edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType type : edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType.values()) {
            if ((type != edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType.LOWER_AGE_LIMIT) && (type != edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType.UPPER_AGE_LIMIT)) {
                java.lang.String val = this.action.getComprehensiveDemographicInfo(patient, type);
                if (val != null) {
                    currentPatientData.add(val);
                } else {
                    currentPatientData.add("");
                }
            }
        }
        // Populate the current record with Medical data
        for (edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType type : edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.values()) {
            if (type != edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.UPPER_OFFICE_VISIT_DATE) {
                java.lang.String val = this.action.getComprehensiveMedicalInfo(patient, type);
                if (val != null) {
                    currentPatientData.add(val);
                } else {
                    currentPatientData.add("");
                }
            }
        }
        // Populate the current record with Personnel data
        for (edu.ncsu.csc.itrust.report.PersonnelReportFilter.PersonnelReportFilterType type : edu.ncsu.csc.itrust.report.PersonnelReportFilter.PersonnelReportFilterType.values()) {
            java.lang.String val = this.action.getComprehensivePersonnelInfo(patient, type);
            if (val != null) {
                currentPatientData.add(val);
            } else {
                currentPatientData.add("");
            }
        }
        // Add the current record to the list of records
        this.reportData.add(currentPatientData);
    }
    // Remove MID from report
    int midIndex = this.reportHeaders.indexOf("MID");
    this.reportHeaders.remove(midIndex);
    for (java.util.ArrayList<java.lang.String> patients : this.reportData) {
        patients.remove(midIndex);
    }
}

