public java.util.List<edu.ncsu.csc.itrust.beans.RequiredProceduresBean> getNeededImmunizations(long pid, int ageGroup) throws edu.ncsu.csc.itrust.exception.DBException {
    // Get a list of all required immunizations that the patient does not yet have.
    java.util.List<edu.ncsu.csc.itrust.beans.ProcedureBean> patientImmunizations = this.getAllImmunizations(pid);
    java.util.List<edu.ncsu.csc.itrust.beans.RequiredProceduresBean> reqImmunizations = this.getRequiredImmunizations(pid, ageGroup);
    java.util.ArrayList<edu.ncsu.csc.itrust.beans.RequiredProceduresBean> neededImmunizations = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.RequiredProceduresBean>();
    for (edu.ncsu.csc.itrust.beans.RequiredProceduresBean reqProc : reqImmunizations) {
        boolean needsProc = true;
        for (edu.ncsu.csc.itrust.beans.ProcedureBean patientProc : patientImmunizations) {
            if (patientProc.getCPTCode().equals(reqProc.getCptCode())) {
                needsProc = false;
            }
        }
        if (needsProc) {
            neededImmunizations.add(reqProc);
        }
    }
    // Get a list of all appropriate diagnoses
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT * FROM officevisits " + "WHERE PatientID = ?");
        ps.setLong(1, pid);
        java.sql.ResultSet rs = ps.executeQuery();
        java.util.List<edu.ncsu.csc.itrust.beans.OfficeVisitBean> visits = this.visitLoader.loadList(rs);
        java.util.List<edu.ncsu.csc.itrust.beans.DiagnosisBean> diagnoses = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.DiagnosisBean>();
        if (diagnoses != null) {
            for (edu.ncsu.csc.itrust.beans.OfficeVisitBean visit : visits) {
                diagnoses.addAll(this.diagnosisDAO.getList(visit.getVisitID()));
            }
        }
        java.util.ArrayList<edu.ncsu.csc.itrust.beans.RequiredProceduresBean> returnList = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.RequiredProceduresBean>();
        for (edu.ncsu.csc.itrust.beans.RequiredProceduresBean needed : neededImmunizations) {
            boolean needsVaccine = true;
            for (edu.ncsu.csc.itrust.beans.DiagnosisBean diagnosis : diagnoses) {
                if (diagnosis.getICDCode().equals("35.00") && needed.getCptCode().equals("90396")) {
                    needsVaccine = false;
                }
            }
            if (needsVaccine) {
                returnList.add(needed);
            }
        }
        rs.close();
        return returnList;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

