public java.lang.Object produceDataset(@java.lang.SuppressWarnings("rawtypes")
java.util.Map params) throws de.laures.cewolf.DatasetProduceException {
    // The DefaultCategoryDataset is used for bar charts.
    // This dataset class may change based on the type of chart you wish to produce.
    org.jfree.data.category.DefaultCategoryDataset dataset = new org.jfree.data.category.DefaultCategoryDataset() {
        private static final long serialVersionUID = 1L;
    };
    java.util.Calendar cur = java.util.Calendar.getInstance();
    int curQuarter = cur.get(java.util.Calendar.MONTH) / 3;
    for (edu.ncsu.csc.itrust.beans.HealthRecord hRecord : this.healthRecords) {
        java.util.Calendar cal = java.util.Calendar.getInstance();
        cal.setTime(hRecord.getDateRecorded());
        int yearOfReport = cal.get(java.util.Calendar.YEAR);
        int monthOfReport = cal.get(java.util.Calendar.MONTH);
        int quarterOfReport = monthOfReport / 3;
        int quarter = ((edu.ncsu.csc.itrust.charts.HealthData.historyLength - (4 * (cur.get(java.util.Calendar.YEAR) - yearOfReport))) - (curQuarter - quarterOfReport)) - 1;
        // Skip entry if it is out of the history range.
        if (quarter < 0) {
            continue;
        }
        // Calculate the average for the quarter.
        double newValue = 0;
        if (this.codeName.equals("Height")) {
            newValue = hRecord.getHeight();
        } else if (this.codeName.equals("Weight")) {
            newValue = hRecord.getWeight();
        } else if (this.codeName.equals("BMI")) {
            newValue = (hRecord.getWeight() * 703) / (hRecord.getHeight() * hRecord.getHeight());
        }
        this.values[quarter] = ((this.values[quarter] * this.numEntries[quarter]) + newValue) / (this.numEntries[quarter] + 1);
        this.numEntries[quarter]++;
    }
    // For each month, add the monthly values to the dataset for
    // producing the chart.
    for (int i = 0; i < edu.ncsu.csc.itrust.charts.HealthData.historyLength; i++) {
        if (this.values[i] > 0) {
            dataset.addValue(this.values[i], this.codeName, this.quarters[i]);
        }
    }
    return dataset;
}

