    java.util.List<edu.ncsu.csc.itrust.beans.PersonnelBean> result = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.PersonnelBean>();
    if (((query != null) && (query.length() > 0)) && (!query.startsWith("_"))) {
        subqueries = query.split(" ");
        int i = 0;
        for (java.lang.String q : subqueries) {
            try {
                java.util.List<edu.ncsu.csc.itrust.beans.PersonnelBean> first = this.personnelDAO.fuzzySearchForExpertsWithName(q, "");
                java.util.List<edu.ncsu.csc.itrust.beans.PersonnelBean> last = this.personnelDAO.fuzzySearchForExpertsWithName("", q);
                for (int j = 0; j < last.size(); j++) {
                    if (!result.contains(last.get(j))) {
                        result.add(0, last.get(j));
                    }
                }
                for (int j = 0; j < first.size(); j++) {
                    if (!result.contains(first.get(j))) {
                        result.add(0, first.get(j));
                    }
                }
                i++;
            } catch (edu.ncsu.csc.itrust.exception.DBException e1) {
                e1.printStackTrace();
            }
        }
    }
    return result;
}

