/* This method will return a list of all of the procedures that the patient passed in will need in 
order to be covered for their age group.
 */
public java.util.List<edu.ncsu.csc.itrust.beans.RequiredProceduresBean> getNeededImmunizations(long pid, int ageGroup) throws edu.ncsu.csc.itrust.exception.DBException {
    java.util.List<edu.ncsu.csc.itrust.beans.RequiredProceduresBean> needed = this.requiredDAO.getNeededImmunizations(pid, ageGroup);
    java.util.List<edu.ncsu.csc.itrust.beans.RequiredProceduresBean> required = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.RequiredProceduresBean>();
    edu.ncsu.csc.itrust.beans.PatientBean patient = this.patDAO.getPatient(pid);
    int age = patient.getAge();
    java.util.Date dateofBirth = patient.getDateOfBirth();
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.set(1994, 1, 1);
    boolean over5 = false;
    boolean over18 = false;
    boolean mmrNeeded = true;
    boolean hepBneeded = true;
    // check to see if the patient is over the age of 5 and 18 respectively
    if (age >= 5) {
        over5 = true;
        if (age >= 18) {
            over18 = true;
        }
    }
    // check to see if the patient was born BEFORE 1994 and 1957 respectively.
    if (dateofBirth.before(cal.getTime())) {
        hepBneeded = false;
        cal.set(1957, 1, 1);
        if (dateofBirth.before(cal.getTime())) {
            mmrNeeded = false;
        }
    }
    // add the required procedures to the list, checking our controlling variables for extenuating vaccinations
    for (edu.ncsu.csc.itrust.beans.RequiredProceduresBean p : needed) {
        boolean needs = true;
        if (p.getCptCode().equals("90645") && over5) {
            needs = false;
        }
        if (p.getCptCode().equals("90712") && over18) {
            needs = false;
        }
        if (p.getCptCode().equals("90707") && (!mmrNeeded)) {
            needs = false;
        }
        if (p.getCptCode().equals("90371") && (!hepBneeded)) {
            needs = false;
        }
        if (needs) {
            required.add(p);
        }
    }
    // RETURN THAT SHIT
    return required;
}

