public java.util.List<edu.ncsu.csc.itrust.beans.SleepEntryBean> getBoundedDiaryTotals(java.lang.String lowerDate, java.lang.String upperDate, long patientMID) throws edu.ncsu.csc.itrust.exception.ITrustException, edu.ncsu.csc.itrust.exception.FormValidationException {
    try {
        /* This nightmare if-statement just checks for two things. Either:
        1) The patient is viewing their own diary.
        2) A HCP is viewing the diary.
         */
        if ((this.patientDAO.checkPatientExists(this.loggedInMID) && (this.loggedInMID == patientMID)) || (this.personnelDAO.getPersonnel(this.loggedInMID) != null)) {
            /* Month can have 1 or 2 digits, same with day, and year must
            have 4.
             */
            java.util.regex.Pattern p = java.util.regex.Pattern.compile("[0-9]{1,2}?/[0-9]{1,2}?/[0-9]{4}?");
            java.util.regex.Matcher m = p.matcher(lowerDate);
            java.util.regex.Matcher n = p.matcher(upperDate);
            /* If it fails to match either of them, throw the form
            validation exception
             */
            if ((!m.matches()) || (!n.matches())) {
                throw new edu.ncsu.csc.itrust.exception.FormValidationException("Enter dates in MM/dd/yyyy");
            }
            java.util.Date lower = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(lowerDate);
            java.util.Date upper = new java.text.SimpleDateFormat("MM/dd/yyyy").parse(upperDate);
            if (lower.after(upper)) {
                throw new edu.ncsu.csc.itrust.exception.FormValidationException("Start date must be before end date!");
            }
            return this.sleepEntryDAO.getBoundedSleepDiaryTotals(lower, upper, patientMID);
        } else {
            throw new edu.ncsu.csc.itrust.exception.ITrustException("You do not have permission to " + "view the Sleep Diary!");
        }
    } catch (edu.ncsu.csc.itrust.exception.DBException e) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Error retrieving Sleep Diary");
    } catch (java.text.ParseException d) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException("Error parsing Dates");
    }
}

