private void buildMappings(java.util.ArrayList<java.lang.String> CSVHeader) throws edu.ncsu.csc.itrust.exception.AddPatientFileException {
    boolean valid;
    for (int i = 0; i < CSVHeader.size(); i++) {
        valid = false;
        for (int j = 0; j < this.requiredFields.length; j++) {
            if (CSVHeader.get(i).equalsIgnoreCase(this.requiredFields[j])) {
                if (this.requiredFieldsMapping[j] == null) {
                    valid = true;
                    this.requiredFieldsMapping[j] = i;
                } else {
                    throw new edu.ncsu.csc.itrust.exception.AddPatientFileException(("Duplicate field \"" + CSVHeader.get(i)) + "\"!");
                }
            }
        }
        for (int j = 0; j < this.validFields.length; j++) {
            if (CSVHeader.get(i).equalsIgnoreCase(this.validFields[j])) {
                if (this.validFieldsMapping[j] == null) {
                    valid = true;
                    this.validFieldsMapping[j] = i;
                } else {
                    throw new edu.ncsu.csc.itrust.exception.AddPatientFileException(("Duplicate field \"" + CSVHeader.get(i)) + "\"!");
                }
            }
        }
        if (valid == false) {
            throw new edu.ncsu.csc.itrust.exception.AddPatientFileException(("Field \"" + CSVHeader.get(i)) + "\" is invalid!");
        }
    }
    for (int i = 0; i < this.requiredFieldsMapping.length; i++) {
        if (this.requiredFieldsMapping[i] == null) {
            throw new edu.ncsu.csc.itrust.exception.AddPatientFileException(("Required field \"" + this.requiredFields[i]) + "\" is missing!");
        }
    }
}

