public boolean hasData() {
    java.util.Date threeYearsAgo = new java.util.Date();
    java.util.Date recDate;
    java.lang.String dateStr;
    java.text.DateFormat year = new java.text.SimpleDateFormat("yyyy");
    java.text.DateFormat rest = new java.text.SimpleDateFormat("/MM/dd HHmma");
    java.text.DateFormat sdf = new java.text.SimpleDateFormat("yyyy/MM/dd HHmma");
    dateStr = year.format(threeYearsAgo);
    dateStr = "" + (java.lang.Integer.parseInt(dateStr) - 3);
    dateStr += rest.format(threeYearsAgo);
    try {
        threeYearsAgo = sdf.parse(dateStr);
    } catch (java.text.ParseException e) {
        return false;
    }
    for (edu.ncsu.csc.itrust.beans.LabProcedureBean lpb : this.lpBeans) {
        recDate = new java.util.Date(lpb.getTimestamp().getTime());
        if (recDate.before(threeYearsAgo)) {
            continue;
        } else {
            return true;
        }
    }
    return false;
}

public java.util.List<edu.ncsu.csc.itrust.beans.MessageBean> getMessagesFromNameDescending(long mid) throws java.sql.SQLException, edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    java.sql.ResultSet rs;
    try {
        conn = this.factory.getConnection();
        if (mid >= 999999999) {
            ps = conn.prepareStatement("SELECT message.* FROM message, patients WHERE message.to_id=patients.mid AND message.from_id=? ORDER BY patients.lastName DESC, patients.firstName DESC, message.sent_date DESC");
            ps.setLong(1, mid);
