public java.util.List<edu.ncsu.csc.itrust.beans.FoodEntryBean> getPatientFoodDiaryTotals(long patientMID) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstring = null;
    try {
        conn = this.factory.getConnection();
        /* We don't care about the mealtype, foodname, or servings but we
        need to have some for the loader, so just bring back whatever.
         */
        pstring = conn.prepareStatement("SELECT DateEaten AS DateEaten, " + ((((((((((((("EntryID AS EntryID, MealType AS MealType, " + "FoodName AS FoodName, ") + "Servings AS Servings, ") + "SUM(Servings * Calories) AS Calories, ") + "SUM(Servings * Fat) AS Fat, ") + "SUM(Servings * Sodium) AS Sodium, ") + "SUM(Servings * Carbs) AS Carbs, ") + "SUM(Servings * Sugar) AS Sugar, ") + "SUM(Servings * Fiber) AS Fiber, ") + "SUM(Servings * Protein) AS Protein, ") + "PatientID AS PatientID, ") + "LabelID AS LabelID FROM foodEntry ") + "WHERE PatientID = ? GROUP BY DateEaten ") + "ORDER BY DateEaten DESC"));
        pstring.setLong(1, patientMID);
        final java.sql.ResultSet results = pstring.executeQuery();
        final java.util.List<edu.ncsu.csc.itrust.beans.FoodEntryBean> diaryTotals = this.foodLoader.loadList(results);
        results.close();
        pstring.close();
        return diaryTotals;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstring);
    }
}

