public boolean hadChildhoodInfection(final long patientID, final double... icdCodes) throws edu.ncsu.csc.itrust.exception.DBException {
    // Note the datediff call - this is a MySQL function
    // that takes the difference between two dates
    // and returns that value in terms of days.
    // 6570 days is 18 years (not counting leap years)
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstmt = null;
    try {
        conn = this.factory.getConnection();
        pstmt = conn.prepareStatement((("SELECT * FROM ovdiagnosis ovd, officevisits ov, patients p " + ("WHERE ovd.visitID=ov.id AND ov.patientid=p.mid AND p.mid=? " + "AND datediff(ov.visitdate,p.dateofbirth) < 6570 AND ovd.icdcode IN (")) + this.createPrepared(icdCodes.length)) + ")");
        pstmt.setLong(1, patientID);
        this.setICDs(2, pstmt, icdCodes);
        final boolean returnVal = pstmt.executeQuery().next();
        pstmt.close();
        return returnVal;// if this query has ANY rows, then yes

    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstmt);
