protected java.lang.String checkInt(java.lang.String name, java.lang.String value, int lower, int upper, boolean isNullable) {
    if (isNullable && ((value == null) || "".equals(value))) {
        return "";
    }
    try {
        int intValue = java.lang.Integer.valueOf(value);
        if ((lower <= intValue) && (intValue <= upper)) {
            return "";
        }
    } catch (java.lang.NumberFormatException e) {
        // just fall through to returning the error message
    }
    return ((((name + " must be an integer in [") + lower) + ",") + upper) + "]";
}

