public boolean addPatientToList(final long patientMID, final long HCPMID, final edu.ncsu.csc.itrust.beans.TelemedicineBean tBean) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement pstmt = null;
    boolean added = true;
    try {
        conn = this.factory.getConnection();
        pstmt = conn.prepareStatement("SELECT * FROM remotemonitoringlists WHERE PatientMID = ? AND HCPMID = ?");
        pstmt.setLong(1, patientMID);
        pstmt.setLong(2, HCPMID);
        final java.sql.ResultSet results = pstmt.executeQuery();
        if (results.next()) {
            results.close();
            pstmt.close();
            added = false;
        } else {
            java.lang.String permissionPS = "SystolicBloodPressure, DiastolicBloodPressure, GlucoseLevel, Height, Weight, PedometerReading";
            results.close();
            pstmt.close();
            pstmt = conn.prepareStatement(("INSERT INTO remotemonitoringlists(PatientMID, HCPMID, " + permissionPS) + ") VALUES(?,?,?,?,?,?,?,?)");
            pstmt.setLong(1, patientMID);
            pstmt.setLong(2, HCPMID);
            pstmt.setBoolean(3, tBean.isSystolicBloodPressureAllowed());
            pstmt.setBoolean(4, tBean.isDiastolicBloodPressureAllowed());
            pstmt.setBoolean(5, tBean.isGlucoseLevelAllowed());
            pstmt.setBoolean(6, tBean.isHeightAllowed());
            pstmt.setBoolean(7, tBean.isWeightAllowed());
            pstmt.setBoolean(8, tBean.isPedometerReadingAllowed());
            pstmt.executeUpdate();
            pstmt.close();
        }
        return added;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, pstmt);
    }
}

