protected void doGet(javax.servlet.http.HttpServletRequest request, javax.servlet.http.HttpServletResponse response) throws javax.servlet.ServletException, java.io.IOException {
    java.lang.String query = request.getParameter("q");
    if (query == null) {
        return;
    }
    boolean isAudit = (request.getParameter("isAudit") != null) && request.getParameter("isAudit").equals("true");
    boolean deactivated = (request.getParameter("allowDeactivated") != null) && request.getParameter("allowDeactivated").equals("checked");
    java.lang.String forward = request.getParameter("forward");
    java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> search = null;
    if (query.isEmpty() && deactivated) {
        search = this.sua.getDeactivated();
    } else {
        search = this.sua.fuzzySearchForPatients(query, deactivated);
    }
    java.lang.StringBuffer result = new java.lang.StringBuffer(("<span class=\"searchResults\">Found " + search.size()) + " Records</span>");
    if (isAudit) {
        result.append("<table class='fTable' width=80%><tr><th width=10%>MID</th><th width=20%>First Name</th><th width=20%>Last Name</th><th width=30%>Status</th><th width=20%>Action</th></tr>");
        for (edu.ncsu.csc.itrust.beans.PatientBean p : search) {
            boolean isActivated = (p.getDateOfDeactivationStr() == null) || p.getDateOfDeactivationStr().isEmpty();
            java.lang.String change = (isActivated) ? "Deactivate" : "Activate";
            result.append("<tr>");
            result.append(("<td>" + p.getMID()) + "</td>");
            result.append(("<td>" + p.getFirstName()) + "</td>");
            result.append(("<td>" + p.getLastName()) + "</td>");
            if (isActivated) {
                result.append(((("<td>" + p.getFirstName()) + " ") + p.getLastName()) + " is activated.</td>");
            } else {
                result.append(((((("<td>" + p.getFirstName()) + " ") + p.getLastName()) + " deactivated on: ") + p.getDateOfDeactivationStr()) + "</td>");
            }
            result.append("<td>");
            result.append(((((("<input type=\'button\' style=\'width:100px;\' onclick=\"parent.location.href=\'getPatientID.jsp?UID_PATIENTID=" + org.apache.commons.lang.StringEscapeUtils.escapeHtml("" + p.getMID())) + "&forward=") + org.apache.commons.lang.StringEscapeUtils.escapeHtml("" + forward)) + "\';\" value=") + org.apache.commons.lang.StringEscapeUtils.escapeHtml("" + change)) + " />");
            result.append("</td></tr>");
        }
        result.append("<table>");
    } else {
        result.append("<table class='fTable' width=80%><tr><th width=20%>MID</th><th width=40%>First Name</th><th width=40%>Last Name</th></tr>");
        for (edu.ncsu.csc.itrust.beans.PatientBean p : search) {
            result.append("<tr>");
            result.append("<td>");
            result.append(((((("<input type=\'button\' style=\'width:100px;\' onclick=\"parent.location.href=\'getPatientID.jsp?UID_PATIENTID=" + org.apache.commons.lang.StringEscapeUtils.escapeHtml("" + p.getMID())) + "&forward=") + org.apache.commons.lang.StringEscapeUtils.escapeHtml("" + forward)) + "\';\" value=") + org.apache.commons.lang.StringEscapeUtils.escapeHtml("" + p.getMID())) + " />");
            result.append("</td>");
            result.append(("<td>" + p.getFirstName()) + "</td>");
            result.append(("<td>" + p.getLastName()) + "</td>");
            result.append("</tr>");
        }
        result.append("</table>");
    }
    response.setContentType("text/plain");
    java.io.PrintWriter resp = response.getWriter();
    resp.write(result.toString());
}

