protected java.util.List<edu.ncsu.csc.itrust.risk.factors.PatientRiskFactor> getDiseaseRiskFactors() {
    java.util.List<edu.ncsu.csc.itrust.risk.factors.PatientRiskFactor> factors = new java.util.ArrayList<edu.ncsu.csc.itrust.risk.factors.PatientRiskFactor>();
    factors.add(new edu.ncsu.csc.itrust.risk.factors.AgeFactor(this.patient, 45));
    factors.add(new edu.ncsu.csc.itrust.risk.factors.EthnicityFactor(this.patient, edu.ncsu.csc.itrust.enums.Ethnicity.Hispanic, edu.ncsu.csc.itrust.enums.Ethnicity.AfricanAmerican, edu.ncsu.csc.itrust.enums.Ethnicity.AmericanIndian, edu.ncsu.csc.itrust.enums.Ethnicity.Asian));
    factors.add(new edu.ncsu.csc.itrust.risk.factors.WeightFactor(this.currentHealthRecord, 25));
    factors.add(new edu.ncsu.csc.itrust.risk.factors.HypertensionFactor(this.currentHealthRecord));
