public java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> getFamilyHistory() throws edu.ncsu.csc.itrust.exception.ITrustException {
    java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> fam = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.FamilyMemberBean>();
    java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> parents = null;
    try {
        parents = this.familyDAO.getParents(this.loggedInMID);
        fam.addAll(parents);
        fam.addAll(this.familyDAO.getSiblings(this.loggedInMID));
    } catch (edu.ncsu.csc.itrust.exception.DBException e) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException(e.getMessage());
    }
    if (parents != null) {
        java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> grandparents = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.FamilyMemberBean>();
        for (edu.ncsu.csc.itrust.beans.FamilyMemberBean parent : parents) {
            try {
                grandparents.addAll(this.familyDAO.getParents(parent.getMid()));
            } catch (edu.ncsu.csc.itrust.exception.DBException e) {
                throw new edu.ncsu.csc.itrust.exception.ITrustException(e.getMessage());
            }
        }
        fam.addAll(grandparents);
        for (edu.ncsu.csc.itrust.beans.FamilyMemberBean gp : grandparents) {
            gp.setRelation("Grandparent");
        }
    }
    return fam;
}

