public double getHeightZScore(edu.ncsu.csc.itrust.beans.HealthRecord record) throws edu.ncsu.csc.itrust.exception.DBException {
    // Get the CDCStatsBean for a patient's height at his or her age
    edu.ncsu.csc.itrust.beans.CDCStatsBean statsBean = this.getCDCStatsBean(record, this.heightStatsDAO);
    // If there is no matching entry in the CDC Stats table then return -999
    if (statsBean == null) {
        return -999;
    }
    // Get the height in centimeters
    double height = record.getHeight() / edu.ncsu.csc.itrust.action.ViewHealthRecordsHistoryAction.INCHES_IN_CM;
    // Get the z score for the patient's height
    double zScore = this.getZScore(statsBean, height);
    return zScore;
}

