    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

private java.util.List<edu.ncsu.csc.itrust.beans.HCPVisitBean> getAllVisitedHCPs(java.lang.String lastName, java.lang.String specialty, java.lang.String zip) throws edu.ncsu.csc.itrust.exception.ITrustException {
    // Visited HCPs in this case includes both HCPs visited *and* HCPs
    // designated by the patient.  These two groups are retrieved in
    // different ways, then combined.
    java.util.List<edu.ncsu.csc.itrust.beans.HCPVisitBean> visits = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.HCPVisitBean>();
    try {
        java.util.List<edu.ncsu.csc.itrust.beans.OfficeVisitBean> ovlist = this.visitDAO.getAllOfficeVisits(this.patientMID);
        // get most recent office visit for each provider
        java.util.LinkedHashMap<java.lang.Long, edu.ncsu.csc.itrust.beans.OfficeVisitBean> mostRecentVisits = new java.util.LinkedHashMap<java.lang.Long, edu.ncsu.csc.itrust.beans.OfficeVisitBean>();
        for (edu.ncsu.csc.itrust.beans.OfficeVisitBean ov : ovlist) {
            long id = ov.getHcpID();
            if (!mostRecentVisits.containsKey(id)) {
                mostRecentVisits.put(id, ov);
            } else {
                edu.ncsu.csc.itrust.beans.OfficeVisitBean old = mostRecentVisits.get(id);
                java.util.Date ovDate = ov.getVisitDate();
                java.util.Date oldDate = old.getVisitDate();
                if (oldDate.before(ovDate)) {
                    mostRecentVisits.put(id, ov);
                }
            }
        }
        // Get visited HCPs.
        for (edu.ncsu.csc.itrust.beans.OfficeVisitBean ov : mostRecentVisits.values()) {
            long hcpid = ov.getHcpID();
            edu.ncsu.csc.itrust.beans.PersonnelBean pb = this.docDAO.getPersonnel(hcpid);
            if (this.matchPersonnel(pb, lastName, specialty, zip)) {
                edu.ncsu.csc.itrust.beans.HCPVisitBean visitBean = this.makeHCPVisitBean(pb, mostRecentVisits.get(hcpid).getVisitDateStr());
                visits.add(visitBean);
            }
        }
        // Get all designated HCPs.  Because a designated HCP may have been
        // visited, we will ensure the HCP is not already in the list.
        java.util.List<edu.ncsu.csc.itrust.beans.PersonnelBean> dhcps = this.patientDAO.getDeclaredHCPs(this.patientMID);
        next : for (edu.ncsu.csc.itrust.beans.PersonnelBean pb : dhcps) {
            if (this.matchPersonnel(pb, lastName, specialty, zip)) {
                long hcpid = pb.getMID();
                // if HCP is already in visits list, skip here
                for (edu.ncsu.csc.itrust.beans.HCPVisitBean hv : visits) {
                    if (hv.getHCPMID() == hcpid) {
                        continue next;
                    }
                }
                java.lang.String date = "";
                edu.ncsu.csc.itrust.beans.HCPVisitBean visitBean = this.makeHCPVisitBean(pb, date);
                visits.add(visitBean);
            }
        }
    } catch (edu.ncsu.csc.itrust.exception.DBException dbe) {
        throw new edu.ncsu.csc.itrust.exception.ITrustException(dbe.getMessage());
    }
    return visits;
}

