public boolean isRateable(long mid, long pid) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    java.sql.ResultSet rs = null;
    boolean isRateable = false;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT * FROM appointment WHERE patient_id =? AND doctor_id=?");
        ps.setLong(1, mid);
        ps.setLong(2, pid);
        rs = ps.executeQuery();
        isRateable = rs.next();
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
        if (rs != null) {
            try {
                rs.close();
            } catch (java.sql.SQLException e) {
                throw new edu.ncsu.csc.itrust.exception.DBException(e);
            }
        }
    }
    if (!isRateable) {
        try {
            conn = this.factory.getConnection();
            ps = conn.prepareStatement("SELECT * FROM officevisits WHERE PatientID=? AND HCPID=?");
            ps.setLong(1, mid);
            ps.setLong(2, pid);
            rs = ps.executeQuery();
            isRateable = rs.next();
            rs.close();
        } catch (java.sql.SQLException e) {
            throw new edu.ncsu.csc.itrust.exception.DBException(e);
        } finally {
            edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
            if (rs != null) {
                try {
                    rs.close();
                } catch (java.sql.SQLException e) {
                    throw new edu.ncsu.csc.itrust.exception.DBException(e);
                }
            }
        }
    }
    return isRateable;
}

