    edu.ncsu.csc.itrust.beans.PersonnelBean personnel;
    try {
        if ((this.patientDAO.checkPatientExists(this.loggedInMID) && (this.loggedInMID == patientMID)) || (((personnel = this.personnelDAO.getPersonnel(this.loggedInMID)) != null) && personnel.getSpecialty().equalsIgnoreCase("Nutritionist"))) {
