public java.util.List<edu.ncsu.csc.itrust.beans.RecordsReleaseBean> getHospitalReleaseRequests() throws edu.ncsu.csc.itrust.exception.ITrustException {
    // List for holding records release requests
    java.util.List<edu.ncsu.csc.itrust.beans.RecordsReleaseBean> releases = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.RecordsReleaseBean>();
    // List of hospitals that the hcp/uap is associated with
    java.util.List<edu.ncsu.csc.itrust.beans.HospitalBean> hospitals;
    // Get the logged in user's role
    edu.ncsu.csc.itrust.enums.Role userRole;
    try {
        // Check the user's role and get a list of hospitals depending on that
        userRole = this.authDAO.getUserRole(this.loggedInMID);
        if (userRole.getUserRolesString().equals("hcp")) {
            hospitals = this.personnelDAO.getHospitals(this.loggedInMID);
        } else if (userRole.getUserRolesString().equals("uap")) {
            hospitals = this.personnelDAO.getUAPHospitals(this.loggedInMID);
        } else {
            return new java.util.ArrayList<edu.ncsu.csc.itrust.beans.RecordsReleaseBean>();
        }
        // Add to the list of records release requests from each associated hospital
        for (int i = 0; i < hospitals.size(); i++) {
            // Get each hospital's id
            java.lang.String hospitalID = hospitals.get(i).getHospitalID();
            releases.addAll(this.releaseDAO.getAllRecordsReleasesByHospital(hospitalID));
        }
    } catch (edu.ncsu.csc.itrust.exception.DBException e) {
        // If there is a DBException return an empty list
        return new java.util.ArrayList<edu.ncsu.csc.itrust.beans.RecordsReleaseBean>();
    }
    return releases;
}

