public java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> fuzzySearchForPatients(java.lang.String query, boolean allowDeactivated) {
    java.lang.String[] subqueries = null;
    java.util.Set<edu.ncsu.csc.itrust.beans.PatientBean> patientsSet = new java.util.TreeSet<edu.ncsu.csc.itrust.beans.PatientBean>();
    if (((query != null) && (query.length() > 0)) && (!query.startsWith("_"))) {
        subqueries = query.split(" ");
        java.util.Set<edu.ncsu.csc.itrust.beans.PatientBean>[] patients = new java.util.Set[subqueries.length];
        int i = 0;
        for (java.lang.String q : subqueries) {
            try {
                patients[i] = new java.util.TreeSet<edu.ncsu.csc.itrust.beans.PatientBean>();
                java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> first = this.patientDAO.fuzzySearchForPatientsWithName(q, "");
                java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> last = this.patientDAO.fuzzySearchForPatientsWithName("", q);
                patients[i].addAll(first);
                patients[i].addAll(last);
                try {
                    long mid = java.lang.Long.valueOf(q);
                    // If the patient exists with the mid, then add the patient to the patient list
                    java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> searchMID = this.patientDAO.fuzzySearchForPatientsWithMID(mid);
                    patients[i].addAll(searchMID);
                    // old way of doing it when they only were returning one person
                    // now that we are returning everybody with that as a substring in their MID, not necessary
                    // yet want to keep it in case we revert sometime
                } catch (java.lang.NumberFormatException e) {
                    // TODO
                }
                i++;
            } catch (edu.ncsu.csc.itrust.exception.DBException e1) {
                e1.printStackTrace();
            }
        }
        if (i > 0) {
            patientsSet.addAll(patients[0]);
        }
        for (java.util.Set<edu.ncsu.csc.itrust.beans.PatientBean> results : patients) {
            try {
                patientsSet.retainAll(results);
            } catch (java.lang.NullPointerException e) {
                // TODO
            }
        }
    }
    java.util.ArrayList<edu.ncsu.csc.itrust.beans.PatientBean> results = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.PatientBean>(patientsSet);
    if (allowDeactivated == false) {
        for (int i = results.size() - 1; i >= 0; i--) {
            if (!results.get(i).getDateOfDeactivationStr().equals("")) {
                results.remove(i);
            }
        }
    }
    java.util.Collections.reverse(results);
    return results;
}

