public java.lang.String resetPassword(long mid, java.lang.String role, java.lang.String answer, java.lang.String password, java.lang.String confirmPassword, java.lang.String ipAddr) throws edu.ncsu.csc.itrust.exception.FormValidationException, edu.ncsu.csc.itrust.exception.ITrustException {
    edu.ncsu.csc.itrust.enums.Role r = this.authDAO.getUserRole(mid);
    try {
        edu.ncsu.csc.itrust.enums.Role.parse(role);
    } catch (java.lang.IllegalArgumentException e) {
        return "Invalid role";
    }
    if (r.equals(edu.ncsu.csc.itrust.enums.Role.ADMIN)) {
        return "This role cannot be changed here";
    }
    if (!r.equals(edu.ncsu.csc.itrust.enums.Role.parse(role))) {
        return "Role mismatch";
    }
    if (this.authDAO.getResetPasswordFailures(ipAddr) >= edu.ncsu.csc.itrust.action.ResetPasswordAction.MAX_RESET_ATTEMPTS) {
        return "Too many retries";
    }
    try {
        this.validatePassword(password, confirmPassword);
        if (answer.equals(this.authDAO.getSecurityAnswer(mid))) {
            this.authDAO.resetPassword(mid, password);
            new edu.ncsu.csc.itrust.EmailUtil(this.factory).sendEmail(this.makeEmailApp(mid, role));
            return "Password changed";
        } else {
            this.authDAO.recordResetPasswordFailure(ipAddr);
            return "Answer did not match";
        }
    } catch (edu.ncsu.csc.itrust.exception.DBException e) {
        return "Error in validation of security answer";
    }
}

