public void setFlag(edu.ncsu.csc.itrust.beans.FlagsBean p) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("SELECT * FROM flags WHERE MID = ? AND pregId = ? AND flagType = ?");
        ps.setLong(1, p.getMid());
        ps.setLong(2, p.getPregId());
        ps.setString(3, p.getFlagValue().toString());
        java.sql.ResultSet rs = ps.executeQuery();
        // if the result exists
        if (rs.next()) {
            // if it's set to false, delete from the DB
            if (!p.isFlagged()) {
                rs.close();
                ps.close();
                ps = conn.prepareStatement("DELETE FROM flags WHERE MID = ? AND pregId=? AND flagType = ?");
                ps.setLong(1, p.getMid());
                ps.setLong(2, p.getPregId());
                ps.setString(3, p.getFlagValue().toString());
                ps.execute();
            }
            // else, it's true and it exists so nothing needs to change
            rs.close();
            ps.close();
        } else // else, it doesn't exist in the DB
        {
            // if it's true, add it
            if (p.isFlagged()) {
                rs.close();
                ps.close();
                ps = conn.prepareStatement("INSERT INTO flags VALUES(?, ?, ?, ?)");
                this.flagsLoader.loadParameters(ps, p);
                ps.execute();
            }
            // else, it's false, so ignore it
        }
        ps.close();
    } catch (java.sql.SQLException e) {
        e.printStackTrace();
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

