        CSVScanner = new java.util.Scanner(new java.io.InputStreamReader(csvstream, "UTF-8"));
    } catch (java.io.UnsupportedEncodingException e) {
        try {
            // Try the default
            CSVScanner = new java.util.Scanner(new java.io.InputStreamReader(csvstream, java.nio.charset.Charset.defaultCharset().displayName()));
        } catch (java.io.UnsupportedEncodingException e1) {
            throw new edu.ncsu.csc.itrust.exception.CSVFormatException("Encoding errors!");
        }
    }
    this.parseCSV(CSVScanner);
}

