public void initializeLabProcedures(java.util.List<edu.ncsu.csc.itrust.beans.LabProcedureBean> lpbs, java.lang.String name) {
    this.lpBeans = lpbs;
    this.labProcedureName = name;
    this.quarters = new java.lang.String[edu.ncsu.csc.itrust.charts.PatientLabResults.historyLength];
    this.values = new double[edu.ncsu.csc.itrust.charts.PatientLabResults.historyLength];
    this.numEntries = new int[edu.ncsu.csc.itrust.charts.PatientLabResults.historyLength];
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.add(java.util.Calendar.MONTH, (-3) * (edu.ncsu.csc.itrust.charts.PatientLabResults.historyLength - 1));
    int startMonth = cal.get(java.util.Calendar.MONTH);
    int startQ = startMonth / 3;
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yy");
    for (int i = 0; i < edu.ncsu.csc.itrust.charts.PatientLabResults.historyLength; i++) {
        this.quarters[i] = (("Q" + (((startQ + i) % 4) + 1)) + " '") + sdf.format(cal.getTime());
        this.values[i] = 0;
        this.numEntries[i] = 0;
        cal.add(java.util.Calendar.MONTH, 3);
    }
}

