public java.lang.String getComprehensiveDemographicInfo(edu.ncsu.csc.itrust.beans.PatientBean patient, edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType filterType) {
    switch (filterType) {
        case GENDER :
            return patient.getGender().toString();
        case LAST_NAME :
            return patient.getLastName();
        case FIRST_NAME :
            return patient.getFirstName();
        case CONTACT_EMAIL :
            return patient.getEmail();
        case STREET_ADDR :
            return (patient.getStreetAddress1() + " ") + patient.getStreetAddress2();
        case CITY :
            return patient.getCity();
        case STATE :
            return patient.getState();
        case ZIP :
            return patient.getZip();
        case PHONE :
            return patient.getPhone();
        case EMER_CONTACT_NAME :
            return patient.getEmergencyName();
        case EMER_CONTACT_PHONE :
            return patient.getEmergencyPhone();
        case INSURE_NAME :
            return patient.getIcName();
        case INSURE_ADDR :
            return (patient.getIcAddress1() + " ") + patient.getIcAddress2();
        case INSURE_CITY :
            return patient.getIcCity();
        case INSURE_STATE :
            return patient.getIcState();
        case INSURE_ZIP :
            return patient.getIcZip();
        case INSURE_PHONE :
            return patient.getIcPhone();
        case MID :
            return java.lang.Long.toString(patient.getMID());
        case INSURE_ID :
            return patient.getIcID();
        case PARENT_FIRST_NAME :
            try {
                java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> parents = this.fDAO.getParents(patient.getMID());
                java.lang.StringBuffer buff = new java.lang.StringBuffer();
                for (edu.ncsu.csc.itrust.beans.FamilyMemberBean parent : parents) {
                    buff.append(parent.getFirstName());
                    buff.append("\n");
                }
                java.lang.String out = buff.toString();
                return out;
            } catch (java.lang.Exception e) {
                break;
            }
        case PARENT_LAST_NAME :
            try {
                java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> parents = this.fDAO.getParents(patient.getMID());
                java.lang.StringBuffer buff = new java.lang.StringBuffer();
                for (edu.ncsu.csc.itrust.beans.FamilyMemberBean parent : parents) {
                    buff.append(parent.getLastName());
                    buff.append("\n");
                }
                java.lang.String out = buff.toString();
                return out;
            } catch (java.lang.Exception e) {
                break;
            }
        case CHILD_FIRST_NAME :
            try {
                java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> children = this.fDAO.getChildren(patient.getMID());
                java.lang.StringBuffer buff = new java.lang.StringBuffer();
                for (edu.ncsu.csc.itrust.beans.FamilyMemberBean child : children) {
                    buff.append(child.getFirstName());
                    buff.append("\n");
                }
                java.lang.String out = buff.toString();
                return out;
            } catch (java.lang.Exception e) {
                break;
            }
        case CHILD_LAST_NAME :
            try {
                java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> children = this.fDAO.getChildren(patient.getMID());
                java.lang.StringBuffer buff = new java.lang.StringBuffer();
                for (edu.ncsu.csc.itrust.beans.FamilyMemberBean child : children) {
                    buff.append(child.getLastName());
                    buff.append("\n");
                }
                java.lang.String out = buff.toString();
                return out;
            } catch (java.lang.Exception e) {
                break;
            }
        case SIBLING_FIRST_NAME :
            try {
                java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> siblings = this.fDAO.getSiblings(patient.getMID());
                java.lang.StringBuffer buff = new java.lang.StringBuffer();
                for (edu.ncsu.csc.itrust.beans.FamilyMemberBean sibling : siblings) {
                    buff.append(sibling.getFirstName());
                    buff.append("\n");
                }
                java.lang.String out = buff.toString();
                return out;
            } catch (java.lang.Exception e) {
                break;
            }
        case SIBLING_LAST_NAME :
            try {
                java.util.List<edu.ncsu.csc.itrust.beans.FamilyMemberBean> siblings = this.fDAO.getSiblings(patient.getMID());
                java.lang.StringBuffer buff = new java.lang.StringBuffer();
                for (edu.ncsu.csc.itrust.beans.FamilyMemberBean sibling : siblings) {
                    buff.append(sibling.getLastName());
                    buff.append("\n");
                }
                java.lang.String out = buff.toString();
                return out;
            } catch (java.lang.Exception e) {
                break;
            }
        case DEACTIVATED :
            return patient.getDateOfDeactivationStr();
        default :
            break;
    }
    return null;
}

