public double getBMIZScore(edu.ncsu.csc.itrust.beans.HealthRecord record) throws edu.ncsu.csc.itrust.exception.DBException {
    // Get the CDCStatsBean for a patient's BMI at his or her age
    edu.ncsu.csc.itrust.beans.CDCStatsBean statsBean = this.getCDCStatsBean(record, this.bmiStatsDAO);
    // If there is no matching entry in the CDC Stats table then return -999
    if (statsBean == null) {
        return -999;
    }
    // Get the bmi of the patient
    double bmi = record.getBodyMassIndex();
    // Get the z score for the patient's bmi
    double zScore = this.getZScore(statsBean, bmi);
    return zScore;
}

