public java.lang.String addAppt(edu.ncsu.csc.itrust.beans.ApptBean appt, boolean ignoreConflicts) throws edu.ncsu.csc.itrust.exception.FormValidationException, java.sql.SQLException, edu.ncsu.csc.itrust.exception.DBException {
