public void validate(edu.ncsu.csc.itrust.beans.LOINCbean m) throws edu.ncsu.csc.itrust.exception.FormValidationException {
    edu.ncsu.csc.itrust.exception.ErrorList errorList = new edu.ncsu.csc.itrust.exception.ErrorList();
    if (((m.getLabProcedureCode() == null) || (m.getComponent() == null)) || (m.getKindOfProperty() == null)) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException("You must have a Lab Procedure Code, Component and Kind Of Property");
    }
    errorList.addIfNotNull(this.checkFormat("LaboratoryProcedureCode", m.getLabProcedureCode(), edu.ncsu.csc.itrust.validate.ValidationFormat.LOINC, false));
    errorList.addIfNotNull(this.checkFormat("Component", m.getComponent(), edu.ncsu.csc.itrust.validate.ValidationFormat.LOINC_ITEM, false));
    errorList.addIfNotNull(this.checkFormat("KindOfProperty", m.getKindOfProperty(), edu.ncsu.csc.itrust.validate.ValidationFormat.LOINC_ITEM, false));
    errorList.addIfNotNull(this.checkFormat("TimeAspect", m.getTimeAspect(), edu.ncsu.csc.itrust.validate.ValidationFormat.LOINC_ITEM, true));
    errorList.addIfNotNull(this.checkFormat("System", m.getSystem(), edu.ncsu.csc.itrust.validate.ValidationFormat.LOINC_ITEM, true));
    errorList.addIfNotNull(this.checkFormat("ScaleType", m.getScaleType(), edu.ncsu.csc.itrust.validate.ValidationFormat.LOINC_ITEM, true));
    errorList.addIfNotNull(this.checkFormat("MethodType", m.getMethodType(), edu.ncsu.csc.itrust.validate.ValidationFormat.LOINC_ITEM, true));
    if (errorList.hasErrors()) {
        throw new edu.ncsu.csc.itrust.exception.FormValidationException(errorList);
    }
}

