public void addObstetricsRecord(edu.ncsu.csc.itrust.beans.ObstetricsRecordBean p) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        // first, insert the record
        // used to have OID, between MID and pregId (also VALUES had another ?,
        ps = conn.prepareStatement("INSERT INTO obstetrics(MID,pregId,LMP,EDD,weeksPregnant," + (("dateVisit,yearConception,hoursInLabor,deliveryType,pregnancyStatus," + "weight,bloodPressureS,bloodPressureD,FHR,FHU)") + " VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)"));
        ps = this.obstetricsLoader.loadParameters(ps, p);
        ps.executeUpdate();
        ps.close();
        // then, set the OID of the original bean to the one the database generates
        ps = conn.prepareStatement("SELECT * FROM obstetrics WHERE pregId=? ORDER BY oid DESC limit 1");// it will be the largest OID in the DB

        ps.setLong(1, p.getPregId());
        java.sql.ResultSet rs = ps.executeQuery();
        rs.first();
        p.setOid(rs.getLong("oid"));
    } catch (java.sql.SQLException e) {
        e.printStackTrace();
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

