    javax.servlet.http.HttpSession session = arg0.getSession();
    int mins = 20;
    try {
        mins = this.factory.getAccessDAO().getSessionTimeoutMins();
    } catch (edu.ncsu.csc.itrust.exception.DBException e) {
        java.lang.System.err.println("Unable to set session timeout, defaulting to 20 minutes");
