public java.lang.String acceptApptRequest(int reqID) throws java.sql.SQLException, edu.ncsu.csc.itrust.exception.DBException {
    edu.ncsu.csc.itrust.beans.ApptRequestBean req = this.arDAO.getApptRequest(reqID);
    if (req.isPending() && (!req.isAccepted())) {
        req.setPending(false);
        req.setAccepted(true);
        this.arDAO.updateApptRequest(req);
        this.aDAO.scheduleAppt(req.getRequestedAppt());
        try {
            edu.ncsu.csc.itrust.beans.MessageBean msg = this.constructMessage(req.getRequestedAppt(), req.isAccepted());
            this.msgAction.sendMessage(msg);
        } catch (java.lang.Exception e) {
            // TODO
        }
        return "The appointment request you selected has been accepted and scheduled.";
    } else {
        return "The appointment request you selected has already been acted upon.";
    }
}

