private void checkOverloadedMethods(T bean) {
    java.lang.reflect.Method[] methods = bean.getClass().getDeclaredMethods();
    java.util.HashMap<java.lang.String, java.lang.String> nameMap = new java.util.HashMap<java.lang.String, java.lang.String>(methods.length);
    for (java.lang.reflect.Method method : methods) {
        if (nameMap.get(method.getName()) != null) {
            throw new java.lang.IllegalArgumentException((bean.getClass().getName() + " should not have any overloaded methods, like ") + method.getName());
        }
        // allow an equals, compareTo override
        if (!("equals".equals(method.getName()) || "compareTo".equals(method.getName()))) {
            nameMap.put(method.getName(), "exists");
        }
    }
}

