public java.util.List<edu.ncsu.csc.itrust.beans.ApptBean> getNextAvailableAppts(int num, edu.ncsu.csc.itrust.beans.ApptBean bean) throws java.sql.SQLException, edu.ncsu.csc.itrust.exception.DBException {
    java.util.List<edu.ncsu.csc.itrust.beans.ApptBean> appts = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.ApptBean>(num);
    for (int i = 0; i < num; i++) {
        edu.ncsu.csc.itrust.beans.ApptBean b = new edu.ncsu.csc.itrust.beans.ApptBean();
        b.setApptType(bean.getApptType());
        b.setHcp(bean.getHcp());
        b.setPatient(bean.getPatient());
        b.setDate(new java.sql.Timestamp(bean.getDate().getTime()));
        java.util.List<edu.ncsu.csc.itrust.beans.ApptBean> conflicts = null;
        do {
            conflicts = this.aDAO.getAllHCPConflictsForAppt(b.getHcp(), b);
            if ((conflicts != null) && (!conflicts.isEmpty())) {
                edu.ncsu.csc.itrust.beans.ApptBean lastConflict = conflicts.get(conflicts.size() - 1);
                java.sql.Timestamp afterConflict = this.endTime(lastConflict);
                b.setDate(afterConflict);
            }
        } while (!conflicts.isEmpty() );
        appts.add(b);
        java.sql.Timestamp nextTime = this.endTime(b);
        bean.setDate(nextTime);
    }
    return appts;
}

public java.util.List<edu.ncsu.csc.itrust.beans.HospitalBean> getHospitalsAssignedToPhysician(long pid) throws java.sql.SQLException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    java.sql.ResultSet rs = null;
    java.util.List<java.lang.String> hosID = new java.util.ArrayList<java.lang.String>();
    java.util.List<edu.ncsu.csc.itrust.beans.HospitalBean> nameOfHospitals = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.HospitalBean>();
    edu.ncsu.csc.itrust.beans.loaders.HospitalBeanLoader loader = new edu.ncsu.csc.itrust.beans.loaders.HospitalBeanLoader();
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("Select hosID from hcpassignedhos where HCPID=?");
        ps.setString(1, java.lang.String.valueOf(pid));
        rs = ps.executeQuery();
        while (rs.next()) {
            hosID.add(rs.getString("hosID"));
        } 
        if (hosID.size() == 0) {
            return null;
        }
        for (java.lang.String string : hosID) {
            ps = conn.prepareStatement("select * from hospitals where hospitals.HospitalID=?");
            ps.setString(1, java.lang.String.valueOf(string));
            rs = ps.executeQuery();
            while (rs.next()) {
                nameOfHospitals.add(loader.loadSingle(rs));
            } 
        }
    } catch (java.sql.SQLException e) {
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
        if (rs != null) {
            try {
                rs.close();
            } catch (java.sql.SQLException e) {
            }
        }
    }
    return nameOfHospitals;
}

