public void sendMessage(edu.ncsu.csc.itrust.beans.MessageBean mBean) throws edu.ncsu.csc.itrust.exception.ITrustException, java.sql.SQLException, edu.ncsu.csc.itrust.exception.FormValidationException {
    this.messVal.validate(mBean);
    this.emailVal.validate(mBean);
    this.messageDAO.addMessage(mBean);
    edu.ncsu.csc.itrust.beans.Email email = new edu.ncsu.csc.itrust.beans.Email();
    java.lang.String senderName;
    java.lang.String fromEmail;
    email.setFrom("noreply@itrust.com");
    java.util.List<java.lang.String> toList = new java.util.ArrayList<java.lang.String>();
    if ((8999999999L < mBean.getFrom()) && (8999999999L < mBean.getTo())) {
        // when from and to are LHCPs
        edu.ncsu.csc.itrust.beans.PersonnelBean sender = this.personnelDAO.getPersonnel(this.loggedInMID);
        edu.ncsu.csc.itrust.beans.PersonnelBean receiver = this.personnelDAO.getPersonnel(mBean.getTo());
        toList.add(receiver.getEmail());
        senderName = sender.getFullName();
        fromEmail = sender.getEmail();
        email.setBody(java.lang.String.format("You have received a new message from %s in iTrust. To view it, go to \"http://localhost:8080/iTrust/auth/hcp/messageInbox.jsp\" and log in to iTrust using your username and password.", senderName));
    } else if (6999999999L < mBean.getFrom()) {
        edu.ncsu.csc.itrust.beans.PersonnelBean sender = this.personnelDAO.getPersonnel(this.loggedInMID);
        if (6999999999L < mBean.getTo()) {
            // when from is any personnel and to is any personnel
            edu.ncsu.csc.itrust.beans.PersonnelBean receiver = this.personnelDAO.getPersonnel(mBean.getTo());
            toList.add(receiver.getEmail());
            senderName = sender.getFullName();
            email.setBody(java.lang.String.format("You have received a new message from %s in iTrust. To view it, go to \"http://localhost:8080/iTrust/auth/hcp/messageInbox.jsp\" and log in to iTrust using your username and password.", senderName));
        } else {
            // when from is any personnel and to is patient
            edu.ncsu.csc.itrust.beans.PatientBean receiver = this.patientDAO.getPatient(mBean.getTo());
            toList.add(receiver.getEmail());
            senderName = sender.getFullName();
            email.setBody(java.lang.String.format("You have received a new message from %s in iTrust. To view it, go to \"http://localhost:8080/iTrust/auth/patient/messageInbox.jsp\" and log in to iTrust using your username and password.", senderName));
        }
        fromEmail = sender.getEmail();
    } else {
        edu.ncsu.csc.itrust.beans.PatientBean sender = this.patientDAO.getPatient(this.loggedInMID);
        if (6999999999L < mBean.getTo()) {
            // when from is patient and to is any personnel
            edu.ncsu.csc.itrust.beans.PersonnelBean receiver = this.personnelDAO.getPersonnel(mBean.getTo());
            toList.add(receiver.getEmail());
            senderName = sender.getFullName();
            email.setBody(java.lang.String.format("You have received a new message from %s in iTrust. To view it, go to \"http://localhost:8080/iTrust/auth/hcp/messageInbox.jsp\" and log in to iTrust using your username and password.", senderName));
        } else {
            // when from is patient and to is patient
            edu.ncsu.csc.itrust.beans.PatientBean receiver = this.patientDAO.getPatient(mBean.getTo());
            toList.add(receiver.getEmail());
            senderName = sender.getFullName();
            email.setBody(java.lang.String.format("You have received a new message from %s in iTrust. To view it, go to \"http://localhost:8080/iTrust/auth/patient/messageInbox.jsp\" and log in to iTrust using your username and password.", senderName));
        }
        fromEmail = sender.getEmail();
    }
    email.setToList(toList);
    email.setFrom(fromEmail);
    email.setSubject(java.lang.String.format("A new message from %s", senderName));
    this.emailer.sendEmail(email);
}

