private static boolean endBefore(java.util.Date startTime, java.util.Date endTime, int years, int months, int weeks) {
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.setTime(startTime);
    cal.add(java.util.Calendar.YEAR, years);
    cal.add(java.util.Calendar.MONTH, months);
    cal.add(java.util.Calendar.HOUR, (weeks * 7) * 24);
    return cal.getTime().compareTo(endTime) <= 0;
}

