@java.lang.SuppressWarnings("resource")
private boolean verifyCDCStatsCSV(java.io.InputStream healthStatsCSV) {
    // Create scanner to read each line of data in the csv
    java.util.Scanner csvScanner = new java.util.Scanner(healthStatsCSV, "UTF-8");
    // String for holding a line of data from the CSV file
    java.lang.String line = "";
    // Read the header line
    if (csvScanner.hasNextLine()) {
        line = csvScanner.nextLine();
    } else {
        csvScanner.close();
        // If the csv file does not contain a line, the csv file is incorrect
        return false;
    }
    // If the header line is incorrectly formatted then the csv file is incorrect
    if (!line.matches(edu.ncsu.csc.itrust.action.UploadReferenceTablesAction.headerFormat)) {
        csvScanner.close();
        return false;
    }
    // Verify that each consecutive line follows correct formatting
    while (csvScanner.hasNextLine()) {
        line = csvScanner.nextLine();
        // If none of the lines match a data line format nor a header line
        // format then the csv file is incorrect
        if ((!line.matches(edu.ncsu.csc.itrust.action.UploadReferenceTablesAction.statsDataFormat)) && (!line.matches(edu.ncsu.csc.itrust.action.UploadReferenceTablesAction.headerFormat))) {
            csvScanner.close();
            return false;
        }
    } 
    // The csv file passes the verification process it is deemed correct
    return true;
}

