public double getHeadCircZScore(edu.ncsu.csc.itrust.beans.HealthRecord record) throws edu.ncsu.csc.itrust.exception.DBException {
    // Get the CDCStatsBean for a patient's head circumference at his or her age
    edu.ncsu.csc.itrust.beans.CDCStatsBean statsBean = this.getCDCStatsBean(record, this.headCircStatsDAO);
    // If there is no matching entry in the CDC Stats table then return -999
    if (statsBean == null) {
        return -999;
    }
    // Get the head cirumference in centimeters
    double headCirc = record.getHeadCircumference() / edu.ncsu.csc.itrust.action.ViewHealthRecordsHistoryAction.INCHES_IN_CM;
    // Get the z score for the patient's head circumference
    double zScore = this.getZScore(statsBean, headCirc);
    return zScore;
}

