public int getPatientAgeInMonths() throws edu.ncsu.csc.itrust.exception.ITrustException {
    // Create int for patient's age in months
    int ageInMonths = 0;
    // Get the office visit date
    java.util.Calendar officeVisitDate = java.util.Calendar.getInstance();
    officeVisitDate.setTime(this.getOfficeVisit().getVisitDate());
    // Get the patient's birthdate
    java.util.Calendar birthDate = java.util.Calendar.getInstance();
    edu.ncsu.csc.itrust.beans.PatientBean patient = this.patientDAO.getPatient(this.pid);
    birthDate.setTime(patient.getDateOfBirth());
    // Split the patient's birthdate into day, month, and year
    int birthDay = birthDate.get(java.util.Calendar.DAY_OF_MONTH);
    int birthMonth = birthDate.get(java.util.Calendar.MONTH) + 1;
    int birthYear = birthDate.get(java.util.Calendar.YEAR);
    // Split the office visit date into day month and year
    int visitDay = officeVisitDate.get(java.util.Calendar.DAY_OF_MONTH);
    int visitMonth = officeVisitDate.get(java.util.Calendar.MONTH) + 1;
    int visitYear = officeVisitDate.get(java.util.Calendar.YEAR);
    // Calculate the year, month, and day differences
    int yearDiff = visitYear - birthYear;
    int monthDiff = visitMonth - birthMonth;
    int dayDiff = visitDay - birthDay;
    // Get the patient's age in months by multiplying the year difference by 12
    // and adding the month difference
    ageInMonths = (yearDiff * edu.ncsu.csc.itrust.action.ViewOfficeVisitAction.MONTHS_IN_YEAR) + monthDiff;
    // If the day difference is negative, subtract a month from the age
    if (dayDiff < 0) {
        ageInMonths -= 1;
    }
    // Return the age in months
    return ageInMonths;
}

