public void logTransaction(edu.ncsu.csc.itrust.enums.TransactionType type, long loggedInMID, long secondaryMID, java.lang.String addedInfo) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        ps = conn.prepareStatement("INSERT INTO transactionlog(loggedInMID, secondaryMID, " + "transactionCode, addedInfo) VALUES(?,?,?,?)");
        ps.setLong(1, loggedInMID);
        ps.setLong(2, secondaryMID);
        ps.setInt(3, type.getCode());
        ps.setString(4, addedInfo);
        ps.executeUpdate();
