private void parseFilters(javax.servlet.http.HttpServletRequest request) {
    boolean hasDeactivatedFilter = false;
    if ((request.getParameter("demoparams") != null) && (!request.getParameter("demoparams").isEmpty())) {
        java.lang.String demoparams = request.getParameter("demoparams");
        java.lang.String demoFilters[] = demoparams.split(" ");
        for (java.lang.String filter : demoFilters) {
            if ((request.getParameter(filter) != null) && (!request.getParameter(filter).isEmpty())) {
                edu.ncsu.csc.itrust.report.DemographicReportFilter.DemographicReportFilterType filterType = edu.ncsu.csc.itrust.report.DemographicReportFilter.filterTypeFromString(filter);
                if (filterType.toString().equals("DEACTIVATED")) {
                    hasDeactivatedFilter = true;
                }
                edu.ncsu.csc.itrust.report.DemographicReportFilter fil = new edu.ncsu.csc.itrust.report.DemographicReportFilter(filterType, request.getParameter(filter), this.factory);
                this.filters.add(fil);
            }
        }
    }
    if (!hasDeactivatedFilter) {
        this.filters.add(new edu.ncsu.csc.itrust.report.DemographicReportFilter(edu.ncsu.csc.itrust.report.DemographicReportFilter.filterTypeFromString("DEACTIVATED"), "exclude", this.factory));
    }
    if ((request.getParameter("medparams") != null) && (!request.getParameter("medparams").isEmpty())) {
        java.lang.String medparams = request.getParameter("medparams");
        java.lang.String medFilters[] = medparams.split(" ");
        for (java.lang.String filter : medFilters) {
            if ((request.getParameter(filter) != null) && (!request.getParameter(filter).isEmpty())) {
                edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType filterType = edu.ncsu.csc.itrust.report.MedicalReportFilter.filterTypeFromString(filter);
                if ((((((filterType == edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.DIAGNOSIS_ICD_CODE) || (filterType == edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.MISSING_DIAGNOSIS_ICD_CODE)) || (filterType == edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.ALLERGY)) || (filterType == edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.CURRENT_PRESCRIPTIONS)) || (filterType == edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.PASTCURRENT_PRESCRIPTIONS)) || (filterType == edu.ncsu.csc.itrust.report.MedicalReportFilter.MedicalReportFilterType.PROCEDURE)) {
                    java.lang.String[] vals = request.getParameterValues(filter);
                    for (java.lang.String val : vals) {
                        edu.ncsu.csc.itrust.report.MedicalReportFilter fil = new edu.ncsu.csc.itrust.report.MedicalReportFilter(filterType, val, this.factory);
                        this.filters.add(fil);
                    }
                } else {
                    edu.ncsu.csc.itrust.report.MedicalReportFilter fil = new edu.ncsu.csc.itrust.report.MedicalReportFilter(filterType, request.getParameter(filter), this.factory);
                    this.filters.add(fil);
                }
            }
        }
    }
    if ((request.getParameter("persparams") != null) && (!request.getParameter("persparams").isEmpty())) {
        java.lang.String persparams = request.getParameter("persparams");
        java.lang.String personnelFilters[] = persparams.split(" ");
        for (java.lang.String filter : personnelFilters) {
            if ((request.getParameter(filter) != null) && (!request.getParameter(filter).isEmpty())) {
                edu.ncsu.csc.itrust.report.PersonnelReportFilter.PersonnelReportFilterType filterType = edu.ncsu.csc.itrust.report.PersonnelReportFilter.filterTypeFromString(filter);
                if (filterType == edu.ncsu.csc.itrust.report.PersonnelReportFilter.PersonnelReportFilterType.DLHCP) {
                    java.lang.String[] vals = request.getParameterValues(filter);
                    for (java.lang.String val : vals) {
                        edu.ncsu.csc.itrust.report.PersonnelReportFilter fil = new edu.ncsu.csc.itrust.report.PersonnelReportFilter(filterType, val, this.factory);
                        this.filters.add(fil);
                    }
                } else {
                    edu.ncsu.csc.itrust.report.PersonnelReportFilter fil = new edu.ncsu.csc.itrust.report.PersonnelReportFilter(filterType, request.getParameter(filter), this.factory);
                    this.filters.add(fil);
                }
            }
        }
    }
}

