private java.util.List<edu.ncsu.csc.itrust.beans.TransactionBean> addAndSortRoles(java.util.List<edu.ncsu.csc.itrust.beans.TransactionBean> tbList, long patientID, boolean sortByRole) throws edu.ncsu.csc.itrust.exception.DBException {
    java.sql.Connection conn = null;
    java.sql.PreparedStatement ps = null;
    try {
        conn = this.factory.getConnection();
        for (edu.ncsu.csc.itrust.beans.TransactionBean t : tbList) {
            ps = conn.prepareStatement("SELECT Role FROM users WHERE MID=?");
            ps.setLong(1, t.getLoggedInMID());
            java.sql.ResultSet rs = ps.executeQuery();
            java.lang.String role = "";
            if (rs.next()) {
                role = rs.getString("Role");
            }
            if (role.equals("er")) {
                role = "Emergency Responder";
            } else if (role.equals("uap")) {
                role = "UAP";
            } else if (role.equals("hcp")) {
                role = "LHCP";
                ps.close();
                ps = conn.prepareStatement("SELECT PatientID FROM declaredhcp WHERE HCPID=?");
                ps.setLong(1, t.getLoggedInMID());
                java.sql.ResultSet rs2 = ps.executeQuery();
                while (rs2.next()) {
                    if (rs2.getLong("PatientID") == patientID) {
                        role = "DLHCP";
                        break;
                    }
                } 
                rs2.close();
            } else if (role.equals("patient")) {
                role = "Patient";
                ps.close();
                ps = conn.prepareStatement("SELECT representeeMID FROM representatives WHERE representerMID=?");
                ps.setLong(1, t.getLoggedInMID());
                java.sql.ResultSet rs2 = ps.executeQuery();
                while (rs2.next()) {
                    if (rs2.getLong("representeeMID") == patientID) {
                        role = "Personal Health Representative";
                        break;
                    }
                } 
                rs2.close();
            }
            t.setRole(role);
            rs.close();
            ps.close();
        }
        if (sortByRole) {
            edu.ncsu.csc.itrust.beans.TransactionBean[] array = new edu.ncsu.csc.itrust.beans.TransactionBean[tbList.size()];
            array[0] = tbList.get(0);
            edu.ncsu.csc.itrust.beans.TransactionBean t;
            for (int i = 1; i < tbList.size(); i++) {
                t = tbList.get(i);
                java.lang.String role = t.getRole();
                int j = 0;
                while ((array[j] != null) && (role.compareToIgnoreCase(array[j].getRole()) >= 0)) {
                    j++;
                } 
                for (int k = i; k > j; k--) {
                    array[k] = array[k - 1];
                }
                array[j] = t;
            }
            int size = tbList.size();
            for (int i = 0; i < size; i++) {
                tbList.set(i, array[i]);
            }
        }
        return tbList;
    } catch (java.sql.SQLException e) {
        throw new edu.ncsu.csc.itrust.exception.DBException(e);
    } finally {
        edu.ncsu.csc.itrust.DBUtil.closeConnection(conn, ps);
    }
}

