private java.util.List<java.lang.String> checkAllergy(edu.ncsu.csc.itrust.beans.PrescriptionBean pres) throws edu.ncsu.csc.itrust.exception.ITrustException, edu.ncsu.csc.itrust.exception.PrescriptionWarningException {
    java.util.ArrayList<java.lang.String> warnings = new java.util.ArrayList<java.lang.String>();
    try {
        java.util.List<edu.ncsu.csc.itrust.beans.AllergyBean> allergyList = this.allergyDAO.getAllergies(this.getPid());
        edu.ncsu.csc.itrust.beans.MedicationBean medBean = pres.getMedication();
        if (medBean != null) {
            java.lang.String newDrug = medBean.getNDCode();
            for (edu.ncsu.csc.itrust.beans.AllergyBean allergyBean : allergyList) {
                // Allergy: Aspirin. First Found: 12/20/2008.
                if (newDrug.equals(allergyBean.getNDCode())) {
                    warnings.add(this.formatAllergyWarning(allergyBean));
