@java.lang.Override
public java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> filter(java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> patients) {
    java.util.List<edu.ncsu.csc.itrust.beans.PatientBean> prunedList = new java.util.ArrayList<edu.ncsu.csc.itrust.beans.PatientBean>();
    boolean add = (this.filterValue != null) && (!this.filterValue.isEmpty());
    if (add) {
        for (edu.ncsu.csc.itrust.beans.PatientBean patient : patients) {
            add = false;
            switch (this.filterType) {
                case ALLERGY :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.AllergyBean> allergies = this.aDAO.getAllergies(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.AllergyBean allergy : allergies) {
                            if (this.filterValue.equalsIgnoreCase(allergy.getNDCode())) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case CURRENT_PRESCRIPTIONS :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.PrescriptionBean> prescriptions = this.pDAO.getCurrentPrescriptions(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.PrescriptionBean prescription : prescriptions) {
                            if (this.filterValue.equalsIgnoreCase(prescription.getMedication().getNDCode()) || this.filterValue.equalsIgnoreCase(prescription.getMedication().getNDCodeFormatted())) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case DIAGNOSIS_ICD_CODE :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.DiagnosisBean> diagnoses = this.pDAO.getDiagnoses(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.DiagnosisBean diagnosis : diagnoses) {
                            if (this.filterValue.equalsIgnoreCase(diagnosis.getICDCode())) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case PASTCURRENT_PRESCRIPTIONS :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.PrescriptionBean> prescriptions = this.pDAO.getPrescriptions(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.PrescriptionBean prescription : prescriptions) {
                            if (this.filterValue.equalsIgnoreCase(prescription.getMedication().getNDCode()) || this.filterValue.equalsIgnoreCase(prescription.getMedication().getNDCodeFormatted())) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case PROCEDURE :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.ProcedureBean> procedures = this.pDAO.getProcedures(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.ProcedureBean procedure : procedures) {
                            if (this.filterValue.equalsIgnoreCase(procedure.getCPTCode())) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case MISSING_DIAGNOSIS_ICD_CODE :
                    try {
                        java.util.List<edu.ncsu.csc.itrust.beans.DiagnosisBean> diagnoses = this.pDAO.getDiagnoses(patient.getMID());
                        add = true;
                        for (edu.ncsu.csc.itrust.beans.DiagnosisBean diagnosis : diagnoses) {
                            if (this.filterValue.equalsIgnoreCase(diagnosis.getICDCode())) {
                                add = false;
                                break;
                            }
                        }
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case LOWER_OFFICE_VISIT_DATE :
                    try {
                        java.text.SimpleDateFormat frmt = new java.text.SimpleDateFormat("MM/dd/yyyy");
                        java.util.Date d = frmt.parse(this.filterValue);
                        java.util.List<edu.ncsu.csc.itrust.beans.OfficeVisitBean> visits = this.oDAO.getAllOfficeVisits(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.OfficeVisitBean visit : visits) {
                            if (d.compareTo(visit.getVisitDate()) <= 0) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.RuntimeException e) {
                        break;
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                case UPPER_OFFICE_VISIT_DATE :
                    try {
                        java.text.SimpleDateFormat frmt = new java.text.SimpleDateFormat("MM/dd/yyyy");
                        java.util.Date d = frmt.parse(this.filterValue);
                        java.util.List<edu.ncsu.csc.itrust.beans.OfficeVisitBean> visits = this.oDAO.getAllOfficeVisits(patient.getMID());
                        for (edu.ncsu.csc.itrust.beans.OfficeVisitBean visit : visits) {
                            if (d.compareTo(visit.getVisitDate()) >= 0) {
                                add = true;
                                break;
                            }
                        }
                    } catch (java.lang.RuntimeException e) {
                        break;
                    } catch (java.lang.Exception e) {
                        break;
                    }
                    break;
                default :
                    break;
            }
            if (add) {
                prunedList.add(patient);
            }
        }
    }
    return prunedList;
}

