public static java.util.HashMap<java.lang.String, java.lang.String> convertMap(java.util.Map<? extends java.lang.Object, ? extends java.lang.Object> params) {
    java.util.HashMap<java.lang.String, java.lang.String> myMap = new java.util.HashMap<java.lang.String, java.lang.String>();
    for (java.util.Map.Entry<? extends java.lang.Object, ? extends java.lang.Object> entry : params.entrySet()) {
        java.lang.String[] value = ((java.lang.String[]) (entry.getValue()));
        if (value != null) {
            myMap.put(entry.getKey().toString(), value[0]);
        } else {
            myMap.put(entry.getKey().toString(), null);
        }
    }
    return myMap;
}

