            temp.setStreetAddress1(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("streetAddress1")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            temp.setStreetAddress2(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("streetAddress2")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            temp.setCity(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("city")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            temp.setState(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("state")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            temp.setZip(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("zip")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            temp.setPhone(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("phone")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            temp.setMotherMID(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("motherMID")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            temp.setFatherMID(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("fatherMID")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            temp.setCreditCardType(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("creditCardType")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            temp.setCreditCardNumber(this.CSVData.get(i).get(this.validFieldsMapping[java.util.Arrays.asList(this.validFields).indexOf("creditCardNumber")]));
        } catch (java.lang.NullPointerException e) {
            // TODO
        }
        try {
            new edu.ncsu.csc.itrust.validate.AddPatientValidator().validate(temp);
            new edu.ncsu.csc.itrust.validate.PatientValidator().validate(temp);
            if (this.patientDAO != null) {
                long newMID = this.patientDAO.addEmptyPatient();
                temp.setMID(newMID);
