public java.lang.String changePassword(long mid, java.lang.String oldPass, java.lang.String newPass, java.lang.String confirmPass) throws edu.ncsu.csc.itrust.exception.FormValidationException, edu.ncsu.csc.itrust.exception.DBException, edu.ncsu.csc.itrust.exception.ITrustException {
    java.lang.String containsLetter = "[a-zA-Z0-9]*[a-zA-Z]+[a-zA-Z0-9]*";
    java.lang.String containsNumber = "[a-zA-Z0-9]*[0-9]+[a-zA-Z0-9]*";
    java.lang.String fiveAlphanumeric = "[a-zA-Z0-9]{5,20}";
    // Make sure old password is valid
    if (!this.authDAO.authenticatePassword(mid, oldPass)) {
        return "Invalid password change submission.";
    }
    // Make sure new passwords match
    if (!newPass.equals(confirmPass)) {
        return "Invalid password change submission.";
    }
    // Validate password. Must contain a letter, contain a number, and be a string of 5-20 alphanumeric characters
    if ((newPass.matches(containsLetter) && newPass.matches(containsNumber)) && newPass.matches(fiveAlphanumeric)) {
        // Change the password
        this.authDAO.resetPassword(mid, newPass);
        return "Password Changed.";
    } else {
        return "Invalid password change submission.";
    }
}

