public java.lang.String declareHCP(java.lang.String name) throws edu.ncsu.csc.itrust.exception.ITrustException {
    boolean match = false;
    for (edu.ncsu.csc.itrust.beans.HCPVisitBean visit : this.getVisitedHCPs()) {
        if (0 == visit.getHCPName().toLowerCase().compareTo(name.toLowerCase())) {
            match = true;
            java.lang.Long mid = java.lang.Long.valueOf(visit.getHCPMID());
            if (!this.patientDAO.checkDeclaredHCP(this.patientMID, visit.getHCPMID())) {
                this.declareAction.declareHCP(mid.toString());
            }
            visit.setDesignated(true);
        }
    }
    if (!match) {
        java.util.List<edu.ncsu.csc.itrust.beans.PersonnelBean> doclist = this.docDAO.getAllPersonnel();
        for (edu.ncsu.csc.itrust.beans.PersonnelBean ele : doclist) {
            if (0 == name.compareTo(ele.getFullName())) {
                edu.ncsu.csc.itrust.beans.HCPVisitBean visitBean;
                visitBean = new edu.ncsu.csc.itrust.beans.HCPVisitBean();
                visitBean.setHCPMID(ele.getMID());
                visitBean.setHCPName(ele.getFullName());
                visitBean.setOVDate("");
                visitBean.setHCPSpecialty(ele.getSpecialty());
                visitBean.setHCPAddr((((((((ele.getStreetAddress1() + " ") + ele.getStreetAddress2()) + " ") + ele.getCity()) + ", ") + ele.getState()) + " ") + ele.getZip());
                visitBean.setDesignated(true);
                java.lang.Long mid = java.lang.Long.valueOf(ele.getMID());
                if (!this.patientDAO.checkDeclaredHCP(this.patientMID, mid)) {
                    this.declareAction.declareHCP(mid.toString());
                }
            }
        }
    }
    return "";
}

