public java.lang.String getMessageAsSentence(java.lang.String actor, java.sql.Timestamp timestamp, edu.ncsu.csc.itrust.enums.TransactionType code) {
    java.lang.String result = actor + " ";
    java.lang.StringBuffer buf = new java.lang.StringBuffer();
    for (edu.ncsu.csc.itrust.enums.TransactionType type : edu.ncsu.csc.itrust.enums.TransactionType.values()) {
        if ((code.getCode() == type.getCode()) && type.isPatientViewable()) {
            buf.append(type.getActionPhrase());
        }
    }
    result += buf.toString();
    java.text.SimpleDateFormat formatter = new java.text.SimpleDateFormat("h:mma.");
    switch (edu.ncsu.csc.itrust.action.ActivityFeedAction.recent(new java.util.Date(timestamp.getTime()))) {
        case 0 :
            result += " today";
            break;
        case 1 :
            result += " yesterday";
            break;
        case 2 :
            java.text.DateFormat sdf = new java.text.SimpleDateFormat("MM/dd/yyyy");
            result += " on " + sdf.format(new java.util.Date(timestamp.getTime()));
            break;
        default :
            break;
    }
    result += " at " + formatter.format(timestamp);
    return this.replaceNameWithYou(result);
}

