private void loadCommon(java.sql.ResultSet rs, edu.ncsu.csc.itrust.beans.ObstetricsRecordBean p) throws java.sql.SQLException {
    p.setMid(rs.getLong("mid"));
    p.setOid(rs.getLong("oid"));// this sets the return bean

    p.setPregId(rs.getLong("pregId"));
    try {
        p.setLmp(new java.text.SimpleDateFormat("MM/dd/yyyy").format(new java.sql.Date(rs.getDate("lmp").getTime())));
    } catch (java.lang.NullPointerException e) {
        // totally fine. It just means it wasn't set in the record we grabbed, so don't worry.
    }
    try {
        p.setEdd(new java.text.SimpleDateFormat("MM/dd/yyyy").format(new java.sql.Date(rs.getDate("edd").getTime())));
    } catch (java.lang.NullPointerException e) {
        // totally fine. It just means it wasn't set in the record we grabbed, so don't worry.
    }
    p.setWeeksPregnant(rs.getString("weeksPregnant"));
    // this one, however, unlike the others above, should throw an NPE if it gets through because EVERY record has this one set
    p.setDateVisit(new java.text.SimpleDateFormat("MM/dd/yyyy").format(new java.sql.Date(rs.getDate("dateVisit").getTime())));
    p.setYearConception(rs.getInt("yearConception"));
    p.setHoursInLabor(rs.getDouble("hoursInLabor"));
    p.setDeliveryType(edu.ncsu.csc.itrust.enums.DeliveryType.valueOf(rs.getString("deliveryType").split("[ ]")[0]));
    p.setPregnancyStatus(edu.ncsu.csc.itrust.enums.PregnancyStatus.valueOf(rs.getString("pregnancyStatus").split("[ ]")[0]));
    p.setWeight(rs.getDouble("weight"));
    p.setBloodPressureS(rs.getInt("bloodPressureS"));
    p.setBloodPressureD(rs.getInt("bloodPressureD"));
    p.setFhr(rs.getInt("fhr"));
    p.setFhu(rs.getDouble("fhu"));
}

