public static java.lang.String testHepB(int count, java.util.Date patientDOB, long time) {
    java.lang.String reason = "";
    long weeks = (java.util.Calendar.getInstance().getTimeInMillis() - time) / edu.ncsu.csc.itrust.action.GetVisitRemindersAction.WEEK_IN_MILLIS;
    if (0 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 0, 0)) {
            reason += "90371 Hepatitis B (birth), ";
        }
    } else if (1 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 1, 0) && (4 <= weeks)) {
            reason += "90371 Hepatitis B (1 month), ";
        }
    } else if (2 == count) {
        if (edu.ncsu.csc.itrust.action.GetVisitRemindersAction.olderThan(patientDOB, 0, 6, 0) && (8 <= weeks)) {
            reason += "90371 Hepatitis B (6 months), ";
        }
    }
    return reason;
}

