public void loadFile(java.io.InputStream fileContent, edu.ncsu.csc.itrust.dao.DAOFactory factory, edu.ncsu.csc.itrust.action.EventLoggingAction loggingAction, long loggedInMID) throws java.io.IOException, edu.ncsu.csc.itrust.exception.DBException {
    edu.ncsu.csc.itrust.dao.mysql.NDCodesDAO ndcodesDAO = factory.getNDCodesDAO();
    java.util.Scanner fileScanner = new java.util.Scanner(fileContent, "UTF-8");
    while (fileScanner.hasNextLine()) {
        java.lang.String ndCodeWithDash;
        edu.ncsu.csc.itrust.beans.MedicationBean bean = new edu.ncsu.csc.itrust.beans.MedicationBean();
        java.util.StringTokenizer tok = new java.util.StringTokenizer(fileScanner.nextLine(), "\t");
        ndCodeWithDash = tok.nextToken();
        java.lang.String parts[] = ndCodeWithDash.split("-");
        // Skip drug type field
        tok.nextToken();
        bean.setNDCode(parts[0].concat(parts[1]));
        bean.setDescription(tok.nextToken());
        try {
            ndcodesDAO.addNDCode(bean);
            loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.DRUG_CODE_ADD, loggedInMID, 0, (("" + bean.getNDCode()) + " - ") + bean.getDescription());
        } catch (edu.ncsu.csc.itrust.exception.ITrustException e) {
            // Overwrite duplicate entries
            ndcodesDAO.updateCode(bean);
            loggingAction.logEvent(edu.ncsu.csc.itrust.enums.TransactionType.DRUG_CODE_EDIT, loggedInMID, 0, (("" + bean.getNDCode()) + " - ") + bean.getDescription());
        }
    } 
    fileScanner.close();
}

